#!/usr/bin/env bash
#
# session-warden.sh — надзиратель сессий: ротация по заполнению окна и тишине.
#
# Что держит: правило «сессия не доживает до авто-компакта» (UNIFIED/13,
# И-инварианты карты носителей). Контекст, пережатый компактом больше
# MAX_COMPACTS раз, теряет решения владельца; сессия, молчащая при непустой
# очереди, — потерянные часы. Оба отказа должен ловить механизм, не внимание.
#
# Откуда взят: собран для стартового пакета по нормам UNIFIED/13 (ротация)
# и UNIFIED/08 (мягкий отказ оставляет след); приём «фоновый claude -p без
# MCP-серверов» — улика из devmap-selfheal.sh: telegram-плагин допускает
# одного потребителя getUpdates и убивает живой канал, поэтому headless-вызовы
# здесь идут строго со --strict-mcp-config и пустым набором серверов.
#
# Чем доказывается: МЕХАНИКА ЗАМЕРА ОКНА — ЭВРИСТИКА (байты JSONL ≈ окно),
# доказывается принудительной ротацией на этапе приёмки (03-ЗАДАНИЕ §первая
# ротация): порог CTX_WINDOW_BYTES калибруется по живому замеру и вписывается
# в harness.conf. Тишина и режимы semi/full доказываются больными случаями
# при установке (01-SPEC §9).
#
# Запуск: cron, каждые 10 минут, от имени $AGENT_USER. Лог — в stdout,
# cron перенаправляет в $LOG_DIR/session-warden.log.
set -euo pipefail

# Каталог скриптов харнеса — от пути САМОГО демона, а не от PROJECT_DIR: в
# пакете демон лежит под harness/, после раскладки — в корне проекта, а
# самотест идёт РАНЬШЕ загрузки паспорта, и обращение к PROJECT_DIR роняло его
# под `set -u` (живой прогон 14.09.2026, после снятия умолчания с чужим путём).
WARDEN_HOME="$(dirname "$(readlink -f "${BASH_SOURCE[0]}")")"
HARNESS_SCRIPTS="$WARDEN_HOME/../../scripts"
[ -d "$HARNESS_SCRIPTS" ] || HARNESS_SCRIPTS="$WARDEN_HOME/../scripts"

say() { printf '%s  %s\n' "$(date '+%Y-%m-%d %H:%M:%S')" "$*"; }

# ── доставка текста в панель агента ─────────────────────────────────────────
# Копия функции из scripts/tg-dispatcher.sh — оба скрипта самодостаточны
# (демон и сервис живут в разных каталогах и не имеют общей библиотеки).
# Улика 11.08.2026: `tmux send-keys -t сессия "$текст" Enter` теряет текст
# двумя способами. Без -l tmux разбирает аргумент как ИМЯ КЛАВИШИ, если оно
# совпало: пинок со словом «Enter» стал нажатием Enter, а «C-c» оборвал бы
# сессию агента. И одним вызовом финальный Enter теряется — TUI ещё разбирает
# вставку и нажатия не видит, текст остаётся в строке ввода непосланным.
# Переводы строки — в пробел: в TUI каждый \n это отправка.
# Нажатия в панель агента и признак «кто в панели» — ОБЩЕЙ дверью
# (scripts/lib/pane.sh). Эти семь строк лежали побайтово равной копией здесь и
# в диспетчере канала, а третьей копией стали бы у ежеминутного сторожа лимита;
# подключается ВЫШЕ самотеста, потому что самотест их и зовёт.
source "$HARNESS_SCRIPTS/lib/pane.sh"

# ── диалог «Background work is running» перехватывает «/exit» ───────────────
# Улика 09.09.2026 (снимок владельца): «/exit» подан, а вместо выхода — вопрос
# с тремя пунктами и «Enter to confirm». Владелец терминала не видит, нажать
# некому: сессия висела, преемник не поднимался, сторож будил владельца зря.
# Пункт 1 («Exit and stop tasks») выбран по умолчанию, и он же верный: НАСТОЯЩАЯ
# долгая работа идёт через `setsid nohup` (этого требует guard_bash) и выходу не
# подчиняется вовсе. Гибнут только задачи самой сессии — ожидания, которые она и
# так не переживёт.
# Признак — ТРИ строки разом, включая приглашение подтвердить: одна строка
# встречается и в отчёте агента про этот самый случай, а слепой Enter в панель
# подтвердил бы чужой вопрос.
# Маркер выбранного пункта в меню Claude Code — «❯», а НЕ «>». Улика
# 11.09.2026: за ротацию 02:00 сторож не распознал диалог ни разу (ноль записей
# rotate_exit_dialog при поданном «/exit»), владелец вышел руками. Причина —
# образец экрана в самотесте был ВЫДУМАН со знаком «>», живой снимок панели дал
# байты e2 9d af. Чередование, а не класс [..]: в локали C класс распался бы на
# отдельные байты и ловил бы любой знак с байтом 0xe2 ([[a-check-creates-its-own-condition]]).
# «>» оставлен законным: он приходит из ASCII-режима терминала.
PICK_MARK='(>|❯|▶)'
RE_EXIT_ITEM="^[[:space:]]*${PICK_MARK}?[[:space:]]*[0-9]+\\.[[:space:]]+Exit and stop tasks"
RE_PICKED_ITEM="^[[:space:]]*${PICK_MARK}[[:space:]]*[0-9]+\\."
RE_BACKGROUND_ITEM="^[[:space:]]*${PICK_MARK}?[[:space:]]*[0-9]+\\.[[:space:]]+Move to background"

диалог_выхода_в() {  # $1 = текст панели
    # Признак — ТРИ СТРОКИ по своим местам, а не три подстроки где попало.
    # Ревью 10.09.2026: подстрочный признак срабатывал на самом файле сторожа
    # (в нём лежит образец экрана для самотеста) — стоило агенту открыть или
    # сгрепать session-warden.sh во время ротации, и сторож слал Escape в живую
    # сессию, обрывая ход. Пункт ищем как пункт: «N. Exit and stop tasks» в
    # начале строки, возможно под стрелкой выбора.
    printf '%s\n' "$1" | grep -qE '^[[:space:]]*Background work is running[[:space:]]*$' \
        && printf '%s\n' "$1" | grep -qE "$RE_EXIT_ITEM" \
        && printf '%s\n' "$1" | grep -qE '^[[:space:]]*Enter to confirm'
}

диалог_выхода_жив() {  # $1 = текст панели, $2 = команда панели
    # ТЕКСТА НА ЭКРАНЕ МАЛО. tmux показывает застывший хвост вышедшей сессии:
    # после выхода агента в панели остаются и «Background work is running», и
    # подсвеченный пункт, и «Enter to confirm» — вместе со строкой «Resume this
    # session with». Признак по одному тексту истинен, когда диалога уже нет
    # ([[a-sign-true-while-work-stands-still]]).
    # УЛИКА 21.09.2026: claude вышел с первого Enter в 11:54, а сторож ещё 17
    # раз слал клавиши в голую оболочку — «1: command not found», «2: command
    # not found». Последний Escape повис в readline и съел первую букву
    # команды подъёма: «laude --model …». Работа стояла 27 минут.
    pane_is_agent "$2" && диалог_выхода_в "$1"
}

# ── лимит подписки исчерпан: работа встала, а панель жива ───────────────────
# Задача владельца 11.09.2026: «Допустим сейчас опять лимиты закончились, я об
# этом не знаю, после их обновления работа сама не запустится».
# Признак НАРОЧНО широкий и двойной. Точного текста CLI при исчерпании лимита я
# не наблюдал — в транскриптах следов нет, — а выдумывать чужой вывод я уже
# пробовал: так родилась слепота к «❯» ([[cli-menu-marker-is-not-a-caret]]).
# Поэтому: слово limit рядом со словом о сбросе/исчерпании В ПАНЕЛИ — это лишь
# половина; вторая половина (немота транскрипта) проверяется вызывающим. Одна
# без другой ничего не значит: про лимит пишу в отчётах и я сам.
# Когда случай произойдёт, журнал сохранит экран дословно — тогда признак можно
# будет сузить по улике, а не по догадке.
# Грепать ТЕМ ЖЕ выражением, что и признак: по одному слову «limit» в панели
# первой находится строка приглашения оболочки, и владелец получил бы в канал
# свою же команду вместо времени сброса (проба 11.09.2026).
# Образец снят с ЖИВОГО экрана: владелец прислал снимок 11.09.2026, и он
# показал, что прежний признак не сработал бы. Настоящая строка CLI:
#   You've hit your session limit · resets 2:50pm (Asia/Qostanay)
#   /upgrade to increase your usage limit.
# Прежний образец требовал слова «reached» или «resets» СРАЗУ после «limit», а
# там между ними « · ». Теперь ждём: «hit your … limit», «limit» рядом с
# reached/exceeded/resets в пределах строки, «/upgrade …» — и не выдумываем.
LIMIT_RE='(hit|reached|exceeded)[^\n]{0,40}limit|limit[^\n]{0,20}(reached|exceeded|resets?|will reset)|out of (usage|credits)|/upgrade (to|or)|upgrade to continue'
признак_лимита_в() {  # $1 = текст панели
    printf '%s\n' "$1" | grep -qiE "$LIMIT_RE"
}

# Строка про лимит целиком — владельцу нужно ВРЕМЯ сброса, а его печатает CLI.
строка_лимита_в() { # $1 = текст панели
    printf '%s\n' "$1" \
        | grep -m1 -iE "$LIMIT_RE" \
        | sed 's/^[[:space:]]*//' | cut -c1-200 || true
}

# Когда обновится лимит — по ЖУРНАЛУ сессии: «<минут>\t<в HH:MM, через N мин>».
# Пусто — записей отказа нет или прибор не смог.
#
# Спрашивать журнал позволено ТОЛЬКО при доказанном свежем отказе: прежняя
# редакция звала разбор на всём файле, и он находил «429» внутри обычного JSON и
# цитату собственного исходника сторожа — лимит объявлялся почти всегда
# (CRITICAL-1 ревью 27.09.2026). Время берётся числом из поля `resetsAt`, а не
# разбором человеческой строки, и потому сообщение владельцу больше не может
# распухнуть до 15 КБ и быть отвергнутым сторожем канала (CRITICAL-2).
сброс_по_журналу() { # $1 = транскрипт
    local vyvod kod
    [ -n "${1:-}" ] || return 0
    vyvod=$(python3 "$HARNESS_SCRIPTS/limit-in-log.py" --сброс "$1" 2>/dev/null)
    kod=$?
    # Код 2 — «файл не прочитан», это не «лимита нет»: молчать о непрочитанном
    # источнике значит красить проверку зелёным ([[unreadable-source-turns-check-green]]).
    [ "$kod" = 2 ] && { say "журнал сессии не прочитан прибором лимита — времени сброса не знаю"; return 0; }
    [ "$kod" = 0 ] || return 0
    printf '%s' "$vyvod"
}

# Глушить ли пинок: всё решение одним местом, чтобы его судила проба, а не
# текст файла. Владелец 27.09.2026: «если известно когда лимит обновится, можно
# пнуть в то время»; 30.10.2026 уточнил: одно сообщение о лимите, тишина до
# обновления, подъём в момент сброса. Срок назван — молчим: судья лимита
# (limit_active) уже сказал, что подъём впереди, и пинок до него стоит смене
# нового отказа.
глушить_пинок() { # $1=лимит держится(0/1), $2=подъём unix (пусто — срок неизвестен), $3=возраст немоты/пинка, мин
    # Лимит не доказан — глушить нечего: это обычная немота, и её будят как прежде.
    [ "${1:-0}" = 1 ] || return 1
    [ -z "${2:-}" ] || return 0
    # ПРЕДОХРАНИТЕЛЬ только для неизвестного срока: молчать вечно нельзя, раз в
    # LIMIT_KICK_MAX_MIN смена будится в любом случае.
    [ "${3:-9999}" -lt "${LIMIT_KICK_MAX_MIN:-60}" ]
}

# Единый ответ на «держится ли лимит подписки», один на обход (scripts/limit-in-log.py
# --действует): ветки 6, 6в и 6б спрашивают ЕГО, а не считают каждая по-своему.
# Выход: LIMIT_ACTIVE (0/1), LIMIT_RESET и LIMIT_WAKE (unix; пусто — срок не назван),
# LIMIT_REFUSED (0/1) — был машинный отказ 429, а не одна заметка CLI.
limit_active() {
    local out rc=0
    LIMIT_ACTIVE=0 LIMIT_RESET="" LIMIT_WAKE="" LIMIT_REFUSED=0
    [ -f "${TRANSCRIPT:-}" ] || return 0
    out=$(python3 "$HARNESS_SCRIPTS/limit-in-log.py" --действует "$TRANSCRIPT" --метка --с-отказом 2>/dev/null) || rc=$?
    # Код 1 — лимит не держится; любой иной (сбой прибора) не должен глушить сторожа.
    [ "$rc" = 0 ] || return 0
    LIMIT_ACTIVE=1
    LIMIT_RESET=$(printf '%s' "$out" | cut -f2)
    LIMIT_WAKE=$(printf '%s' "$out" | cut -f3)
    LIMIT_REFUSED=$(printf '%s' "$out" | cut -f4)
}

# Фраза журнала про лимит: час сброса 24-часовой либо честное «срок не назван».
limit_until_text() {
    if [ -n "${LIMIT_RESET:-}" ]; then printf 'лимит до %s' "$(date -d "@$LIMIT_RESET" +%H:%M)"
    else printf 'лимит (срок не назван)'; fi
}

# Через сколько лимит обновится — задача владельца 11.09.2026: «сделай чтобы он
# еще сообщал через сколько времени лимиты обновятся». Время сброса печатает
# САМ CLI в строке панели («resets 6pm», «resets at 18:00»); мы его только
# разбираем и считаем остаток. Не назвал — так и говорим, без выдумки: врать
# про срок хуже, чем промолчать.
через_сколько_сброс() { # $1 = строка панели; печатает «в 18:00, через 47 мин»
    printf '%s\n' "$1" | python3 -c '
import datetime, re, sys
строка = sys.stdin.read()
м = re.search(r"resets?(?:\s+at)?\s+(\d{1,2})(?::(\d{2}))?\s*(am|pm)?", строка, re.I)
if not м:
    sys.exit(1)
час = int(м.group(1)); минута = int(м.group(2) or 0); половина = (м.group(3) or "").lower()
if половина == "pm" and час != 12:
    час += 12
elif половина == "am" and час == 12:
    час = 0
if час > 23:
    sys.exit(1)
сейчас = datetime.datetime.now()
сброс = сейчас.replace(hour=час, minute=минута, second=0, microsecond=0)
if сброс <= сейчас:                      # названо время следующих суток
    сброс += datetime.timedelta(days=1)
осталось = int((сброс - сейчас).total_seconds() // 60)
часы, мин = divmod(осталось, 60)
сколько = f"{часы} ч {мин} мин" if часы else f"{мин} мин"
print(f"в {сброс:%H:%M}, через {сколько}")
' 2>/dev/null
}

# Немота ИМЕННО АГЕНТА: mtime транскрипта для этого не годится. 11.09.2026
# работа стояла 2 ч 10 мин (три паузы: 47, 50 и 32 минуты), а файл всё это
# время обновлялся — в него пишутся ВХОДЯЩИЕ: сообщения владельца, пинки
# сторожа, вложения. STALL_MIN был около нуля, ветка не входила ни разу, и
# владелец узнал об остановке сам. Возраст считается по последней записи
# type=assistant — по тому, что написал сам агент.
# Пинки не помогли — сказать ВЛАДЕЛЬЦУ. Улика 12.09.2026: агент работал и не
# отчитывался 180 минут, сторож честно пинал его восемнадцать раз подряд — и ни
# разу не сказал владельцу. Тот остался гадать и решил, что кончился лимит
# подписки. Сигнал, который идёт только виновнику, владельца не бережёт.
сказать_владельцу_о_молчании() { # $1 = минут без отчёта, $2 = минут с работы
    # Имена ЛАТИНИЦЕЙ: `local отчёт=` bash не принимает — «not a valid
    # identifier», и функция обрывается молча (наступил на это же 12.09.2026
    # в четвёртый раз за смену, см. память: cyrillic-in-bash-names).
    local silence="$1" work="$2" mark age=""
    [ "$silence" -ge "${PULSE_OWNER_MIN:-60}" ] || return 0
    mark="$LOG_DIR/pulse.owner"
    [ -f "$mark" ] && age=$(( ( $(date +%s) - $(stat -c '%Y' "$mark") ) / 60 ))
    if подавлен_кулдауном "$age" "${PULSE_OWNER_MIN:-60}"; then
        say "владельцу о молчании уже говорили $age мин назад — жду"
        return 0
    fi
    date +%s > "$mark"
    jlog "pulse_owner" "${SESSION_ID:-}" "владельцу сказано о молчании ${silence} мин"
    # Про лимит НЕ утверждаем того, чего не проверяли. Улика 12.09.2026: этот
    # текст говорил «с лимитом подписки это не связано» безусловно, а ветка
    # лимита в этом же стороже в ту же минуту писала в журнал «лимит виден:
    # отказ 429 был 9 мин назад». Владелец получил два противоречащих сигнала
    # и назвал это обманом. Спрашиваем ТОТ ЖЕ признак, что и ветка лимита.
    local limit_min="" tail_text doska_says="" stall=""
    if [ -n "${TRANSCRIPT:-}" ]; then
        limit_min=$(лимит_в_транскрипте_минут "$TRANSCRIPT" 2>/dev/null || true)
        stall=$(немота_агента_минут "$TRANSCRIPT" || true)
    fi
    # Лимит действует, только пока отказ свежее последнего успешного ответа —
    # то же условие, что LIMIT_PROVEN в ветке лимита. Прибор отдаёт возраст
    # последнего 429 во всём хвосте журнала, и прошедший лимит без этого
    # называется причиной часами после того, как смена снова работала.
    if [[ "$limit_min" =~ ^[0-9]+$ ]] && [[ "$stall" =~ ^[0-9]+$ ]] \
       && [ "$limit_min" -ge "$stall" ]; then
        limit_min=""
    fi
    # Доска состояния: смена говорит о себе ПРЯМО, а не только следами в
    # журнале (владелец 12.09.2026: «нужно место для обмена данными, чтобы код
    # умел туда обращаться»). Её слово старше косвенных признаков — но только
    # пока запись жива: срок хранится в самой записи.
    if [ -x "${PROJECT_DIR:-}/scripts/board.py" ] || [ -f "${PROJECT_DIR:-}/scripts/board.py" ]; then
        # Код доски — её ответ: 0 — запись жива, иначе записи нет. Через
        # `|| true` в весть владельцу уезжала сама строка «смена: записи нет»
        # (его снимок 17.10.2026: «До остановки смена делала: смена: записи нет»).
        doska_says=$(python3 "${PROJECT_DIR}/scripts/board.py" --читать смена 2>/dev/null) \
            || doska_says=""
    fi
    # ФАКТ СТАРШЕ НАМЕРЕНИЯ. Доска — слово смены о том, что она СОБИРАЕТСЯ
    # делать; отказ 429 — машинный факт о том, что она не работает вовсе.
    # Улика 13.09.2026: смена стояла в лимите 3,5 часа, а на доске висела её
    # запись «задача о глубине закрыта, беру архив владельца на разбор» —
    # живая, со сроком 120 минут. Доска стояла ПЕРВОЙ веткой и перебила
    # лимит: владелец получил «смена работает, но не отчитывается» и спросил
    # «почему он не в курсе что лимит». Теперь лимит называется первым, а
    # доска идёт дополнением — что смена собиралась делать до остановки.
    # Простой называется ОДНИМ числом. Улика 17.10.2026: в одной вести стояли
    # «не отчитывается 63 минут» и «последний отказ 9 мин назад» — две мерки
    # одного простоя, владелец не понял, какая правда. При лимите мерка одна:
    # сколько смена стоит с последнего ответа.
    head_text="Смена работает, но не отчитывается вам ${silence} минут — статус у неё прошу уже несколько раз."
    if [ -n "$limit_min" ]; then
        head_text="Смена стоит ${stall:-$limit_min} мин."
        tail_text="Работа стоит из-за лимита подписки. Как лимит обновится, смена продолжит сама."
        [ -n "$doska_says" ] && tail_text="${tail_text} До остановки смена делала: ${doska_says}"
    elif [ -n "$doska_says" ]; then
        tail_text="Смена сообщает о себе: ${doska_says}"
    else
        tail_text="Работа идёт (последняя запись ${work} мин назад), признаков лимита подписки в журнале нет."
    fi
    # «--не-досылать»: после обновления лимита эта весть смысла не имеет —
    # работа пошла, и залп устаревших сообщений владельцу не нужен.
    tg_send "${head_text} ${tail_text}" --не-досылать \
        || say "о молчании смены владельцу сказать не удалось"
}

# Лимит подписки виден в ЖУРНАЛЕ СЕССИИ машинным признаком, а не только на
# экране: CLI пишет запись с "error": "rate_limit" и "apiErrorStatus": 429.
# Экранный признак угадывает чужой текст, этот — факт. Печатает минуты с
# последней такой записи (пусто — записей нет).
лимит_в_транскрипте_минут() { # $1 = транскрипт
    # Разбор живёт в ОТДЕЛЬНОМ приборе: с 13.09.2026 тот же факт спрашивает
    # ежеминутный limit-watch.sh, и вторая копия heredoc-а разошлась бы с
    # этой молча. Гейт check-signals.py держит источник единственным.
    [ -f "$1" ] || return 1
    python3 "$HARNESS_SCRIPTS/limit-in-log.py" "$1" 2>/dev/null
}

# Свежий ли отказ по лимиту в журнале. Один вопрос — один ответ на обоих
# сторожей: у limit-watch.sh то же условие, и разойтись им нельзя.
свежий_отказ() { # $1 = транскрипт; 0 — отказ свежий, 1 — нет
    local age_min
    age_min=$(лимит_в_транскрипте_минут "$1" || true)
    [ -n "$age_min" ] || return 1
    [ "$age_min" -le "${LIMIT_FRESH_MIN:-5}" ]
}

немота_агента_минут() { # $1 = транскрипт; печатает минуты (пусто — не смог)
    # Разбор живёт в scripts/stall-in-log.py — у факта «работает ли смена»
    # один судья, и зовут его ОБА сторожа. До 27.09.2026 разбор стоял здесь
    # heredoc-ом, а ежеминутный limit-watch.sh судил ту же работу по mtime
    # транскрипта: пинок сторожа дописывал строку, и владелец получал «работа
    # пошла снова, простой 0 мин», пока работа стояла (ревью 27.09, F-01).
    # HARNESS_SCRIPTS, а не PROJECT_DIR: самотест идёт РАНЬШЕ загрузки
    # паспорта, и обращение к PROJECT_DIR роняло бы его под set -u.
    python3 "$HARNESS_SCRIPTS/stall-in-log.py" "$1" 2>/dev/null
}

# Работа сессии = ответ главной ИЛИ живого помощника (stall-in-log.py --работа).
# Одно измерение на обход: тишину, немоту и пульс судят по ЕГО числам, а не по
# mtime транскрипта и не по одной главной. 25.10.2026 «Работа встала» ушла
# владельцу, пока помощник отвечал каждые полминуты.
# Выход: JUDGE_WORK_MIN/SEC, JUDGE_MAIN_MIN, JUDGE_HELPERS (число идущих или «?»),
# JUDGE_HUNG (число зависших), JUDGE_RC (код прибора), JUDGE_AT (когда судил), JUDGE_OUT.
# «?» — судья не смог счесть помощников, а в каталоге смены они есть: незнание
# не разрешение, ротация и перезапуск читают его как «помощники идут».
# Транскрипт СМЕНЫ в каталоге проекта — тем же разрешателем, что `stall-in-log.py --shift`:
# headless-прогоны (sdk-cli) пишут рядом и бывают свежее смены, но помощники и флаг
# ротации принадлежат смене. Печатает путь; пусто — смены в каталоге нет.
shift_transcript_in() {  # $1 = каталог транскриптов проекта
    python3 - "$HARNESS_SCRIPTS/stall-in-log.py" "$1" 2>/dev/null <<'PY' || true
import importlib.util, pathlib, sys
spec = importlib.util.spec_from_file_location("stall_in_log", sys.argv[1])
module = importlib.util.module_from_spec(spec)
spec.loader.exec_module(module)
print(module.shift_transcript(pathlib.Path(sys.argv[2])) or "")
PY
}

judge_work() {
    local rc=0 reason="" tr="${SHIFT_TRANSCRIPT:-${TRANSCRIPT:-}}"
    JUDGE_WORK_MIN="" JUDGE_WORK_SEC="" JUDGE_MAIN_MIN="" JUDGE_HELPERS=0 JUDGE_HUNG=0 JUDGE_RC=0 JUDGE_OUT=""
    JUDGE_AT=$(date +%s)
    [ -f "$tr" ] || return 0
    reason=$(mktemp)
    JUDGE_OUT=$(HELPER_FRESH_MIN="${HELPER_FRESH_MIN:-}" HELPER_HUNG_MIN="${HELPER_HUNG_MIN:-}" \
        python3 "$HARNESS_SCRIPTS/stall-in-log.py" --работа "$tr" 2>"$reason") || rc=$?
    JUDGE_RC=$rc
    if [ "$rc" = 0 ]; then
        JUDGE_WORK_MIN=$(judge_field работа_мин)
        JUDGE_WORK_SEC=$(judge_field работа_сек)
        JUDGE_MAIN_MIN=$(judge_field главная_мин)
        JUDGE_HELPERS=$(judge_field помощников)
        JUDGE_HUNG=$(judge_field зависших)
        [[ "$JUDGE_HELPERS" =~ ^[0-9]+$ ]] || JUDGE_HELPERS=0
        [[ "$JUDGE_HUNG" =~ ^[0-9]+$ ]] || JUDGE_HUNG=0
        [[ "$JUDGE_MAIN_MIN" =~ ^[0-9]+$ ]] || JUDGE_MAIN_MIN=""
    else
        # Судья молчать не должен: отказ реестра и сбой прибора сводятся к
        # главной сессии, а без её ответов — к возрасту файла.
        JUDGE_OUT=""
        [ -z "$(ls -A "${tr%.jsonl}/subagents" 2>/dev/null)" ] || JUDGE_HELPERS="?"
        [ "$rc" != 3 ] || say "судья работы отказал: $(head -c 300 "$reason") — сужу по главной сессии"
        [ "$rc" = 3 ] || say "судья работы не ответил (код $rc) — сужу по главной сессии"
        JUDGE_MAIN_MIN=$(немота_агента_минут "$tr" || true)
        JUDGE_WORK_MIN="$JUDGE_MAIN_MIN"
    fi
    rm -f "$reason"
    [[ "$JUDGE_WORK_MIN" =~ ^[0-9]+$ ]] || \
        JUDGE_WORK_MIN=$(( ( $(date +%s) - $(stat -c '%Y' "$tr") ) / 60 ))
    [[ "$JUDGE_WORK_SEC" =~ ^[0-9]+$ ]] || JUDGE_WORK_SEC=$(( JUDGE_WORK_MIN * 60 ))
}
judge_field() {  # $1 = ключ строки судьи → значение
    printf '%s\n' "$JUDGE_OUT" | awk -F'\t' -v key="$1" '$1 == key { print $2; exit }'
}
# Есть ли помощники: «?» (судья не знает) читается как «есть», число — как число.
helpers_present() { [ "${JUDGE_HELPERS:-0}" != 0 ]; }
# Живые помощники строкой для текста: $1 = «пинок» (с «идёт N мин») | «весть».
judge_helpers_text() {
    printf '%s\n' "$JUDGE_OUT" | awk -F'\t' -v mode="$1" '
        $1 == "помощник" {
            one = "«" $5 "» ("
            if (mode == "пинок") one = one "идёт " $4 " мин, "
            one = one "последний ответ " $3 " мин назад)"
            out = out (out == "" ? "" : (mode == "пинок" ? "; " : ", ")) one
        }
        END { print out }'
}
# Зависшие помощники строкой для текста владельцу.
judge_hung_text() {
    printf '%s\n' "$JUDGE_OUT" | awk -F'\t' '
        $1 == "зависший" {
            one = "«" $5 "» (молчит " $3 " мин, идёт " $4 " мин)"
            out = out (out == "" ? "" : ", ") one
        }
        END { print out }'
}

# Что слать диалогу на N-й попытке. Улика 10.09.2026: за ОДНУ ротацию сторож
# послал Enter СОРОК раз (rotate_exit_dialog=40 при rotate_exit_sent=1) и
# двадцать минут ничего не менялось — сессия жила, преемник не поднимался,
# работать было некому. Одна клавиша, повторённая сорок раз, — не попытка, а
# ожидание чуда: если Enter не сработал дважды, он не сработает и в сороковой.
# Лестница: подтвердить как есть → назвать пункт ЯВНО цифрой → сбросить диалог
# и подать «/exit» заново. Клавиши именами tmux, а не текстом (send_to_pane
# шлёт «Enter» буквами -l и в диалоге бесполезен).
# ── снимки терминала: что было на экране в момент нештатного ────────────────
# Задача владельца 13.09.2026: «Можно сделать механизм который делает
# скриншоты терминала чтобы потом разбираться?» В тот день диалог выхода не
# поддался десять раз, а в журнале от экрана осталось 400 знаков — по ним не
# видно ни всего списка задач, ни того, что было выше диалога.
#
# Снимок — файл, а не строка журнала: экран это двумерная картина, и в JSONL
# он превращается в кашу из «|». Храним последние СНИМКОВ_ХРАНИМ штук: за
# сутки тревог бывает под сотню, и без предела каталог съел бы диск.
сохранить_снимок() { # $1=повод $2=текст экрана (пусто — снять с панели) → путь
    # Имена переменных ЛАТИНИЦЕЙ: кириллическое имя bash не берёт, а печатает
    # его значение в ошибку ([[cyrillic-in-bash-names]]).
    local povod="$1" text="${2:-}" dir file extra
    dir="${SNIMKI_DIR:-$LOG_DIR/snimki}"
    mkdir -p "$dir" || return 1
    [ -n "$text" ] || text=$(tmux capture-pane -p -S -200 -t "$TMUX_SESSION" 2>/dev/null || true)
    file="$dir/$(date '+%Y-%m-%d_%H-%M-%S')-${povod}.txt"
    printf '%s\n' "$text" > "$file" || return 1
    # Сносим самые старые по ИМЕНИ: оно начинается с времени, и сортировка
    # имён совпадает с порядком событий — mtime у скопированного файла врёт.
    extra=$(find "$dir" -maxdepth 1 -name '*.txt' | sort | head -n "-${SNIMKOV_HRANIM:-200}")
    [ -z "$extra" ] || printf '%s\n' "$extra" | xargs -r rm -f
    printf '%s\n' "$file"
}

клавиши_подтверждения() { # $1 = номер попытки, $2 = помощники держат (1/0) → клавиши через пробел
    # Помощники живут внутри процесса: «Exit and stop tasks» и «уйти фоном»
    # оборвали бы их. Отвечаем отменой выхода — назад к ожиданию.
    [ "${2:-0}" != 1 ] || { printf 'Escape\n'; return 0; }
    # Улика 13.09.2026 (04:58–05:01): десять попыток подряд, пункт «Exit and
    # stop tasks» подсвечен, клавиши уходят («1=ок, Enter=ок») — и диалог
    # стоит. В списке четыре фоновые задачи shell, среди них отвязанные
    # setsid: остановить их выход не может, потому и не завершается. Дальше
    # давить тот же пункт бессмысленно — уходим ФОНОМ: он ничего не ждёт.
    case "$1" in
        1|2) printf 'Enter\n' ;;
        3)   printf 'ПУНКТ Enter\n' ;;   # ПУНКТ подставляется номером с экрана
        4|5) printf 'ФОНОМ Enter\n' ;;   # ФОНОМ — номер пункта «уйти фоном»
        *)   printf 'Escape\n' ;;
    esac
}

# Номер пункта «Exit and stop tasks» — С ЭКРАНА, а не вшитый.
# Ревью 10.09.2026: в лестнице стояла литеральная «1», хотя рядом уже был разбор
# пунктов. Сменится порядок в диалоге CLI — сторож нажмёт «Stay», то есть сам
# отменит выход, которого добивается.
номер_пункта_выхода() { # $1 = текст панели → «1» / «2» / пусто
    # «|| true»: пустой ответ — законный случай (диалога нет), а под set -e
    # ненулевой grep уронил бы весь самотест — так и случилось при первом прогоне.
    printf '%s\n' "$1" \
        | grep -E "$RE_EXIT_ITEM" \
        | grep -oE '[0-9]+' | head -1 || true
}

# Номер пункта «Move to background and exit» — С ЭКРАНА, как и пункт выхода:
# порядок пунктов задаёт чужой CLI, и вшитая «2» однажды нажмёт «Stay».
номер_пункта_фоном() { # $1 = текст панели → «2» / «3» / пусто
    printf '%s\n' "$1" \
        | grep -E "$RE_BACKGROUND_ITEM" \
        | grep -oE '[0-9]+' | head -1 || true
}

# Какой пункт диалога подсвечен. Без этого в журнале сорок одинаковых строк, по
# которым нельзя сказать, двигался ли выбор вообще ([[a-signal-that-does-not-discriminate]]).
# «> /exit» в той же панели начинается так же — потому и нужен номер пункта.
подсвеченный_пункт_в() { # $1 = текст панели
    printf '%s' "$1" | grep -m1 -E "$RE_PICKED_ITEM" | sed -E "s/^[[:space:]]*${PICK_MARK}[[:space:]]*//" || true
}

# ── Решение по tmux-панели агента — ЧИСТОЙ функцией, чтобы её можно было
# прогнать без tmux, без сервера и без побочных действий (UNIFIED/08: прибор
# доказывается на больном случае, а значит должен быть запускаем).
#
# Улика 11.08.2026: владелец вышел из claude — systemd-юнит остался active,
# heartbeat-метки свежие, харнес рапортовал зелёным, а агента не было.
# Замечалось это ТОЛЬКО когда что-то требовалось доставить (непустой inbox или
# непустая очередь). «Агент мёртв» — самостоятельное состояние, а не побочный
# эффект неудачной доставки, поэтому у него теперь свой сторож.
#
# Улика 11.08.2026 (вторая): подключённый клиент был БЕЗУСЛОВНОЙ блокировкой.
# SSH-клиент владельца висит на сессии постоянно — значит подъём агента был
# запрещён не «пока владелец работает», а НАВСЕГДА; в 22:51 сессия вышла сама,
# и никто её не поднял. Клиент уважается ровно пока в панели есть жизнь:
# простаивает дольше AGENT_ATTACHED_IDLE_MIN — за клиентом никого нет.
# И даже когда человек в панели действительно работает, молчать нельзя:
# работать некому, а владелец узнаёт об этом только из канала.
#
# Печатает одно слово: ok | человек | сказать | ждём | поднять
решение_по_панели() { # $1=команда  $2=клиенты tmux  $3=эпоха «не claude с»  $4=сейчас  $5=простой панели, мин  $6=владелец ждёт ответа
    local cmd="$1" clients="$2" since="$3" now="$4" idle_min="${5:-0}" waiting="${6:-0}" elapsed_min
    if pane_is_agent "$cmd"; then printf 'ok\n'; return 0; fi
    if [ -n "$since" ] && [ "$since" != 0 ]; then elapsed_min=$(( (now - since) / 60 )); else elapsed_min=-1; fi
    if [ "$AGENT_DEAD_RESPECT_ATTACHED" = 1 ] && [ "${clients:-0}" -gt 0 ] \
       && [ "${idle_min:-0}" -lt "$AGENT_ATTACHED_IDLE_MIN" ]; then
        # За клиентом кто-то печатает: слать туда команды — портить его ввод.
        # Но если агента нет дольше порога — сказать об этом в канал.
        if [ "$elapsed_min" -ge "$AGENT_DEAD_MIN" ]; then printf 'сказать\n'; else printf 'человек\n'; fi
        return 0
    fi
    # БОЛЬНОЙ СЛУЧАЙ 27.08.2026, 13:34–13:53: владелец дважды написал «Статус»,
    # агента в панели не было, а сторож выдерживал порог и вместо подъёма смены
    # дважды ответил ему «передать агенту не могу». Порог существует, чтобы не
    # дёргать сессию на пересборке панели; ждущему владельцу он стоил 19 минут
    # молчания. Ждёт владелец — поднимаем сразу.
    if [ "${waiting:-0}" = 1 ]; then printf 'поднять\n'; return 0; fi
    if [ "$elapsed_min" -lt 0 ]; then printf 'ждём\n'; return 0; fi
    if [ "$elapsed_min" -lt "$AGENT_DEAD_MIN" ]; then printf 'ждём\n'; return 0; fi
    printf 'поднять\n'
}

# Что слышит смена, когда ротация ждёт помощников. «Не начинай» без оговорки
# смена читает как «молчи» и не отвечает владельцу, поэтому запрет назван
# запретом на запуск, а ответ в канал — разрешённым прямо.
rotation_hold_text() {  # $1 = число идущих помощников
    printf '%s' "[сторож сессий] ротация ждёт идущих помощников ($1): новых задач не начинай ни сам, ни помощником (запрет только на запуск); на сообщения владельца отвечай в канал как обычно — вопрос ответом, работу карточкой в очередь"
}

подавить_ротацию() {  # журнал, сессия, режим (1 = спрашиваем владельца), сейчас-эпоха
    # Печатает «нет» либо «да <событие> <возраст_мин> <окно_мин>». Одно решение,
    # никаких побочных действий — потому и проверяемо селфтестом без живой сессии.
    #
    # Анонс владельцу и поданная в панель команда — РАЗНЫЕ события с разными
    # окнами: первый ждёт чужого решения, вторая уже исполняется. 11.08.2026
    # оба писались как rotate_command, и неотвеченный анонс 22:20 задавил
    # ротацию до 00:20 — окно за это время дошло до 114%, сессия ушла в
    # автосжатие, то есть ровно в то, что ротация обязана предотвращать.
    local log="$1" sess="$2" ask="$3" now="$4" event gap ts age
    if [ "${ask:-0}" = 1 ]; then event="rotate_announced"; gap="${ROTATE_ANNOUNCE_GAP_MIN:-30}"
    else                         event="rotate_command";   gap="${ROTATE_COOLDOWN_MIN:-120}"; fi
    [ -f "$log" ] || { echo "нет"; return 0; }
    ts=$(grep "\"event\":\"$event\".*\"session\":\"$sess\"" "$log" | tail -1 | jq -r '.ts' 2>/dev/null || true)
    [ -n "$ts" ] && [ "$ts" != "null" ] || { echo "нет"; return 0; }
    age=$(( ( now - $(date -d "$ts" +%s) ) / 60 ))
    [ "$age" -lt "$gap" ] || { echo "нет"; return 0; }
    # Команда, о провале которой журнал сказал сам, не исполняется — ждать её
    # весь ROTATE_COOLDOWN_MIN незачем. Повторов раньше окна не больше
    # ROTATE_EARLY_RETRY_MAX: безостановочная подача поручений в панель мешала бы
    # смене отвечать владельцу.
    if [ "$event" = "rotate_command" ] && [ "$age" -ge "${ROTATE_APPLY_WAIT_MIN:-30}" ] \
       && [ "$(rotation_failed_recently "$log" "$sess" "$now" "$gap")" = "да" ]; then
        echo "нет"; return 0
    fi
    echo "да $event $age $gap"
}

# «да», если после последней команды ротации этой сессии журнал записал провал
# (clear_failed, clear_timeout, rotate_timeout), а попыток за окно ещё не больше
# ROTATE_EARLY_RETRY_MAX + 1. Команда полного пути, поданная вслед за провалом
# быстрого (в течение двух минут), — та же попытка, а не новая: повтор по
# решению сторожа не бывает раньше ROTATE_APPLY_WAIT_MIN.
rotation_failed_recently() {  # журнал, сессия, сейчас-эпоха, окно_мин
    local log="$1" sess="$2" now="$3" gap="$4" ev ts failed=0 fail_at=0 attempts=0 e
    while IFS=$'\t' read -r ts ev; do
        e=$(date -d "$ts" +%s) || continue
        case "$ev" in
            rotate_command)
                if [ $(( e - fail_at )) -ge 120 ] && [ $(( (now - e) / 60 )) -lt "$gap" ]; then
                    attempts=$((attempts + 1))
                fi
                failed=0 ;;
            *) failed=1; fail_at="$e" ;;
        esac
    done < <(grep -E "\"event\":\"(rotate_command|clear_failed|clear_timeout|rotate_timeout)\"" "$log" \
             | jq -r --arg s "$sess" 'select(.session == $s) | [.ts, .event] | @tsv' 2>/dev/null | tail -40)
    [ "$failed" = 1 ] && [ "$attempts" -le "${ROTATE_EARLY_RETRY_MAX:-2}" ] && echo да || echo нет
}

# Единиц у сравнения нет намеренно: возраст и порог приходят в одних и тех же
# единицах — у пинка в секундах, у разговора о блокировке в минутах.
подавлен_кулдауном() {  # возраст ("" — события не было), порог
    [ -n "$1" ] || return 1
    [ "$1" -lt "$2" ]
}

# Пинок «подхвати работу» зовут три руки: сторож после ротации, sentinel после
# загрузки и пусковой скрипт после подъёма юнитом (Restart=always вернёт сессию
# за 10с — раньше её возвращал только сторож, и он же пинал). Решение отдельно
# от действия: внутри самого пинка пауза, ожидание панели и запись в живую
# сессию агента — проверить это селфтестом нельзя, а решение можно.
пинок_подавлен() {  # возраст последнего пинка в секундах ("" — пинка не было)
    подавлен_кулдауном "$1" "${KICK_COOLDOWN_SEC:-120}"
}

# Признак «уходящая сессия закончилась». Видов три, и третий появился не сразу.
# Улика 12.08.2026: команда завершения подана в 14:40:02, сессия закрылась в
# 14:51:32 — в срок, но юнит harness-agent (Restart=always, RestartSec=10)
# вернул claude в панель через 10с, раньше очередной 30-секундной проверки.
# Сторож видел «в панели снова claude», досидел до 900с, записал rotate_timeout
# и поднял владельца по ложной тревоге — а свои шаги после смены (пинок
# «подхвати работу», проверка приёма) пропустил. Тот же ложный таймаут был в
# 13:35. Смену видно там, где её не подделать: свежайший транскрипт проекта
# сменил имя — значит пишет уже не та сессия.
#
# Печатает одно слово: ушла | оболочка | преемник | ждём
смена_состоялась() {  # $1=сессия tmux жива(1/0) $2=команда в панели $3=id свежайшего транскрипта $4=id уходящей
    local alive="$1" pane="$2" fresh_id="$3" old_id="$4"
    [ "$alive" = 1 ] || { printf 'ушла\n'; return 0; }
    # «мертва» — панель пережила свой процесс: агент вышел, сессия цела.
    case "$pane" in
        bash|sh|zsh|dash) printf 'оболочка\n'; return 0 ;;
        мертва) printf 'ушла\n'; return 0 ;;
    esac
    if [ -n "$fresh_id" ] && [ "$fresh_id" != "$old_id" ]; then printf 'преемник\n'; return 0; fi
    printf 'ждём\n'
}

# Кто закрывает уходящую сессию. Улика 12.08.2026: команда завершения подавалась
# в 13:35, 14:40, 15:50, 18:00 — агент КАЖДЫЙ раз отрабатывал регламент (STATE,
# передача, коммит), но выйти не мог: «/exit», написанный агентом в ответе, —
# просто текст, слэш-команду исполняет только ввод в панель
# (память/выход-exit-агенту-недоступен.md). Сторож досиживал 900с и будил
# владельца «нужно вмешаться» — автоматическая ротация превращалась в ручную.
# Выход — работа сторожа, а не агента: агент доводит регламент до конца, сторож
# видит, что панель замолчала, и сам вводит «/exit».
#
# Молчание панели само по себе НЕ значит «агент закончил». Улика 13.08.2026:
# ротация в 13:00 увидела простой 288с и ввела «/exit» — а агент в это время
# работал, и владелец видел в терминале, как его оборвали на середине задачи с
# незакоммиченным деревом. Панель молчит и во время долгого инструмента
# (`make smoke` — 5 мин 40 с): вывода нет, работа есть. Признак «жду ввода» из
# него не выводится никак — молчание не отличает занятость от простоя.
#
# Точный признак даёт хук Stop: он срабатывает ровно тогда, когда ход завершён.
# Хук пишет время в turn-end.stamp, здесь оно сверяется с моментом поручения:
# закончил ход ПОСЛЕ того, как получил задание, — регламент отработан.
#
# Закончил ли агент ход после указанного момента (метку пишет хук Stop).
# Метки нет — печатаем 0: молчание хука толкуем как «ход не закончен», иначе
# отсутствие сигнала работало бы разрешением, а это ровно то, что чинится.
ход_завершён_после() {  # $1=epoch поручения
    local since="$1" stamp
    stamp=$(cat "$LOG_DIR/turn-end.stamp" 2>/dev/null || echo 0)
    [[ "$stamp" =~ ^[0-9]+$ ]] || stamp=0
    if [ "$stamp" -gt "$since" ]; then printf '1'; else printf '0'; fi
}

# Печатает одно слово: смена | ждём | выход | принудительно | тревога
выход_из_ротации() {  # $1=вердикт смены $2=простой панели, сек $3=выход уже подан(1/0) $4=прошло сек $5=таймаут сек $6=ход завершён после поручения(1/0) $7=фоновая задача сессии жива(1/0) $8=помощники держат(1/0)
    # Имена переменных латиницей: кириллические bash запрещает (SC2296).
    local verdict="$1" idle="$2" sent="$3" elapsed="$4" limit="$5" turn_done="${6:-0}" tasks_live="${7:-0}" helpers_hold="${8:-0}"
    [ "$verdict" = "ждём" ] || { printf 'смена\n'; return 0; }
    if [ "$sent" != 1 ]; then
        # Идущие помощники живут в процессе смены: «/exit» оборвал бы их. Ни
        # молчание панели, ни срок регламента этого не отменяют — ожидание
        # помощников ограничено своим сроком (ROTATE_HELPERS_WAIT_MAX_MIN).
        [ "$helpers_hold" = 1 ] && { printf 'ждём\n'; return 0; }
        # Ход закончен И панель молчит — регламент отработан, агент ждёт ввода.
        # Одного молчания мало (см. улику выше), одной метки — тоже: ход мог
        # закончиться и возобновиться, а метка осталась бы прежней.
        [ "$turn_done" = 1 ] && [ "$idle" -ge "${ROTATE_IDLE_SEC:-120}" ] && { printf 'выход\n'; return 0; }
        # Срок вышел, а панель всё говорит: выход всё равно наш — молчание
        # сторожа стоит дороже прерванного хода, работа уже в передаче.
        [ "$elapsed" -ge "$limit" ] && { printf 'принудительно\n'; return 0; }
    elif [ "$elapsed" -ge "$limit" ]; then
        # Фоновая задача сессии держит очередь ввода: «/exit» УЖЕ принят, но
        # исполнится после неё. Сессия при этом жива и работает — будить
        # владельца не за что. Улика 04.09.2026: сторож ввёл «/exit» в 14:13:02,
        # транскрипт принял его («Bye!») в 14:19:34 — 392с спустя, а тревога
        # владельцу ушла в 14:16 напрасно, и следом напрасный дозор.
        [ "$tasks_live" = 1 ] && { printf 'задачи\n'; return 0; }
        printf 'тревога\n'; return 0
    fi
    printf 'ждём\n'
}

# Фоновая задача сессии (Bash с run_in_background) откладывает ВЕСЬ ввод из
# очереди, включая «/exit»: Claude Code исполняет его после хода по завершённой
# задаче. Снаружи это неотличимо от зависания — а различить обязано, иначе
# сторож будит владельца на каждой ротации с живой фоновой работой.
# Признак — свежесть вывода задач: Claude Code пишет его в
# /tmp/claude-<uid>/<проект>/<сессия>/tasks/<id>.output.
# stat, а не `find -newermt`: find здесь bfs, относительных отметок он не берёт.
фоновые_задачи_живы() {  # $1=id сессии $2=порог свежести, сек
    local sid="$1" fresh="${2:-${ROTATE_TASK_FRESH_SEC:-120}}" now d f age
    [ -n "$sid" ] || return 1
    now=$(date +%s)
    for d in "${TASKS_ROOT:-/tmp}"/claude-*/*/"$sid"/tasks; do
        [ -d "$d" ] || continue
        for f in "$d"/*; do
            [ -f "$f" ] || continue
            age=$(( now - $(stat -L -c %Y "$f" 2>/dev/null || echo 0) ))
            [ "$age" -le "$fresh" ] && return 0
        done
    done
    return 1
}

# Обрезки текста в канал здесь больше нет. Три улики подряд об одном: владелец
# получил хвост «…довест» (12.08.2026), отчёт приёмки на 500 знаках — «и я же
# полностью так и не прочитаю» (12.08.2026), и наконец прямо (13.08.2026):
# «твои сообщения обрезаются, а они вообще не должны иметь лимита». Потолок
# 4096 есть у ОДНОГО сообщения Telegram, а не у текста: tg_send.sh делит любой
# текст на нумерованные части и доставляет целиком. Резать до него нечего.

# Замер окна: usage последнего ответа модели (input + оба кэша) — ровно то, за
# что платят на следующем шаге. Читается хвост транскрипта: файл весит мегабайты,
# а нужна последняя запись. Размер хвоста — двойной запас над самой длинной
# строкой живого транскрипта (1,29 МБ, снимок экрана в base64): при 200 КБ один
# такой снимок вытеснял замер целиком (улика 12.08.2026, 19:50).
#
# Печатает число токенов либо НИЧЕГО. Пусто — это «померить не удалось», а не
# ноль и не повод к ротации: прикидка «байты файла = окно» здесь была и врала
# (669% там, где было 42%), поэтому её больше нет.
# ── Чем менять сессию: «/clear» или полный перезапуск ───────────────────────
# Решение владельца 11.09.2026: «Механизма нужно оба, просто для каждого своя
# роль». Замер того же дня на отдельной сессии: «/clear» освобождает окно
# (117 385 → 34 927 токенов), заводит НОВЫЙ идентификатор сессии и новый файл
# транскрипта — то есть замер заполнения подхватывает его сам, — и при этом
# CLAUDE.md с указаниями остаётся в контексте (проверено секретным словом:
# после «/clear» сессия ответила из контекста, ни разу не заглянув в файл).
#
# Отсюда роли. «/clear» — обычный путь: мгновенно, без выхода из процесса, без
# диалога подтверждения, без подъёма преемника (48 таймаутов из 135 попыток за
# месяц — все родом из тяжёлого пути). Полный перезапуск — там, где «/clear»
# бессилен, потому что процесс остаётся прежним:
#   • правились хуки или настройки — их читают только при старте процесса;
#   • сменилась версия CLI — работает старая, пока процесс жив;
#   • давно не перезапускались — память процесса не освобождается никогда;
#   • «/clear» уже подавали, а окно не упало — значит признак врёт, уходим
#     тяжёлым путём, а не крутимся в лёгком.
# Принудительный выход (`--rotate-now`, смена модели) — тоже полный: агент
# просил именно уйти.
#
# Печатает: clear | full
способ_ротации() { # $1=хуки правились $2=версия сменилась $3=часов с полного $4=потолок часов $5=clear не помог $6=принудительный $7=перезагрузка встала бы
    local hooks="$1" version="$2" hours="$3" limit="$4" failed="$5" forced="$6" reboot="${7:-0}"
    [ "$forced" = 1 ] && { printf 'full\n'; return 0; }
    [ "$failed" = 1 ] && { printf 'full\n'; return 0; }
    [ "$hooks"  = 1 ] && { printf 'full\n'; return 0; }
    [ "$version" = 1 ] && { printf 'full\n'; return 0; }
    [ "$hours" -ge "$limit" ] && { printf 'full\n'; return 0; }
    # Перезагрузка заменяет «/exit» только тяжёлого пути: быстрый её не знает.
    [ "$reboot" = 1 ] && { printf 'full\n'; return 0; }
    printf 'clear\n'
}

# ── Менять ли сессию ПРЯМО СЕЙЧАС — чистой функцией, её судит самотест ─────
# Владелец 18.10.2026 прислал беду с другого своего сервера: «Лимит подписки.
# И смена сессии. Но без полноценной передачи, потому, что возник лимит и
# модель не может сделать передачу. Соответственно ротация сессии надо чтобы
# была невозможна если передача не состоялась».
#
# Почему это было возможно: поручение регламента уходит в панель, а под
# лимитом ход НЕ НАЧИНАЕТСЯ — метка конца хода остаётся прежней, панель молчит.
# Молчание смены под лимитом и молчание смены, доделавшей дела, для сторожа
# выглядели одинаково, и дальше шёл «/clear».
#
# Порядок веток не произвольный: лимит СТАРШЕ принуждения — под лимитом писать
# передачу нечем, и принуждать нечего. Причина принуждения обязательна:
# дверь без названной причины — не дверь, а дыра ([[a-guard-without-a-legal-door]]).
ротация_разрешена() {
    # $1=передача дописана после поручения(1/0) $2=лимит держится(1/0)
    # $3=принуждение(1/0) $4=причина принуждения (текст)
    local peredacha="${1:-0}" limit="${2:-0}" forced="${3:-0}" why="${4:-}"
    # ПЕРЕДАЧА СТАРШЕ ЛИМИТА (находка ревью F1-gen-04). Написанная передача
    # делает смену безопасной, и запрещать её из-за лимита — своя беда: улика
    # 11.08.2026 в этом же файле, подавленная ротация довела окно до 114 % и
    # сессия ушла в автосжатие. Лимит объясняет, ПОЧЕМУ передачи нет, а не
    # запрещает смену при её наличии.
    if [ "$peredacha" = 1 ]; then
        printf 'да: передача смены написана\n'
        return 0
    fi
    if [ "$limit" = 1 ]; then
        printf 'нет: держится лимит подписки — смена не может написать передачу, а смена сессии без неё теряет весь контекст\n'
        return 1
    fi
    if [ "$forced" = 1 ] && [ -n "$why" ]; then
        printf 'да: передачи нет, но ротация принуждена названной причиной — %s\n' "$why"
        return 0
    fi
    if [ "$forced" = 1 ]; then
        printf 'нет: принуждение без причины — ROTATE_WITHOUT_HANDOVER требует ROTATE_WITHOUT_HANDOVER_WHY\n'
        return 1
    fi
    printf 'нет: передача дел не написана — менять сессию значит потерять её целиком\n'
    return 1
}

# ── Ждать ли помощников перед сменой сессии — чистой функцией ──────────────
# Помощник живёт ВНУТРИ процесса claude смены: «/exit» и «/clear» обрывают всех
# на середине, их работа и токены уходят в мусор (слово владельца 02.11.2026).
# Слово И код: вызывающий смотрит на код, журнал и владелец — на слово.
# Опечатка в ключе действия не рубит работу: незнакомое действие = «сообщить».
# Зависший не ждёт срока: он и так молчит дольше HELPER_HUNG_MIN.
rotation_helpers_verdict() {
    # $1=идут (число|?) $2=зависших $3=ждали мин $4=предел мин $5=действие по сроку
    local running="${1:-0}" hung="${2:-0}" waited="${3:-0}" cap="${4:-60}" action="${5:-}" what
    if [ "$running" = 0 ] && [ "$hung" = 0 ]; then
        printf 'можно: помощников нет\n'
        return 0
    fi
    if [ "$running" != 0 ]; then
        if [ "$waited" -lt "$cap" ]; then
            printf 'ждать: идут помощники (%s), ждём %s мин из %s\n' "$running" "$waited" "$cap"
            return 1
        fi
        what="ждали $waited мин (предел $cap), идут помощники ($running)"
    else
        what="зависли помощники ($hung): молчат дольше HELPER_HUNG_MIN, похоже, завис"
    fi
    if [ "$action" = ротировать ]; then
        printf 'ротировать: %s\n' "$what"
        return 0
    fi
    printf 'сообщить: %s\n' "$what"
    return 1
}

# ── Перезагружать ли сервер в окне ротации — чистой функцией ────────────────
# Слово владельца 27.10.2026 (входящее 9705) и подтверждение 10558: только в
# момент смены сессии и только когда помощники не работают. Ошибка кода здесь —
# настоящая перезагрузка машины, поэтому каждое «нет» называет свою причину, а
# порядок проверок — от дешёвого и частого «нет» к редкому: первое отвечает.
# Слово И код, как у rotation_helpers_verdict: сторож смотрит на код.
reboot_window_verdict() {
    # $1=ключ $2=соседи $3=пауза 1|0 $4=act $5=фоновые задачи 1|0 $6=помощников N|?
    # $7=занята 0|?|что $8=нужна 1|0|? $9=часов с загрузки ${10}=предел часов ${11}=прошлая не сменила ядро 1|0
    local key="${1:-}" neighbours="${2:-}" paused="${3:-0}" act="${4:-}" tasks="${5:-0}" helpers="${6:-?}"
    local busy="${7:-?}" need="${8:-?}" hours="${9:-}" gap="${10:-}" last_failed="${11:-0}"
    if [ "$key" != 1 ]; then
        printf 'нет: автоперезагрузка выключена (AUTO_REBOOT_IN_ROTATION=%s)\n' "$key"; return 1
    fi
    if [ -z "$neighbours" ]; then
        printf 'нет: соседи не названы владельцем (STACK_NEIGHBOURS пуст)\n'; return 1
    fi
    if [ "$paused" = 1 ]; then printf 'нет: пауза владельца\n'; return 1; fi
    if [ "$paused" != 0 ]; then printf 'нет: пауза неизвестна (pause.py не ответил)\n'; return 1; fi
    if [ "$act" != выход ]; then printf 'нет: смена ещё в ходу (%s)\n' "$act"; return 1; fi
    if [ "$tasks" = 1 ]; then printf 'нет: идёт фоновая задача сессии\n'; return 1; fi
    if ! [[ "$helpers" =~ ^[0-9]+$ ]]; then printf 'нет: помощники неизвестны\n'; return 1; fi
    if [ "$helpers" != 0 ]; then printf 'нет: идут помощники (%s)\n' "$helpers"; return 1; fi
    if [ "$busy" = "?" ]; then printf 'нет: занята ли машина — неизвестно\n'; return 1; fi
    if [ "$busy" != 0 ]; then printf 'нет: машина занята (%s)\n' "$busy"; return 1; fi
    if [ "$need" = 0 ]; then printf 'нет: перезагрузка не нужна\n'; return 1; fi
    if [ "$need" != 1 ]; then printf 'нет: нужна ли перезагрузка — неизвестно\n'; return 1; fi
    if ! [[ "$hours" =~ ^[0-9]+$ ]] || ! [[ "$gap" =~ ^[0-9]+$ ]] || [ "$hours" -lt "$gap" ]; then
        printf 'нет: машина загружена %s ч назад (< %s)\n' "$hours" "$gap"; return 1
    fi
    if [ "$last_failed" = 1 ]; then
        printf 'нет: прошлая перезагрузка не сменила ядро — нужен владелец\n'; return 1
    fi
    printf 'перезагрузить: окно ротации, помощников нет, машина свободна, загружена %s ч назад\n' "$hours"
    return 0
}

# Сколько ждали, без паузы владельца: на паузе ротация погашена, и её время
# ожиданием помощников не является — иначе пауза в 2,5 часа дала бы ложную
# весть «ждём уже 3 часа».
rotation_waited_sec() {  # $1=ждали_сек $2=проверено epoch $3=сейчас epoch $4=пауза 1|0
    if [ "$4" = 1 ]; then printf '%s\n' "$1"; else printf '%s\n' $(( $1 + $3 - $2 )); fi
}

окно_в_токенах() {  # $1=транскрипт
    [ -f "$1" ] || return 0
    tail -c "${CTX_TAIL_BYTES:-2000000}" "$1" 2>/dev/null | python3 -c '
import json, sys
последний = 0
for строка in sys.stdin:
    try:
        u = (json.loads(строка).get("message") or {}).get("usage") or {}
    except Exception:
        continue            # обрезанная первая строка и битые — не наш контракт
    объём = sum(int(u.get(k) or 0) for k in
                ("input_tokens", "cache_read_input_tokens", "cache_creation_input_tokens"))
    if объём:
        последний = объём
if последний:
    print(последний)
' 2>/dev/null || true
}

# ── Решение лимитной ветки — ЧИСТОЙ функцией, её можно проверить ────────────
# Ревью 27.09.2026 (F-lim-06): самотест сторожа кончается строкой 1667, а вся
# ветка лимита живёт в потоке прогона ниже 2600 — любая мутация там зелена по
# построению. Пять условий, решавших судьбу сообщения владельцу, сведены сюда:
# суждение отдельно, действия отдельно.
#
# Вход (всё числами 0/1, кроме немоты): немота_мин доказан виден есть_метка свежий_отказ
# Выход одним словом:
#   возобновление   — метка стоит, смена ожила, свежего отказа нет
#   объявить-лимит  — порог пройден, метки нет, признак лимита есть
#   объявить-немоту — порог пройден, метки нет, признака лимита нет
#   пинок           — порог пройден, но о простое уже сказано
#   молчу           — порог не пройден
решение_лимита() {
    local STALL="${1:-0}" PROVEN="${2:-0}" SEEN="${3:-0}" MARKED="${4:-0}" FRESH="${5:-0}"
    local STALL_LIMIT="${LIMIT_STALL_MIN:-20}" SAY_MIN="${LIMIT_SAY_MIN:-3}"
    [[ "$STALL" =~ ^[0-9]+$ ]] || STALL=0
    # Возобновление судится ПЕРВЫМ: смена, которая снова пишет и не получает
    # отказов, важнее любого порога немоты.
    #
    # Порог здесь — SAY_MIN (смена ПИШЕТ), а не STALL_LIMIT (смена молчит, но
    # меньше двадцати минут). Улика 27.09.2026, снимок владельца «смотри как
    # много спама было»: 14 пар «Упёрся в лимит» / «Лимит обновился» за три
    # часа, по паре каждые десять минут. Сессия стояла в лимите и пробовала
    # раз в пять минут; ежеминутный limit-watch ставил метку по свежему отказу
    # (3 мин) и говорил «упёрся», а этот сторож на своём обходе видел немоту
    # 10 минут, отказ 9-минутной давности (FRESH=0 при пороге 5) — и объявлял
    # «работа возобновилась», пока работа стояла. В том же обходе он сам писал
    # «лимит виден: отказ 429 был 9 мин назад»: два измерения одного факта
    # разъехались порогами. Возобновление обязано доказываться ПРИЗНАКОМ
    # РАБОТЫ, а не её отсутствием; у ежеминутного сторожа порог был этот с
    # самого начала — здесь стояла вторая копия суждения с чужим порогом.
    # PROVEN спрашивается отдельно, хотя при порогах по умолчанию (SAY_MIN 3,
    # FRESH_MIN 5) он избыточен. Ревью 27.09 (F-02): избыточность держится на
    # НЕЗАПИСАННОМ соотношении двух ключей — LIMIT_SAY_MIN ≤ LIMIT_FRESH_MIN.
    # Владелец настраивает первый («через сколько минут немоты сказать мне о
    # лимите»), второго в harness.conf нет вовсе; LIMIT_SAY_MIN=10 молча
    # возвращает дефект: немота 7, отказ 6-минутной давности — и сторож снова
    # объявляет возобновление при доказанном лимите. Одно слово дешевле, чем
    # зависимость правильности от того, какое число владелец впишет в конфиг.
    if [ "$MARKED" = 1 ] && [ "$STALL" -lt "$SAY_MIN" ] && [ "$FRESH" = 0 ] \
       && [ "$PROVEN" = 0 ]; then
        printf 'возобновление\n'
        return 0
    fi
    if [ "$STALL" -ge "$STALL_LIMIT" ] \
       || { [ "$PROVEN" = 1 ] && [ "$STALL" -ge "$SAY_MIN" ]; }; then
        if [ "$MARKED" = 1 ]; then
            printf 'пинок\n'
        elif [ "$SEEN" = 1 ]; then
            printf 'объявить-лимит\n'
        else
            printf 'объявить-немоту\n'
        fi
        return 0
    fi
    printf 'молчу\n'
}

# ── `--признак-диалога <tmux-сессия>`: сверка признака с ЖИВЫМ экраном ──────
# Улика 11.09.2026: самотест был зелёным на ВЫДУМАННОМ образце экрана, а живой
# CLI печатает маркер «❯» вместо «>» — за ротацию 02:00 диалог не распознан ни
# разу, владелец вышел руками. Самотест ловит только то, что в него вписали;
# этот режим спрашивает настоящую панель и ничего в неё не шлёт.
# Проверка перед выкатом правок в распознавание:
#   tmux new-session -d -s проба claude … → задача в фоне → «/exit»
#   session-warden.sh --признак-диалога проба   → ждём «диалог: ДА»
if [ "${1:-}" = "--признак-диалога" ]; then
    PANE_SESSION="${2:-}"
    [ -n "$PANE_SESSION" ] || { echo "нужно имя tmux-сессии: $0 --признак-диалога <сессия>" >&2; exit 2; }
    tmux has-session -t "$PANE_SESSION" 2>/dev/null \
        || { echo "tmux-сессии «$PANE_SESSION» нет" >&2; exit 2; }
    SCREEN=$(tmux capture-pane -p -t "$PANE_SESSION" 2>/dev/null || true)
    if диалог_выхода_в "$SCREEN"; then
        echo "диалог: ДА"
        echo "подсвечено: $(подсвеченный_пункт_в "$SCREEN")"
        echo "номер пункта выхода: $(номер_пункта_выхода "$SCREEN")"
        echo "клавиши на 1-й попытке: $(клавиши_подтверждения 1)"
        exit 0
    fi
    echo "диалог: НЕТ"
    # Три признака порознь: по ним видно, какой именно не сошёлся, а не «просто нет».
    printf '%s\n' "$SCREEN" | grep -qE '^[[:space:]]*Background work is running[[:space:]]*$' \
        && echo "  заголовок: есть" || echo "  заголовок: НЕТ"
    printf '%s\n' "$SCREEN" | grep -qE "$RE_EXIT_ITEM" \
        && echo "  пункт выхода: есть" || echo "  пункт выхода: НЕТ"
    printf '%s\n' "$SCREEN" | grep -qE '^[[:space:]]*Enter to confirm' \
        && echo "  приглашение подтвердить: есть" || echo "  приглашение подтвердить: НЕТ"
    exit 1
fi

# ── `--признак-лимита <tmux-сессия>`: сверка признака лимита с ЖИВЫМ экраном ─
# Тот же урок, что и с диалогом выхода: признак по чужому экрану обязан быть
# проверяем на настоящем экране, иначе слепоту видно только по последствию.
if [ "${1:-}" = "--признак-лимита" ]; then
    PANE_SESSION="${2:-}"
    [ -n "$PANE_SESSION" ] || { echo "нужно имя tmux-сессии: $0 --признак-лимита <сессия>" >&2; exit 2; }
    tmux has-session -t "$PANE_SESSION" 2>/dev/null \
        || { echo "tmux-сессии «$PANE_SESSION» нет" >&2; exit 2; }
    SCREEN=$(tmux capture-pane -p -t "$PANE_SESSION" 2>/dev/null || true)
    if признак_лимита_в "$SCREEN"; then
        echo "лимит: ПОХОЖЕ ДА"
        echo "строка: $(строка_лимита_в "$SCREEN")"
        echo "ВНИМАНИЕ: это лишь половина признака — вторая половина (немота транскрипта) проверяется сторожем"
        exit 0
    fi
    echo "лимит: нет"
    exit 1
fi

knopka_revizii() {  # $1 = файл-флага, $2 = путь демона ревизии
    # Кнопка панели «ревизия сейчас» — ФЛАГ, а не ключ конфига. Ключ читает
    # месячный cron, а сбрасывать его пришлось бы демону, то есть второму
    # писателю /etc/harness/harness.conf (спека ревизии, C-5). Флаг кладёт
    # панель, снимает сторож — и обещание «в ближайшую проверку» правдиво.
    [ -f "$1" ] || return 0
    # Выключатель фоновых: погашенный запуск не должен съесть кнопку молча.
    local gate=0
    "$PROJECT_DIR/scripts/run-background.sh" --разрешён project-revision || gate=$?
    if [ "$gate" -eq 1 ]; then
        say "кнопка ревизии: ревизия отложена выключателем — флаг остаётся"
        return 0
    fi
    rm -f "$1"
    if [ ! -x "$2" ] && [ ! -f "$2" ]; then
        say "кнопка ревизии: демона нет ($2) — флаг снят, запускать нечего"
        return 1
    fi
    say "кнопка ревизии: запускаю $2 --сейчас"
    setsid nohup "$PROJECT_DIR/scripts/run-background.sh" project-revision -- bash "$2" --сейчас >> "$LOG_DIR/project-revision.log" 2>&1 < /dev/null &
    return 0
}

# Кто в панели. Отдельным словом «мертва» — панель, переживившая свой процесс
# (remain-on-exit): опыт 13.08.2026 показал, что `pane_current_command` у неё
# продолжает показывать ПРЕЖНЮЮ команду, то есть «claude» уже после выхода
# агента. Всякий, кто спросит «агент на месте?», получил бы ответ про мертвеца.

# Судья по дереву процессов (scripts/lib/agent_processes.py). Из проб путь к
# проекту подменяется, поэтому библиотека берётся от PROJECT_DIR, как tg_send.sh.
agent_proc() {
    TMUX_SESSION="$TMUX_SESSION" AGENT_USER="${AGENT_USER:-}" \
        python3 "$PROJECT_DIR/scripts/lib/agent_processes.py" "$@"
}

# Тревога не чаще раза в период: метка $LOG_DIR/<ключ>.told хранит время
# последней УСПЕШНОЙ отправки. Не ушла — метки нет, и следующий круг повторит.
# $1 ключ, $2 текст, $3 задача для tg_send.
alarm_once() {
    local stamp="$LOG_DIR/$1.told" period="${NEST_ALARM_PERIOD_SEC:-3600}" age
    if [ -f "$stamp" ]; then
        age=$(( $(date +%s) - $(stat -c '%Y' "$stamp") ))
        [ "$age" -lt "$period" ] && return 0
    fi
    mkdir -p "$LOG_DIR"
    if tg_send "$2" --несмотря-на-лимит --task "$3"; then
        date +%s > "$stamp"
    else
        say "тревога «$1» не ушла — повторю в следующем круге"
    fi
    return 0
}

# Совет «systemctl restart» — только если живого агента нет: при lost/orphan
# перезапуск юнита убил бы живую смену, а тревогу о них уже послал nest_guard.
refusal_hint() {
    [ -z "${NEST_REFUSAL:-}" ] || return 0
    tg_send "Сессии агента нет, и поднять её командой «$AGENT_START_CMD» не удалось. Нужны ваши руки: sudo -u $AGENT_USER -H systemctl restart harness-agent" --несмотря-на-лимит --task session-warden:no-agent \
        || say "и сигнал не ушёл"
}

# Гнезда tmux нет — это не всегда «агента нет». Сокет бывает удалён при живом
# сервере (отчёт другого сервера, 29.10.2026): подъём по has-session поднял
# второй сервер со второй сменой. Здесь судится по дереву процессов.
# Коды: 0 — гнездо есть или возвращено (start_agent кончен), 1 — отказ с
# тревогой владельцу, 2 — агента нет вовсе, поднимать штатно.
# NEST_REFUSAL нужен вызывающему: при живом агенте совет «systemctl restart»
# вреден — перезапуск юнита убил бы живую смену.
nest_guard() {
    local verdict waited=0
    NEST_REFUSAL=""
    verdict=$(agent_proc status 2>/dev/null) || true
    case "${verdict%%$'\n'*}" in
        ok) rm -f "$LOG_DIR/nest-lost.told" "$LOG_DIR/nest-orphan.told"; return 0 ;;
        lost)
            say "сокет tmux '$TMUX_SESSION' пропал, а сервер с агентом жив — возвращаю сокет сигналом USR1, второй сервер не поднимаю"
            agent_proc restore-nest >/dev/null 2>&1 || true
            while :; do
                if tmux has-session -t "$TMUX_SESSION" 2>/dev/null; then
                    say "сокет tmux вернулся"
                    return 0
                fi
                [ "$waited" -lt "${NEST_RESTORE_WAIT_SEC:-10}" ] || break
                sleep 1; waited=$((waited + 1))
            done
            NEST_REFUSAL="lost"
            alarm_once nest-lost "Гнездо tmux '$TMUX_SESSION' пропало, а сервер tmux с агентом жив. Сигнал возврата сокета не помог за ${waited}с. Вторую смену не поднимаю — она писала бы в то же дерево. Нужны ваши руки: найти сервер (pgrep -a 'tmux: server') и вернуть сокет (kill -USR1 <pid>), перезапуск юнита убьёт живую смену." \
                session-warden:nest-lost
            return 1 ;;
        orphan)
            NEST_REFUSAL="orphan"
            say "tmux-сервера нет, но агент (claude) жив вне tmux — вторую смену не поднимаю"
            alarm_once nest-orphan "Сервера tmux нет, но процесс агента claude жив вне tmux. Вторую смену не поднимаю — она работала бы параллельно с живой. Нужны ваши руки: посмотреть, кто это (pgrep -a claude), и закрыть лишнее." \
                session-warden:nest-orphan
            return 1 ;;
    esac
    return 2
}

# Два основных агента сразу — две смены пишут в одно дерево. Тревога только
# когда ТОТ ЖЕ состав pid'ов держится два круга подряд и не короче
# TWO_AGENTS_CONFIRM_SEC: короткоживущий второй (каждый круг новый pid) — не
# смена. Порог 540, а не 600: круги cron расходятся на секунды. Смена состава
# сбрасывает since. Метка .told хранит, о каком составе уже сказано.
check_two_agents() {
    local state="$LOG_DIR/two-agents.state" pids rc=0 since="" since_epoch="" now fresh=1
    pids=$(agent_proc two-agents 2>/dev/null) || rc=$?
    case "$rc" in
        0)
            # Условие ушло — снимаем по журналу тревог, а не по метке .told:
            # метка живёт в LOG_DIR и теряется, журнал — нет.
            if declare -F alert_task >/dev/null; then
                alert_task --resolve session-warden:two-agents
            fi
            rm -f "$state" "$state.told"; return 0 ;;
        1) ;;
        *) return 0 ;;
    esac
    mkdir -p "$LOG_DIR"
    now=$(date +%s)
    if [ "$(sed -n 's/^pids=//p' "$state" 2>/dev/null | head -1)" = "$pids" ]; then
        since=$(sed -n 's/^since=//p' "$state" | head -1)
        since_epoch=$(sed -n 's/^since_epoch=//p' "$state" | head -1)
        [ -z "$since_epoch" ] || fresh=0
    fi
    [ -n "$since_epoch" ] || { since_epoch=$now; since=$(date -d "@$now" '+%Y-%m-%dT%H:%M:%S'); }
    printf 'count=%s\npids=%s\nsince=%s\nsince_epoch=%s\nupdated=%s\n' \
        "$(wc -w <<<"$pids")" "$pids" "$since" "$since_epoch" "$(date '+%Y-%m-%dT%H:%M:%S')" > "$state"
    [ "$fresh" = 0 ] && [ $((now - since_epoch)) -ge "${TWO_AGENTS_CONFIRM_SEC:-540}" ] || return 0
    [ "$(cat "$state.told" 2>/dev/null)" = "$pids" ] && return 0
    # Выключатель данными (harness.conf): ложная тревога будит владельца.
    [ "${TWO_AGENTS_ALARM:-1}" != 0 ] || { say "тревога «два агента» выключена: TWO_AGENTS_ALARM=0"; return 0; }
    if tg_send "Работают два агента: pids $pids. Оставить одну смену: bash scripts/one-shift.sh" \
        --несмотря-на-лимит --task session-warden:two-agents; then
        printf '%s' "$pids" > "$state.told"
    else
        say "тревога о двух агентах не ушла — повторю в следующем круге"
    fi
    return 0
}

# Подъём агента после ротации (Б-4а). Команда запуска — только в оболочку:
# в чужой процесс (редактор, зависший claude) её слать так же опасно.
#
# Улика 11.08.2026 (проба ротации): с тех пор как юнит создаёт сессию КОМАНДОЙ
# (`tmux new-session … "$AGENT_START_CMD"`), выход агента закрывает и панель, и
# всю сессию. Слать команду запуска стало некуда: подъём начинается с самой
# сессии. Юнит её не вернёт — при штатном выходе rc=0, а у него Restart=on-failure.
# `8>&-` у каждого запуска, порождающего tmux-СЕРВЕР, — не украшение.
# Пережито 12.08.2026: лок сторожа взят дескриптором 8 (`exec 8>>` выше),
# затем сторож поднял агента, tmux-сервер унаследовал этот дескриптор и стал
# держать лок ВЕЧНО — он демон и не умирает. Девять плановых прогонов подряд
# вышли «лок занят»; сторож был мёртв 40 минут, а нашлось это случайно.
# Круг замкнутый: ротацию делает сторож, а первая же ротация его и убивает —
# сессия после неё дорастает до автокомпакта, ради избежания которого он есть.
# Улика: `/proc/42014/fd/8 -> …/session-warden.lock`, tmux запущен 13:36:23,
# ровно в момент ротации.
# Проверено пробой: `exec {FD}>>` НЕ спасает (bash не ставит close-on-exec —
# потомок видит дескриптор), спасает только явное закрытие при вызове.
start_agent() {
    local cmd waited=0 zapusk
    # Чем войдёт поднятая смена. Носитель чужого ключа срывается ЗДЕСЬ, у
    # самой отправки: поставленный на загрузке конфига, он обходится любым,
    # кто задаёт AGENT_START_CMD позже, — и проба судила бы не тот путь.
    zapusk="$(komanda_agenta "$AGENT_START_CMD")"
    # Подмена конфига живёт одной командой, а не в окружении tmux-сервера:
    # сервер — демон, он не умирает, и всё, что осело в его глобальном
    # окружении, наследует КАЖДАЯ будущая сессия агента. Улика 12.08.2026:
    # HARNESS_CONF со смоук-порогом «ротация при 1% окна» остался в глобале
    # после пробы ротации; поднятая сессия унаследовала его, и первый же
    # ручной прогон сторожа объявил ротацию на 26% окна.
    tmux set-environment -gu HARNESS_CONF 2>/dev/null || true
    tmux set-environment -gu HARNESS_INSTALL_CONF 2>/dev/null || true
    # Та же беда, но дороже: носитель чужого входа. Сервер tmux нёс его с
    # 30.09 (поднят, когда переменная стояла в профиле), и каждая созданная
    # им панель получала ЧУЖУЮ подписку — владелец 10.10: «при ротации
    # подключается аккаунт, в котором у меня закончился лимит». У команды
    # запуска носитель срывает komanda_agenta; здесь он снимается у сервера,
    # чтобы его не унаследовала панель, открытая руками.
    tmux set-environment -gu "$NOSITEL_CHUZHOGO_VHODA" 2>/dev/null || true
    if ! tmux has-session -t "$TMUX_SESSION" 2>/dev/null; then
        local nest=0
        nest_guard || nest=$?
        case "$nest" in 0) return 0 ;; 1) return 1 ;; esac
    fi
    if ! tmux has-session -t "$TMUX_SESSION" 2>/dev/null; then
        say "tmux-сессии '$TMUX_SESSION' нет — поднимаю её вместе с агентом"
        if [ -x "$PROJECT_DIR/scripts/start-agent.sh" ]; then
            "$PROJECT_DIR/scripts/start-agent.sh" 8>&- || return 1
        else
            # С оболочкой, а не командой: сессия, созданная командой, умирает
            # вместе с агентом и выбрасывает приаттаченного владельца из tmux
            # (улика 13.08.2026 — та же, что в scripts/start-agent.sh).
            tmux new-session -d -s "$TMUX_SESSION" -c "$PROJECT_DIR" 8>&- || return 1
            pane_command keys "$zapusk" Enter || return 1
        fi
        while [ "$waited" -lt "$AGENT_START_TIMEOUT_SEC" ]; do
            sleep 5; waited=$((waited + 5))
            case "$(pane_cmd)" in claude|node) say "агент поднялся вместе с сессией за ${waited}с"; return 0 ;; esac
        done
        say "сессия поднята, но агента в панели нет за ${AGENT_START_TIMEOUT_SEC}с (там: $(pane_cmd))"
        return 1
    fi
    cmd=$(pane_cmd)
    case "$cmd" in
        claude|node) say "в панели уже claude/node — агент запущен без меня"; return 0 ;;
        # Мёртвой панели ввод не отдать: её оживляют respawn, а не send-keys.
        мертва)
            say "панель пережила выход агента (remain-on-exit) — оживляю её командой запуска"
            tmux respawn-pane -t "$TMUX_SESSION" -c "$PROJECT_DIR" "$zapusk" 8>&- || return 1 ;;
        bash|sh|zsh|dash)
            say "запускаю агента: $AGENT_START_CMD"
            # Строка оболочки очищается ДО команды. В ней мог остаться висячий
            # ввод: лестница ответов диалогу слала в панель цифры и Escape, а
            # readline держит Escape началом мета-последовательности и съедает
            # ПЕРВУЮ букву следующей команды. Улика 21.09.2026: подъём пришёл
            # как «laude --model claude-opus-5 …», «Command laude not found»,
            # агент не поднялся за 120с, работа стояла 27 минут.
            pane_command keys C-c || true
            sleep "${PANE_ENTER_DELAY:-0.7}"
            pane_command keys "$zapusk" Enter || return 1 ;;
        *) say "в панели '$cmd' — не оболочка, команду запуска не шлю"; return 1 ;;
    esac
    while [ "$waited" -lt "$AGENT_START_TIMEOUT_SEC" ]; do
        sleep 5; waited=$((waited + 5))
        # Метку ставит ТОЛЬКО тяжёлый путь: по её возрасту решается, не пора ли
        # перезапустить процесс ради памяти, которую «/clear» не освобождает.
        case "$(pane_cmd)" in
            claude|node)
                say "агент поднялся за ${waited}с"
                touch "$HEARTBEAT_DIR/.полный-перезапуск" 2>/dev/null || true
                return 0 ;;
        esac
    done
    say "агент НЕ поднялся за ${AGENT_START_TIMEOUT_SEC}с (в панели: $(pane_cmd))"
    return 1
}


# Будить ли смену, когда она молчит. Решение отдельной функцией, потому что
# проба обязана судить БОЕВОЙ код: переписанная у себя копия зеленела бы после
# любой правки боя ([[comparing-two-implementations-turns-tautological]]).
#
# СЛУЧАЙ 26.09.2026: смена стояла, ожидая слова владельца по шагу 3 спеки, и
# получила три пинка подряд «если лимит подписки обновился — продолжай». Лимита
# не было, продолжать было нечего, и каждый пинок стоил полного шага агента со
# всем накопленным контекстом. Ветка 6 этот довод уже знает («агента не
# трогаем — будить нечем»), а ветка лимита в прибор очереди не смотрела вовсе.
budit_smenu() {  # $1=число работ, $2=строка ждущих → 0 будить, 1 не будить
    local rabot="$1" zhdut="$2"
    # Прибор не ответил (пусто, не число) — будим: молчать из-за сломанного
    # прибора нельзя, это уже решено веткой 6 тем же доводом.
    [[ "$rabot" =~ ^[0-9]+$ ]] || return 0
    [ "$rabot" -gt 0 ] && return 0          # работа есть — будить есть зачем
    [ -n "$zhdut" ] && return 1             # всё ждёт владельца — будить нечем
    return 0                                # ни работы, ни ждущих — прежнее поведение
}

# «Работы нет, смена у приглашения»: делать самой нечего (wip без блокера —
# тоже работа; судья тот же, что у «будить ли смену»), ход закончен после
# последнего успешного ответа, и владелец не писал после последнего отчёта.
# Свежий транскрипт сам по себе работой не считается: его освежает и ответ на
# пинок сторожа. Мера и срок — в данных: слово владельца новее отчёта снимает
# состояние (смена работает над ответом), незаконченный ход — тоже (смена
# работает или зависла, и о зависании говорят как прежде).
blocked_idle() {  # $1=работ $2=ждущие $3=слово владельца $4=отчёт $5=конец хода $6=ответ (epoch) → 0 у приглашения
    budit_smenu "$1" "$2" && return 1
    [[ "$6" =~ ^[0-9]+$ ]] || return 1          # ответа не видно — судить нечем
    [ "${3:-0}" -gt "${4:-0}" ] && return 1     # владелец сказал после отчёта
    [ "${5:-0}" -ge "$6" ]                      # ход закончен после ответа
}

# Время последнего слова владельца: входящие лежат файлами в inbox/ и
# inbox/обработано/ и строкой в inbox.jsonl — берём время самого свежего.
owner_last_word_epoch() {
    local newest jsonl
    newest=$(find "$LOG_DIR/inbox" "$LOG_DIR/inbox/обработано" -maxdepth 1 -type f \
             -name '*.txt' -printf '%T@\n' 2>/dev/null | sort -nr | head -1 | cut -d. -f1 || true)
    jsonl=$(stat -c '%Y' "$LOG_DIR/inbox.jsonl" 2>/dev/null || true)
    [ "${jsonl:-0}" -gt "${newest:-0}" ] && newest="$jsonl"
    printf '%s\n' "${newest:-0}"
}

# Число из файла-метки (отчёт, конец хода); нет или мусор — 0.
epoch_from() {  # $1 = файл
    local v; v=$(cat "$1" 2>/dev/null || true)
    [[ "$v" =~ ^[0-9]+$ ]] && printf '%s\n' "$v" || printf '0\n'
}

# Время последнего успешного ответа — тот же судья, что немота (stall-in-log.py).
last_answer_epoch() {  # $1 = транскрипт → epoch (пусто — ответов нет)
    python3 - "$HARNESS_SCRIPTS/stall-in-log.py" "$1" 2>/dev/null <<'PY' || true
import datetime, importlib.util, sys
spec = importlib.util.spec_from_file_location("stall_in_log", sys.argv[1])
judge = importlib.util.module_from_spec(spec)
spec.loader.exec_module(judge)
mark = judge.последний_ответ(sys.argv[2])
if mark:
    print(int(datetime.datetime.fromisoformat(str(mark).replace("Z", "+00:00")).timestamp()))
PY
}

# Пульс отчётности: просить ли у смены статус. У приглашения отчитываться не о
# чем: пинок рождает ответ, ответ освежает транскрипт, и следующий обход снова
# видит «работа идёт» — круг без конца.
# Срабатывает, когда к следующему обходу отчёту станет больше порога: на обходе
# раз в WARDEN_PERIOD_MIN минут провал виден не раньше, чем через шаг.
pulse_verdict() {  # $1=мин с работы $2=мин без отчёта $3=у приглашения(0/1) → пинок|молчу
    if [ "$1" -ge "${SILENCE_MAX_MIN:-30}" ] \
       || [ $(( $2 + ${WARDEN_PERIOD_MIN:-10} )) -le "${PULSE_MAX_MIN:-30}" ] \
       || [ "$3" = 1 ]; then
        printf 'молчу\n'
    else
        printf 'пинок\n'
    fi
}

# Повод остановки для метки. Признак лимита старше всего: лимит — факт о том,
# что смена не может работать, даже если работы и нет.
stall_reason() {  # $1=признак лимита(0/1) $2=у приглашения(0/1) → limit|blocked|nemota
    if [ "$1" = 1 ]; then printf 'limit\n'
    elif [ "$2" = 1 ]; then printf 'blocked\n'
    else printf 'nemota\n'
    fi
}

if [ "${1:-}" = "--selftest" ]; then
    ok_flag=1
    NOW=1000000
    # Библиотека конфигов — ЗДЕСЬ: самотест идёт РАНЬШЕ загрузки паспорта, а
    # start_agent берёт из неё komanda_agenta (срыв чужого носителя входа).
    # Без неё проба умирала под set -e молча, не напечатав ни строки
    # ([[a-bash-function-called-before-definition]]).
    KONF_ST="$WARDEN_HOME/../../scripts/lib/config.sh"
    [ -r "$KONF_ST" ] || KONF_ST="$WARDEN_HOME/../scripts/lib/config.sh"
    # shellcheck disable=SC1090
    source "$KONF_ST"
    проба() { # $1=ожидание $2..$4 аргументы решения $5=имя случая $6=простой панели, мин $7=владелец ждёт
        local want="$1" got
        got=$(AGENT_DEAD_MIN=15 AGENT_ATTACHED_IDLE_MIN=10 \
              AGENT_DEAD_RESPECT_ATTACHED="${AGENT_DEAD_RESPECT_ATTACHED:-1}" \
              решение_по_панели "$2" "$3" "$4" "$NOW" "${6:-0}" "${7:-0}")
        if [ "$got" = "$want" ]; then printf '  ок    %s\n' "$5"
        else printf '  ПЛОХО %s: ждали «%s», получили «%s»\n' "$5" "$want" "$got"; ok_flag=0; fi
    }
    # БОЛЬНОЙ СЛУЧАЙ 11.08.2026, 22:51: клиент владельца висит на сессии сутками,
    # панель при этом мертва. Раньше здесь печаталось «человек» — и агент не
    # поднимался никогда. Теперь простой панели снимает уважение к клиенту.
    проба поднять bash   1 $((NOW-3600)) "клиент висит, но панель не трогали 40 мин — за ним никого, поднимаем" 40
    проба ok      claude 0 0            "в панели claude — агент жив"
    проба ok      node   1 0            "в панели node (обёртка claude) — жив"
    проба человек bash   1 $((NOW-300))  "владелец печатает в панели (простой 1 мин), агента нет 5 мин — не лезем и молчим" 1
    проба сказать bash   1 $((NOW-3600)) "владелец печатает, а агента нет час — в панель не лезем, но говорим в канал" 1
    проба ждём    bash   0 $((NOW-300))  "5 минут не claude — рано, ждём"
    проба ждём    bash   0 0             "первый раз увидели не claude — засекаем время, не действуем"
    # БОЛЬНОЙ СЛУЧАЙ 27.08.2026: владелец ждал ответа 19 минут, пока сторож
    # выдерживал порог. Ждущий владелец порог снимает — оба случая ниже.
    проба поднять bash   0 $((NOW-300))  "владелец ждёт ответа — порог не выдерживаем, поднимаем" 0 1
    проба поднять bash   0 0             "владелец ждёт, а часы только заведены — всё равно поднимаем" 0 1
    проба ok      claude 0 0             "владелец ждёт, но агент на месте — поднимать нечего" 0 1
    проба ждём    bash   1 $((NOW-300))  "панель простаивает, но агента нет всего 5 мин — сперва порог" 40
    проба поднять bash   0 $((NOW-1200)) "20 минут не claude и никого нет — поднять агента"
    проба поднять vim    0 $((NOW-1200)) "в панели редактор без человека — то же (сессия брошена)"
    AGENT_DEAD_RESPECT_ATTACHED=0 проба поднять bash 2 $((NOW-1200)) \
        "уважение к приаттаченному выключено конфигом — поднимаем"

    # ── кто закрывает уходящую сессию ───────────────────────────────────────
    выход() { # $1=ожидание $2..$7 аргументы решения $8=имя случая
        local want="$1" got
        got=$(ROTATE_IDLE_SEC=120 выход_из_ротации "$2" "$3" "$4" "$5" "$6" "$7" "${9:-0}")
        if [ "$got" = "$want" ]; then printf '  ок    %s\n' "$8"
        else printf '  ПЛОХО %s: ждали «%s», получили «%s»\n' "$8" "$want" "$got"; ok_flag=0; fi
    }
    # БОЛЬНОЙ СЛУЧАЙ 13.08.2026 (владелец видел обрыв в терминале): панель молчит
    # 288с, потому что идёт долгий инструмент, а хода агент не заканчивал. Старый
    # код вводил здесь «/exit» и обрывал работу на середине.
    выход ждём          ждём 288 0 300 900 0 "панель молчит 288с, но ход не закончен — агент работает, НЕ трогаем"
    # БОЛЬНОЙ СЛУЧАЙ 12.08.2026: агент отработал регламент и замолчал, но выйти
    # не может — «/exit» в его ответе это текст. Раньше сторож сидел до 900с и
    # будил владельца; теперь выход вводит он сам.
    выход выход         ждём 150 0 300 900 1 "ход закончен и панель молчит 150с ≥ 120 — сторож вводит «/exit» сам"
    выход ждём          ждём  40 0 300 900 1 "ход закончен, но панель ожила (молчит 40с) — агент продолжил, ждём"
    выход ждём          ждём  40 0 300 900 0 "агент ещё пишет отчёт (молчит 40с) — не мешаем"
    выход ждём          ждём 200 1 400 900 1 "«/exit» уже подан, сессия ещё закрывается — ждём"
    выход принудительно ждём  10 0 900 900 0 "срок вышел, а ход не закончен — выход всё равно наш, а не тревога"
    выход тревога       ждём  10 1 900 900 1 "«/exit» подан, а сессия жива после срока — вот теперь будим владельца"
    # БОЛЬНОЙ СЛУЧАЙ 04.09.2026: «/exit» введён в 14:13:02, исполнен в 14:19:34
    # («Bye!» в транскрипте) — очередь ввода держала фоновая задача сессии.
    # Сессия была жива и работала, а сторож в 14:16 поднял владельца зря.
    выход задачи        ждём  10 1 900 900 1 "«/exit» подан, срок вышел, но фоновая задача сессии жива — ждём её, а не будим владельца" 1
    выход тревога       ждём  10 1 900 900 1 "фоновых задач нет — прежний путь, тревога" 0

    # ── признак живой фоновой задачи: свой каталог, свои отметки времени ─────
    задачи() {  # $1=ожидание(живы/нет) $2=возраст вывода, сек $3=имя случая
        local want="$1" got=нет T="$(mktemp -d)"
        mkdir -p "$T/claude-77/проект/сессия-проба/tasks"
        printf 'x' > "$T/claude-77/проект/сессия-проба/tasks/b1.output"
        touch -d "@$(( $(date +%s) - $2 ))" "$T/claude-77/проект/сессия-проба/tasks/b1.output"
        TASKS_ROOT="$T" фоновые_задачи_живы "сессия-проба" 120 && got=живы
        rm -rf "$T"
        if [ "$got" = "$want" ]; then printf '  ок    %s\n' "$3"
        else printf '  ПЛОХО %s: ждали «%s», получили «%s»\n' "$3" "$want" "$got"; ok_flag=0; fi
    }
    задачи живы 5   "вывод задачи писался 5с назад — задача жива"
    задачи нет  600 "вывод задачи не менялся 10 мин — задачи нет, оправдания тоже"
    got=нет; TASKS_ROOT=/несуществующий фоновые_задачи_живы "сессия-проба" 120 && got=живы
    if [ "$got" = нет ]; then printf '  ок    %s\n' "каталога задач нет вовсе — признак молчит, а не врёт"
    else printf '  ПЛОХО %s\n' "каталога задач нет, а признак сказал «живы»"; ok_flag=0; fi
    выход смена         оболочка 10 0 60 900 0 "панель стала оболочкой — смена состоялась, выход не нужен"
    выход смена         преемник  0 1 90 900 0 "в панели уже преемник — дальше обычный путь"

    # ── помощники держат ротацию (слово владельца 02.11.2026) ─────────────────
    # Помощник живёт внутри процесса смены: «/exit» и «/clear» оборвали бы его.
    ворота() { # $1=ждём (слово;код) $2..$6 аргументы функции $7=имя случая
        local out rc=0 want="$1"
        out=$(rotation_helpers_verdict "$2" "$3" "$4" "$5" "$6") || rc=$?
        if [ "${out%%:*};$rc" = "$want" ]; then printf '  ок    %s\n' "$7"
        else printf '  ПЛОХО %s: ждали «%s», получили «%s;%s»\n' "$7" "$want" "${out%%:*}" "$rc"; ok_flag=0; fi
    }
    ворота "ждать;1"      2 0 0  60 сообщить  "БОЛЬНОЙ СЛУЧАЙ 02.11: окно у порога, помощники идут — ротация ждёт"
    ворота "ждать;1"      "?" 0 0 60 сообщить "судья не знает («?») — ждём, а не рубим"
    ворота "можно;0"      0 0 500 60 сообщить "помощников нет — можно сразу, сколько бы ни ждали"
    ворота "сообщить;1"   2 0 60 60 сообщить  "срок вышел, действие «сообщить» — весть владельцу, ротация ждёт дальше"
    ворота "ротировать;0" 2 0 90 60 ротировать "срок вышел, действие «ротировать» — ротация идёт"
    ворота "сообщить;1"   2 0 61 60 рубить    "незнакомое действие — как «сообщить», а не ротация"
    ворота "сообщить;1"   0 1 0  60 сообщить  "зависший помощник срока не ждёт — весть сразу"
    ворота "ротировать;0" 0 1 0  60 ротировать "зависший, действие «ротировать» — ротация идёт"
    ждали() { # $1=ждём $2..$5 аргументы $6=имя
        local got; got=$(rotation_waited_sec "$2" "$3" "$4" "$5")
        [ "$got" = "$1" ] && printf '  ок    %s\n' "$6" \
            || { printf '  ПЛОХО %s: ждали «%s», получили «%s»\n' "$6" "$1" "$got"; ok_flag=0; }
    }
    ждали 0   0   $((NOW-600)) "$NOW" 1 "прогон на паузе к ожиданию ничего не прибавляет"
    ждали 900 300 $((NOW-600)) "$NOW" 0 "прогон вне паузы прибавляет прошедшее (300 + 600)"
    держат() { # $1=ожидание $2..$7 аргументы $8=имя случая
        local got; got=$(ROTATE_IDLE_SEC=120 выход_из_ротации "$2" "$3" "$4" "$5" "$6" "$7" 0 1)
        [ "$got" = "$1" ] && printf '  ок    %s\n' "$8" \
            || { printf '  ПЛОХО %s: ждали «%s», получили «%s»\n' "$8" "$1" "$got"; ok_flag=0; }
    }
    держат ждём ждём 150 0 300 900 1 "ход закончен, панель молчит, но помощники держат — «ждём», не «/exit»"
    держат ждём ждём  10 0 900 900 0 "срок регламента вышел, помощники держат — «ждём», не «принудительно»"
    got=$(клавиши_подтверждения 3 1)
    [ "$got" = "Escape" ] && printf '  ок    %s\n' "диалог выхода при идущих помощниках — только Escape, не «Exit and stop tasks»" \
        || { printf '  ПЛОХО диалог выхода при помощниках: ждали «Escape», получили «%s»\n' "$got"; ok_flag=0; }

    # ── метка конца хода: её пишет хук Stop, читает ротация ─────────────────
    метка() { # $1=ожидание $2=что лежит в метке $3=момент поручения $4=имя случая
        local want="$1" got T; T=$(mktemp -d)
        [ "$2" = "нет" ] || printf '%s' "$2" > "$T/turn-end.stamp"
        got=$(LOG_DIR="$T" ход_завершён_после "$3")
        rm -rf "$T"
        if [ "$got" = "$want" ]; then printf '  ок    %s\n' "$4"
        else printf '  ПЛОХО %s: ждали «%s», получили «%s»\n' "$4" "$want" "$got"; ok_flag=0; fi
    }
    # БОЛЬНОЙ СЛУЧАЙ: хука нет или он ни разу не сработал. Отсутствие сигнала
    # обязано читаться как «ход не закончен» — иначе молчание снова станет
    # разрешением на «/exit», ровно как молчание панели.
    метка 0 нет            "$NOW" "метки нет вовсе — считаем, что ход не закончен"
    метка 0 "мусор"        "$NOW" "в метке не число — то же самое, ошибка не разрешает выход"
    метка 0 $((NOW - 60))  "$NOW" "последний ход закончен ДО поручения — это чужой ход, не ответ на ротацию"
    метка 1 $((NOW + 30))  "$NOW" "ход закончен после поручения — регламент отработан"

    # ── доставка текста в панель: ЖИВОЙ tmux, свои одноразовые сессии ────────
    # Решение «пинать» ничего не стоит, если пинок не доезжает. Больной случай
    # первым: старый способ на слове «Enter» обязан провалиться, иначе чинить
    # было нечего. В сессию агента селфтест не пишет ни байта — поднимает свою
    # с `cat > файл` в приёмнике.
    command -v tmux >/dev/null 2>&1 || { echo "SELFTEST: tmux не установлен — доставку в панель проверить нечем"; exit 1; }
    T=$(mktemp -d)
    приёмник() { tmux new-session -d -s "$1" "cat > '$2'"; sleep 0.5; }
    забрать()  { tmux send-keys -t "$1" C-d 2>/dev/null || true; sleep 0.5; cat "$2" 2>/dev/null || true; }

    TMUX_SESSION="warden-selftest-1-$$"
    приёмник "$TMUX_SESSION" "$T/1"
    tmux send-keys -t "$TMUX_SESSION" "Enter" Enter; sleep 0.5
    got=$(забрать "$TMUX_SESSION" "$T/1"); tmux kill-session -t "$TMUX_SESSION" 2>/dev/null || true
    if printf '%s' "$got" | grep -q 'Enter'; then
        printf '  ПЛОХО больной случай не воспроизвёлся: старый способ доставил «Enter»\n'; ok_flag=0
    else
        printf '  ок    БОЛЬНОЙ СЛУЧАЙ: старый способ на тексте «Enter» кладёт в приёмник пустые строки, слово потеряно\n'
    fi

    TMUX_SESSION="warden-selftest-2-$$"
    приёмник "$TMUX_SESSION" "$T/2"
    send_to_pane "Enter"
    got=$(забрать "$TMUX_SESSION" "$T/2"); tmux kill-session -t "$TMUX_SESSION" 2>/dev/null || true
    if [ "$got" = "Enter" ]; then printf '  ок    send_to_pane доставляет «Enter» текстом, а не клавишей\n'
    else printf '  ПЛОХО send_to_pane «Enter»: ждали «Enter», получили «%s»\n' "$got"; ok_flag=0; fi

    TMUX_SESSION="warden-selftest-3-$$"
    приёмник "$TMUX_SESSION" "$T/3"
    # $'\n', а не $(printf '\n'): подстановка съедает хвостовые переводы строки.
    send_to_pane "Очередь непуста"$'\n'"Продолжай задачу"
    got=$(забрать "$TMUX_SESSION" "$T/3"); tmux kill-session -t "$TMUX_SESSION" 2>/dev/null || true
    if [ "$got" = "Очередь непуста Продолжай задачу" ]; then
        printf '  ок    многострочный пинок приходит одной строкой (перевод строки → пробел)\n'
    else printf '  ПЛОХО многострочный пинок: получили «%s»\n' "$got"; ok_flag=0; fi

    # ── висячий Escape в оболочке: улика 21.09.2026 ──────────────────────────
    # Лестница ответов диалогу слала в панель Escape. readline держит его
    # началом мета-последовательности и съедает ПЕРВУЮ букву следующей команды:
    # подъём пришёл как «laude --model claude-opus-5 …», «Command laude not
    # found», агент не поднялся за 120с, работа стояла 27 минут.
    # Больной случай ПЕРВЫМ: не воспроизведётся — проверять нечего.
    стенд_oboloch() {  # $1 = имя сессии; своё имя и отказ, если занято
        tmux has-session -t "$1" 2>/dev/null && return 1
        tmux new-session -d -s "$1" -c /tmp 2>/dev/null || return 1
        sleep 0.5
        tmux send-keys -t "$1" Escape
        sleep 0.5
    }
    SES="warden-escape-$$"
    PODYOM="$T/podyom"
    if ! стенд_oboloch "$SES"; then
        printf '  ПЛОХО стенд оболочки не поднялся (сессия %s занята?)\n' "$SES"; ok_flag=0
    else
        tmux send-keys -t "$SES" "echo VSTAL > '$PODYOM'" Enter; sleep 1.5
        if [ -s "$PODYOM" ]; then
            printf '  ПЛОХО больной случай не воспроизвёлся: висячий Escape букву не съел\n'; ok_flag=0
        else
            printf '  ок    БОЛЬНОЙ СЛУЧАЙ: после Escape команда в оболочке калечится и не исполняется\n'
        fi
        tmux kill-session -t "$SES" 2>/dev/null || true
    fi
    rm -f "$PODYOM"
    if ! стенд_oboloch "$SES"; then
        printf '  ПЛОХО стенд оболочки не поднялся во второй раз\n'; ok_flag=0
    else
        LOG_DIR="$T/log" TMUX_SESSION="$SES" AGENT_START_CMD="echo VSTAL > '$PODYOM'" \
            AGENT_PROC_ROOT="$T/proc" AGENT_MAINPID=0 AGENT_START_TIMEOUT_SEC=5 start_agent >/dev/null 2>&1 || true
        if [ -s "$PODYOM" ]; then
            printf '  ок    start_agent сбрасывает строку: команда подъёма доходит целой\n'
        else
            printf '  ПЛОХО start_agent: команда подъёма не исполнилась (буква съедена?)\n'; ok_flag=0
        fi
        tmux kill-session -t "$SES" 2>/dev/null || true
    fi
    # ── чужой вход в памяти оболочки: улика 10.10.2026 ───────────────────────
    # Владелец: «при ротации сессий подключается аккаунт, в котором у меня
    # закончился лимит». Файловые носители убрали ещё утром того дня, а чужой
    # ключ продолжал входить: его помнили СЕРВЕР tmux (поднят 30.09) и живая
    # оболочка панели — ровно та, в которую ротация шлёт команду подъёма.
    # Больной случай ПЕРВЫМ: сперва доказываем, что носитель в оболочке есть и
    # доезжает до запущенной команды, иначе зелень второго случая ничего не стоит.
    #
    # Стенд СВОЙ, без висячего Escape: в стенде соседней пробы первая буква
    # команды съедается, «export …» не исполняется, и носитель не появляется
    # вовсе — первый прогон этой пробы так и показал (случай не воспроизвёлся,
    # а второй был бы зелёным ни за что).
    SES_N="warden-nositel-$$"
    NOSITEL_OUT="$T/nositel-vhoda"
    if tmux has-session -t "$SES_N" 2>/dev/null || \
       ! tmux new-session -d -s "$SES_N" -c /tmp 2>/dev/null; then
        printf '  ПЛОХО стенд оболочки для пробы носителя входа не поднялся\n'; ok_flag=0
    else
        sleep 0.5
        tmux send-keys -t "$SES_N" "export CLAUDE_CODE_OAUTH_TOKEN=podstavnoj-klyuch" Enter; sleep 0.7
        tmux send-keys -t "$SES_N" "printenv CLAUDE_CODE_OAUTH_TOKEN > '$NOSITEL_OUT'" Enter; sleep 1.5
        if [ -s "$NOSITEL_OUT" ]; then
            printf '  ок    БОЛЬНОЙ СЛУЧАЙ: носитель чужого входа живёт в оболочке панели и доезжает до команды\n'
        else
            printf '  ПЛОХО больной случай не воспроизвёлся: оболочка носитель не отдала\n'; ok_flag=0
        fi
        : > "$NOSITEL_OUT"
        LOG_DIR="$T/log" TMUX_SESSION="$SES_N" AGENT_START_CMD="printenv CLAUDE_CODE_OAUTH_TOKEN > '$NOSITEL_OUT'" \
            AGENT_PROC_ROOT="$T/proc" AGENT_MAINPID=0 AGENT_START_TIMEOUT_SEC=5 start_agent >/dev/null 2>&1 || true
        sleep 1.5
        if [ -s "$NOSITEL_OUT" ]; then
            printf '  ПЛОХО start_agent поднял агента С чужим носителем входа — работа уйдёт на чужую подписку\n'; ok_flag=0
        else
            printf '  ок    start_agent срывает носитель: поднятая смена его не видит\n'
        fi
        tmux kill-session -t "$SES_N" 2>/dev/null || true
    fi

    rm -rf "$T"

    # ── антиповтор ротации: 11.08 здесь потерялась сессия ────────────────────
    # Больной случай первым: анонс, на который владелец не ответил, давил
    # ротацию как исполненная команда — на 120 минут, пока окно росло до 114%.
    J=$(mktemp -d); LOG="$J/rotation.jsonl"; NOW_S=1786500000
    строка() {  # событие, минут назад, сессия (по умолчанию s1)
        printf '{"ts":"%s","event":"%s","session":"%s","detail":"-"}\n' \
               "$(date -u -d "@$(( NOW_S - $2 * 60 ))" +%Y-%m-%dT%H:%M:%SZ)" "$1" "${3:-s1}" >> "$LOG"; }
    случай() { # ожидание(да|нет), режим, имя
        local want="$1" got
        got=$(ROTATE_COOLDOWN_MIN=120 ROTATE_ANNOUNCE_GAP_MIN=30 ROTATE_APPLY_WAIT_MIN=30 ROTATE_EARLY_RETRY_MAX=2 \
              подавить_ротацию "$LOG" s1 "$2" "$NOW_S" | cut -d' ' -f1)
        if [ "$got" = "$want" ]; then printf '  ок    %s\n' "$3"
        else printf '  ПЛОХО %s: ждали «%s», получили «%s»\n' "$3" "$want" "$got"; ok_flag=0; fi
    }
    случай нет 0 "журнал пуст — давить нечем"
    строка rotate_announced 10
    случай нет 0 "БОЛЬНОЙ СЛУЧАЙ: анонс 10 мин назад НЕ давит команду в режиме full"
    случай да  1 "тот же анонс в режиме semi давит повторный анонс (10 < 30)"
    : > "$LOG"; строка rotate_announced 45
    случай нет 1 "анонс 45 мин назад в semi уже не давит (45 ≥ 30) — окно растёт, спрашиваем снова"
    : > "$LOG"; строка rotate_command 10
    случай да  0 "команда, поданная 10 мин назад, давит повтор (10 < 120)"
    : > "$LOG"; строка rotate_command 45
    случай да  0 "команда 45 мин назад без вести о провале давит: ротация может ещё идти"
    : > "$LOG"; строка rotate_command 45; строка clear_timeout 30
    случай нет 0 "БОЛЬНОЙ СЛУЧАЙ 06.11: команда не применилась (clear_timeout), сессия та же, прошло ≥ 30 мин — повтор разрешён"
    : > "$LOG"; строка rotate_command 20; строка clear_failed 15
    случай да  0 "провал есть, но с команды прошло 20 < 30 мин — рано"
    : > "$LOG"; строка rotate_command 100; строка clear_failed 95; строка rotate_command 60; строка clear_failed 55
    случай нет 0 "вторая попытка провалилась — ранний повтор ещё разрешён (повторов 1 из 2)"
    строка rotate_command 35; строка rotate_timeout 20
    случай да  0 "третья попытка за окно провалилась — потолок ранних повторов (2), давит прежнее окно"
    : > "$LOG"; строка rotate_command 100; строка clear_timeout 85; строка rotate_command 84; строка rotate_timeout 60
    случай нет 0 "полный путь вслед за быстрым — одна попытка, а не две: повтор разрешён"
    : > "$LOG"; строка rotate_command 10 s0
    случай нет 0 "запись под ПРЕЖНЕЙ сессией s0 не давит s1: ротация применилась, сессия сменилась"
    : > "$LOG"; строка rotate_command 200
    случай нет 0 "команда 200 мин назад не давит — окно вышло"
    rm -rf "$J"

    # ── весть смене о ждущей ротации: не глушит ли она ответы владельцу ──────
    # БОЛЬНОЙ СЛУЧАЙ 06.11.2026, 00:42–00:46: «новых задач не начинай» смена
    # поняла как «не отвечай», и четыре сообщения владельца остались без ответа.
    # Ответ в канал — не задача, запрет касается только запуска.
    HOLD_TEXT=$(rotation_hold_text 3)
    case "$HOLD_TEXT" in
        *"не отвечай"*) echo "  ПЛОХО БОЛЬНОЙ СЛУЧАЙ: весть велит владельцу НЕ отвечать"; ok_flag=0 ;;
        *"отвечай в канал как обычно"*) printf '  ок    БОЛЬНОЙ СЛУЧАЙ: весть велит отвечать владельцу в канал и не велит молчать\n' ;;
        *) echo "  ПЛОХО весть о ждущей ротации не велит отвечать владельцу"; ok_flag=0 ;;
    esac
    case "$HOLD_TEXT" in
        *"новых задач не начинай"*) printf '  ок    запрет на запуск новых задач сохранён\n' ;;
        *) echo "  ПЛОХО весть потеряла запрет на новые задачи"; ok_flag=0 ;;
    esac
    case "$HOLD_TEXT" in
        *"(3)"*) printf '  ок    весть называет число идущих помощников\n' ;;
        *) echo "  ПЛОХО весть не называет число помощников"; ok_flag=0 ;;
    esac

    # ── кулдаун пинка «подхвати работу» ──────────────────────────────────────
    пинок() {  # ждём(да/нет), возраст в секундах, что проверяем
        local want="$1" age="$2" name="$3" got=нет
        пинок_подавлен "$age" && got=да
        [ "$got" = "$want" ] \
            && printf '  ок    %s\n' "$name" \
            || { printf '  ПЛОХО %s: ждали «%s», получили «%s»\n' "$name" "$want" "$got"; ok_flag=0; }
    }
    KICK_COOLDOWN_SEC=120
    # БОЛЬНОЙ СЛУЧАЙ: юнит поднял сессию и пнул, сторож через минуту пнул снова —
    # свежая сессия получала два одинаковых поручения и бралась за работу дважды.
    пинок да  30 "БОЛЬНОЙ СЛУЧАЙ: пинок 30с назад давит повторный (30 < 120)"
    пинок нет 300 "пинок 300с назад не давит — та сессия уже не новая"
    пинок нет ""  "пинка не было вовсе — подавлять нечего"
    пинок да  0   "пинок только что (0с) — давит"
    пинок нет 120 "граница принадлежит разрешению: ровно 120с не давит"

    # ── что именно говорит пинок поднятой сессии ─────────────────────────────
    # БОЛЬНОЙ СЛУЧАЙ 13.09.2026: текст ставил входящие ПЕРЕД работой, и сессия
    # после подъёма бралась за последнее сообщение владельца вместо своего
    # оборванного шага. Владелец: «после лимита запуск должен быть мягкий, ты
    # должен спокойно завершить свою работу… а не хвататься за то что пишу».
    # Правило живёт в ПОРЯДКЕ СЛОВ, поэтому его и проверяем — иначе следующая
    # правка текста вернёт прежнее поведение, и никто не заметит.
    KICK_TEXT=$(sed -n 's/.*pane_command text "\(Ты — новая сессия[^"]*\)".*/\1/p' "$0" | head -1)
    POS_WORK=${KICK_TEXT%%ПРОДОЛЖАЙ ТЕКУЩИЙ ШАГ*}
    POS_INBOX=${KICK_TEXT%%inbox*}
    if [ -n "$KICK_TEXT" ] && [ ${#POS_WORK} -lt ${#POS_INBOX} ]; then
        printf '  ок    БОЛЬНОЙ СЛУЧАЙ: пинок велит продолжать шаг ДО разбора входящих\n'
    else
        printf '  ПЛОХО пинок ставит входящие раньше работы — сессия бросит свой шаг\n'
        ok_flag=0
    fi
    case "$KICK_TEXT" in
        *"не бросая его на полпути"*)
            printf '  ок    пинок прямо запрещает бросать шаг на полпути\n' ;;
        *)  printf '  ПЛОХО в пинке нет запрета бросать шаг на полпути\n'; ok_flag=0 ;;
    esac

    # ── будить ли смену: БОЛЬНОЙ СЛУЧАЙ 26.09.2026 ───────────────────────────
    # Смена стояла, ожидая слова владельца, и получила три пинка подряд «если
    # лимит подписки обновился — продолжай». Лимита не было, продолжать было
    # нечего, каждый пинок стоил полного шага агента. Судится БОЕВАЯ функция.
    budit_proba() {  # $1=работ $2=ждут $3=ждём(да|нет) $4=зачем
        local vyshlo=нет
        budit_smenu "$1" "$2" && vyshlo=да
        if [ "$vyshlo" = "$3" ]; then
            printf '  ок    %s\n' "$4"
        else
            printf '  ПЛОХО %s: вышло «%s», ждали «%s»\n' "$4" "$vyshlo" "$3"
            ok_flag=0
        fi
    }
    budit_proba 0 "hr.задача=ждёт слова владельца" нет \
        "БОЛЬНОЙ СЛУЧАЙ 26.09: работы нет, всё ждёт владельца — смену не будим"
    budit_proba 1 "hr.задача=ждёт слова владельца" да \
        "работа есть, хоть что-то и ждёт — будим"
    budit_proba 0 "" да \
        "ни работы, ни ждущих — прежнее поведение, будим"
    budit_proba "" "hr.задача=ждёт" да \
        "прибор очереди не ответил — будим, молчать из-за сломанного прибора нельзя"

    # ── «работы нет, смена у приглашения»: пульс и немота молчат ────────────
    # БОЛЬНОЙ СЛУЧАЙ 14.10.2026: очередь целиком заблокирована, ход закончен, а
    # владелец получил за 40 минут три ложных сигнала, смена — пинок каждый час.
    # Обвязку (что доходит до канала) судит scripts/test_warden_blocked_idle.sh.
    hold_proba() {  # $1=ждём $2=что вышло $3=зачем
        if [ "$2" = "$1" ]; then printf '  ок    %s\n' "$3"
        else printf '  ПЛОХО %s: вышло «%s», ждали «%s»\n' "$3" "$2" "$1"; ok_flag=0; fi
    }
    hold_got() { "$@" >/dev/null 2>&1 && echo да || echo нет; }
    # blocked_idle: работ, ждущие, слово владельца, отчёт, конец хода, ответ (epoch)
    hold_proba да  "$(hold_got blocked_idle 0 'hr.a=ждёт' 100 200 300 250)" \
        "БОЛЬНОЙ СЛУЧАЙ: работы нет, ход закончен после ответа, владелец молчит с отчёта — смена у приглашения"
    hold_proba нет "$(hold_got blocked_idle 0 'hr.a=ждёт' 300 200 400 250)" \
        "слово владельца новее отчёта — смена работает над ответом"
    hold_proba нет "$(hold_got blocked_idle 0 'hr.a=ждёт' 100 200 240 250)" \
        "ход не закончен (метка конца хода старше ответа) — смена работает или зависла"
    hold_proba да  "$(hold_got blocked_idle 0 'hr.a=ждёт' 100 200 250 250)" \
        "граница: конец хода в секунду ответа — ход закончен"
    hold_proba да  "$(hold_got blocked_idle 0 'hr.a=ждёт' 200 200 300 250)" \
        "граница: слово владельца в секунду отчёта — отчёт уже на него"
    hold_proba нет "$(hold_got blocked_idle 1 'hr.a=ждёт' 100 200 300 250)" \
        "есть работа (wip без блокера) — не «у приглашения»"
    hold_proba нет "$(hold_got blocked_idle 0 '' 100 200 300 250)" \
        "очередь пуста и ждущих нет — прежнее поведение"
    hold_proba нет "$(hold_got blocked_idle '' 'hr.x=ждёт' 100 200 300 250)" \
        "прибор очереди не ответил — прежнее поведение"
    hold_proba нет "$(hold_got blocked_idle 0 'hr.a=ждёт' 100 200 300 '')" \
        "успешного ответа в журнале нет — судить нечем, прежнее поведение"
    hold_proba молчу "$(SILENCE_MAX_MIN=45 PULSE_MAX_MIN=45 pulse_verdict 5 64 1 2>&1)" \
        "БОЛЬНОЙ СЛУЧАЙ п.1: смена у приглашения — пульс не пинает и владельца не зовёт"
    hold_proba пинок "$(SILENCE_MAX_MIN=45 PULSE_MAX_MIN=45 pulse_verdict 5 64 0 2>&1)" \
        "смена работает и не отчитывается дольше порога — пульс пинает, как прежде"
    hold_proba молчу "$(SILENCE_MAX_MIN=45 PULSE_MAX_MIN=45 pulse_verdict 5 10 0 2>&1)" \
        "отчёт свежий — пульс молчит"
    hold_proba молчу "$(SILENCE_MAX_MIN=45 PULSE_MAX_MIN=45 pulse_verdict 50 64 0 2>&1)" \
        "агент молчит дольше порога тишины — пульс не его ветка"
    hold_proba blocked "$(stall_reason 0 1 2>&1)" \
        "БОЛЬНОЙ СЛУЧАЙ п.2: немота без признака лимита у приглашения — повод «blocked»"
    hold_proba limit "$(stall_reason 1 1 2>&1)" \
        "признак лимита есть и у приглашения — повод «limit»"
    hold_proba nemota "$(stall_reason 0 0 2>&1)" \
        "немота при работе — повод «nemota»"
    unset -f hold_proba hold_got

    # ── признак завершения смены ─────────────────────────────────────────────
    смена() {  # ждём, сессия жива, панель, свежий id, уходящий id, имя случая
        local want="$1" got
        got=$(смена_состоялась "$2" "$3" "$4" "$5")
        [ "$got" = "$want" ] \
            && printf '  ок    %s\n' "$6" \
            || { printf '  ПЛОХО %s: ждали «%s», получили «%s»\n' "$6" "$want" "$got"; ok_flag=0; }
    }
    # БОЛЬНОЙ СЛУЧАЙ 12.08.2026, 14:40→14:55: юнит вернул claude в панель через
    # 10с после ухода сессии, сторож принял преемника за неушедшую старую и
    # 15 минут спустя разбудил владельца ложной тревогой.
    смена преемник 1 claude s2 s1 "БОЛЬНОЙ СЛУЧАЙ: в панели claude, но транскрипт другой — смену завершил юнит"
    смена ждём     1 claude s1 s1 "в панели claude и транскрипт тот же — старая сессия ещё пишет, ждём"
    смена ушла     0 ""     s1 s1 "tmux-сессии нет — ушла вместе с панелью, созданной командой"
    # БОЛЬНОЙ СЛУЧАЙ 13.08.2026: панель пережила агента (remain-on-exit), а
    # `pane_current_command` у неё так и показывает «claude» — опыт это
    # подтвердил. Не различив мертвеца, сторож ждал бы смены до самого таймаута.
    смена ушла     1 мертва s1 s1 "панель мертва — агент вышел, сессия цела (владельца не выбросило)"
    смена оболочка 1 bash   s1 s1 "панель снова оболочка — агент вышел"
    смена ждём     1 claude ""  s1 "транскрипта не видно — на пустом признаке смену не объявляем"

    # ── длинный ответ в канал уходит целиком ─────────────────────────────────
    # БОЛЬНОЙ СЛУЧАЙ 13.08.2026: владелец — «твои сообщения обрезаются, а они
    # вообще не должны иметь лимита». Обрезки в демоне больше нет; деление на
    # нумерованные части делает tg_send.sh, и его самотест — проверка того, что
    # текст доходит знак в знак. Грепом стережём возврат обрезки в этот файл.
    # Шаблон склеен из кусков нарочно: написанный целиком, он нашёл бы сам себя
    # в этой же строке и проверка краснела бы всегда.
    if grep -qE 'срез''_для_канала|полный''_ответ_файлом' "$0"; then
        printf '  ПЛОХО обрезка текста для канала вернулась в демон\n'; ok_flag=0
    else
        printf '  ок    БОЛЬНОЙ СЛУЧАЙ: обрезки текста для канала в демоне нет\n'
    fi
    # ── лимит подписки виден в ЖУРНАЛЕ, а не только на экране ─────────────
    # Настоящие записи сняты с транскрипта 12.09.2026: 20 отказов 429 за 160
    # минут, каждый — с типом assistant. Прибор немоты считал их работой.
    LIMIT_YARD=$(mktemp -d)
    NOW_ISO=$(date -u +%Y-%m-%dT%H:%M:%S.000Z)
    LONG_AGO_ISO=$(date -u -d '200 minutes ago' +%Y-%m-%dT%H:%M:%S.000Z)
    printf '%s\n' \
      "{\"type\":\"assistant\",\"timestamp\":\"$LONG_AGO_ISO\",\"message\":{\"content\":\"работа\"}}" \
      "{\"type\":\"assistant\",\"timestamp\":\"$NOW_ISO\",\"error\":\"rate_limit\",\"isApiErrorMessage\":true,\"apiErrorStatus\":429}" \
      > "$LIMIT_YARD/transkript.jsonl"

    STALL_PROBE=$(немота_агента_минут "$LIMIT_YARD/transkript.jsonl" || echo нет)
    if [ "$STALL_PROBE" != нет ] && [ "$STALL_PROBE" -ge 190 ]; then
        printf '  ок    БОЛЬНОЙ СЛУЧАЙ: отказ 429 работой не считается (немота %s мин)\n' "$STALL_PROBE"
    else
        printf '  ПЛОХО отказ лимита посчитан работой: немота %s мин вместо 200\n' "$STALL_PROBE"; ok_flag=0
    fi

    LIMIT_PROBE=$(лимит_в_транскрипте_минут "$LIMIT_YARD/transkript.jsonl" || echo нет)
    if [ "$LIMIT_PROBE" != нет ] && [ "$LIMIT_PROBE" -le 2 ]; then
        printf '  ок    лимит найден в журнале сессии (%s мин назад)\n' "$LIMIT_PROBE"
    else
        printf '  ПЛОХО лимит в журнале не найден: %s\n' "$LIMIT_PROBE"; ok_flag=0
    fi

    # БОЛЬНОЙ СЛУЧАЙ: лимит ПРОШЁЛ — отказ в журнале старше последнего успешного
    # ответа. Тревожить владельца нечем: смена работает.
    PROSHEL_ISO=$(date -u -d '15 minutes ago' +%Y-%m-%dT%H:%M:%S.000Z)
    printf '%s\n' \
      "{\"type\":\"assistant\",\"timestamp\":\"$PROSHEL_ISO\",\"error\":\"rate_limit\",\"isApiErrorMessage\":true,\"apiErrorStatus\":429}" \
      "{\"type\":\"assistant\",\"timestamp\":\"$NOW_ISO\",\"message\":{\"content\":\"снова работаю\"}}" \
      > "$LIMIT_YARD/proshel.jsonl"
    OTKAZ_MIN=$(лимит_в_транскрипте_минут "$LIMIT_YARD/proshel.jsonl" || echo нет)
    RABOTA_MIN=$(немота_агента_минут "$LIMIT_YARD/proshel.jsonl" || echo нет)
    if [ "$OTKAZ_MIN" != нет ] && [ "$RABOTA_MIN" != нет ] && [ "$OTKAZ_MIN" -ge "$RABOTA_MIN" ]; then
        printf '  ок    БОЛЬНОЙ СЛУЧАЙ: прошедший лимит (отказ %s мин, ответ %s мин) тревогой не считается\n' "$OTKAZ_MIN" "$RABOTA_MIN"
    else
        printf '  ПЛОХО прошедший лимит принят за действующий: отказ %s, ответ %s\n' "$OTKAZ_MIN" "$RABOTA_MIN"; ok_flag=0
    fi

    printf '%s\n' "{\"type\":\"assistant\",\"timestamp\":\"$NOW_ISO\",\"message\":{\"content\":\"обычный ответ\"}}" \
        > "$LIMIT_YARD/chistyj.jsonl"
    if лимит_в_транскрипте_минут "$LIMIT_YARD/chistyj.jsonl" >/dev/null 2>&1; then
        printf '  ПЛОХО лимит «найден» там, где его нет\n'; ok_flag=0
    else
        printf '  ок    БОЛЬНОЙ СЛУЧАЙ: чистый журнал лимита не показывает\n'
    fi
    # БОЛЬНОЙ СЛУЧАЙ 12.09.2026: владелец увидел лимит на экране, а сообщение
    # от харнеса пришло через 20 минут — порог немоты для ДОГАДКИ по экрану
    # применялся и к доказанному отказу 429. Условие входа в ветку проверяется
    # тем же выражением, что стоит в боевом коде.
    ГОВОРИМ_ПРИ() { # $1=немота, $2=доказан ли лимит машинным признаком
        local stall="$1" proven="$2"
        [ "$stall" -ge "${LIMIT_STALL_MIN:-20}" ] \
            || { [ "$proven" = 1 ] && [ "$stall" -ge "${LIMIT_SAY_MIN:-3}" ]; }
    }
    if ГОВОРИМ_ПРИ 5 1; then
        printf '  ок    БОЛЬНОЙ СЛУЧАЙ: доказанный лимит — владельцу говорим через 5 мин, а не через 20\n'
    else
        printf '  ПЛОХО доказанный лимит ждёт полного порога немоты\n'; ok_flag=0
    fi
    if ! ГОВОРИМ_ПРИ 5 0; then
        printf '  ок    догадка по экрану без немоты владельца не тревожит\n'
    else
        printf '  ПЛОХО экранная догадка подняла тревогу на 5-й минуте\n'; ok_flag=0
    fi
    if ГОВОРИМ_ПРИ 25 0; then
        printf '  ок    немота 25 мин — говорим и без машинного признака\n'
    else
        printf '  ПЛОХО долгая немота осталась без сообщения\n'; ok_flag=0
    fi
    unset -f ГОВОРИМ_ПРИ
    rm -rf "$LIMIT_YARD"

    # ── владельцу говорят о молчании смены (улика 12.09.2026) ─────────────
    # Прежде сторож пинал только агента: 180 минут молчания, восемнадцать
    # пинков, владельцу — ни слова. Он решил, что кончился лимит подписки.
    PULSE_YARD=$(mktemp -d)
    # Заглушки: настоящие tg_send и jlog определены НИЖЕ по файлу, а самотест
    # идёт выше — без них проба обрывалась на «jlog: command not found»
    # (наступил 12.09.2026, см. память: функция-bash-звана-до-определения).
    tg_send() { printf '%s\n' "$1" > "$PULSE_YARD/skazano"; }
    jlog() { :; }
    skazano_chto() { cat "$PULSE_YARD/skazano" 2>/dev/null || true; }
    LOG_DIR="$PULSE_YARD"
    PULSE_OWNER_MIN=60

    rm -f "$PULSE_YARD/skazano" "$PULSE_YARD/pulse.owner"
    сказать_владельцу_о_молчании 30 5 >/dev/null 2>&1
    if [ -z "$(skazano_chto)" ]; then
        printf '  ок    БОЛЬНОЙ СЛУЧАЙ: молчание короче порога — владельца не дёргаем\n'
    else
        printf '  ПЛОХО владельцу сказали о молчании в 30 мин при пороге 60\n'; ok_flag=0
    fi

    сказать_владельцу_о_молчании 180 9 >/dev/null 2>&1
    if printf '%s' "$(skazano_chto)" | grep -q '180 минут'; then
        printf '  ок    молчание 180 мин — владельцу сказано числом\n'
    else
        printf '  ПЛОХО владельцу о молчании 180 мин не сказано: %s\n' "$(skazano_chto)"; ok_flag=0
    fi

    rm -f "$PULSE_YARD/skazano"
    сказать_владельцу_о_молчании 190 9 >/dev/null 2>&1
    if [ -z "$(skazano_chto)" ]; then
        printf '  ок    повтор в кулдауне: второй раз подряд не пишем\n'
    else
        printf '  ПЛОХО кулдаун не держит: сказали дважды подряд\n'; ok_flag=0
    fi
    # БОЛЬНОЙ СЛУЧАЙ 12.09.2026: в журнале ВИДЕН лимит, а владельцу уходило
    # «с лимитом подписки это не связано». Два сигнала из одного сторожа
    # противоречили друг другу, и владелец назвал это обманом.
    rm -f "$PULSE_YARD/skazano" "$PULSE_YARD/pulse.owner"
    NOW_ISO=$(date -u -d '3 minutes ago' +%Y-%m-%dT%H:%M:%SZ)
    printf '{"type":"assistant","error":"rate_limit","timestamp":"%s"}\n' "$NOW_ISO" \
        > "$PULSE_YARD/limit.jsonl"
    TRANSCRIPT="$PULSE_YARD/limit.jsonl"
    сказать_владельцу_о_молчании 200 9 >/dev/null 2>&1
    if printf '%s' "$(skazano_chto)" | grep -q 'лимита подписки' \
       && ! printf '%s' "$(skazano_chto)" | grep -q 'не связано'; then
        printf '  ок    БОЛЬНОЙ СЛУЧАЙ: лимит виден — владельцу сказано о лимите, а не обратное\n'
    else
        printf '  ПЛОХО при видимом лимите сказано: %s\n' "$(skazano_chto)"; ok_flag=0
    fi

    # Доска старше косвенных признаков: смена сказала о себе прямо.
    rm -f "$PULSE_YARD/skazano" "$PULSE_YARD/pulse.owner"
    # Корень берём от пути САМОГО демона: PROJECT_DIR подключается ниже по
    # файлу, а самотест идёт выше — «unbound variable» обрывал бы пробы.
    PULSE_ROOT=$(cd "$(dirname "$(readlink -f "$0")")/../.." && pwd)
    HARNESS_DOSKA="$PULSE_YARD/доска.json" PROJECT_DIR="$PULSE_ROOT" \
        python3 "$PULSE_ROOT/scripts/board.py" --сказать смена \
        "жду ответа владельца по развилке выката" --на 60 >/dev/null 2>&1
    HARNESS_DOSKA="$PULSE_YARD/доска.json" PROJECT_DIR="$PULSE_ROOT" \
        сказать_владельцу_о_молчании 200 9 >/dev/null 2>&1
    # Проверяется СУТЬ, а не обёртка: слово смены обязано дойти до владельца
    # дословно. Прежняя проба искала фразу «Смена сообщает о себе», и когда
    # 13.09.2026 факт лимита подняли ВЫШЕ доски, обёртка стала другой («До
    # остановки смена делала: …»), а проба покраснела на исправном коде.
    # Проверка, привязанная к форме чужого текста, отстаёт от реализации
    # молча — правило записано в памяти как [[the-check-fell-behind-the-code]].
    if printf '%s' "$(skazano_chto)" | grep -q 'жду ответа владельца по развилке выката'; then
        printf '  ок    доска: слово смены доходит до владельца дословно\n'
    else
        printf '  ПЛОХО доска не прочитана, сказано: %s\n' "$(skazano_chto)"; ok_flag=0
    fi

    rm -f "$PULSE_YARD/skazano" "$PULSE_YARD/pulse.owner"
    printf '{"type":"assistant","timestamp":"%s"}\n' "$NOW_ISO" > "$PULSE_YARD/chisto.jsonl"
    TRANSCRIPT="$PULSE_YARD/chisto.jsonl"
    сказать_владельцу_о_молчании 200 9 >/dev/null 2>&1
    if printf '%s' "$(skazano_chto)" | grep -q 'признаков лимита подписки в журнале нет'; then
        printf '  ок    лимита в журнале нет — так и сказано, без утверждений сверх факта\n'
    else
        printf '  ПЛОХО без лимита сказано: %s\n' "$(skazano_chto)"; ok_flag=0
    fi

    # БОЛЬНОЙ СЛУЧАЙ п.4, 14.10.2026: отказ 429 был 99 мин назад, после него
    # смена отвечала, а владелец получил «Работа стоит из-за лимита подписки».
    rm -f "$PULSE_YARD/skazano" "$PULSE_YARD/pulse.owner"
    { printf '{"type":"assistant","error":"rate_limit","apiErrorStatus":429,"timestamp":"%s"}\n' \
          "$(date -u -d '99 minutes ago' +%Y-%m-%dT%H:%M:%SZ)"
      printf '{"type":"assistant","timestamp":"%s"}\n' \
          "$(date -u -d '5 minutes ago' +%Y-%m-%dT%H:%M:%SZ)"; } > "$PULSE_YARD/proshyol.jsonl"
    TRANSCRIPT="$PULSE_YARD/proshyol.jsonl"
    сказать_владельцу_о_молчании 200 5 >/dev/null 2>&1
    if [ -n "$(skazano_chto)" ] && ! printf '%s' "$(skazano_chto)" | grep -q 'из-за лимита'; then
        printf '  ок    БОЛЬНОЙ СЛУЧАЙ п.4: лимит прошёл (после отказа смена отвечала) — причиной не назван\n'
    else
        printf '  ПЛОХО прошедший лимит назван причиной: %s\n' "$(skazano_chto)"; ok_flag=0
    fi
    rm -f "$PULSE_YARD/skazano" "$PULSE_YARD/pulse.owner"
    { printf '{"type":"assistant","timestamp":"%s"}\n' \
          "$(date -u -d '10 minutes ago' +%Y-%m-%dT%H:%M:%SZ)"
      printf '{"type":"assistant","error":"rate_limit","apiErrorStatus":429,"timestamp":"%s"}\n' \
          "$(date -u -d '3 minutes ago' +%Y-%m-%dT%H:%M:%SZ)"; } > "$PULSE_YARD/derzhitsya.jsonl"
    TRANSCRIPT="$PULSE_YARD/derzhitsya.jsonl"
    сказать_владельцу_о_молчании 200 3 >/dev/null 2>&1
    if printf '%s' "$(skazano_chto)" | grep -q 'из-за лимита'; then
        printf '  ок    отказ свежее последнего ответа — лимит назван, как прежде\n'
    else
        printf '  ПЛОХО действующий лимит не назван: %s\n' "$(skazano_chto)"; ok_flag=0
    fi
    # Граница: отказ и последний ответ в одну минуту — отказ не СВЕЖЕЕ ответа,
    # как и в LIMIT_PROVEN (строгое «<»).
    rm -f "$PULSE_YARD/skazano" "$PULSE_YARD/pulse.owner"
    RAVNO_TS=$(date -u -d '5 minutes ago' +%Y-%m-%dT%H:%M:%SZ)
    { printf '{"type":"assistant","timestamp":"%s"}\n' "$RAVNO_TS"
      printf '{"type":"assistant","error":"rate_limit","apiErrorStatus":429,"timestamp":"%s"}\n' \
          "$RAVNO_TS"; } > "$PULSE_YARD/ravno.jsonl"
    TRANSCRIPT="$PULSE_YARD/ravno.jsonl"
    сказать_владельцу_о_молчании 200 5 >/dev/null 2>&1
    if [ -n "$(skazano_chto)" ] && ! printf '%s' "$(skazano_chto)" | grep -q 'из-за лимита'; then
        printf '  ок    граница: отказ в минуту последнего ответа — причиной не назван\n'
    else
        printf '  ПЛОХО отказ в минуту ответа назван причиной: %s\n' "$(skazano_chto)"; ok_flag=0
    fi
    unset TRANSCRIPT

    rm -rf "$PULSE_YARD"
    unset -f tg_send jlog skazano_chto

    # tg_send — от этого файла, а не из паспорта: в прогоне ворот по снимку
    # самотест судит снимок. Ищется в ОБЕИХ раскладках: в пакете скрипты под
    # harness/, после раскладки — в scripts/ корня проекта.
    WARDEN_DIR="$(dirname "$(readlink -f "${BASH_SOURCE[0]}")")"
    TG_SEND_ST="$WARDEN_DIR/../../scripts/tg_send.sh"
    [ -r "$TG_SEND_ST" ] || TG_SEND_ST="$WARDEN_DIR/../scripts/tg_send.sh"
    if "$TG_SEND_ST" --selftest >/dev/null 2>&1; then
        printf '  ок    доставка длинного текста частями: самотест tg_send прошёл\n'
    else
        printf '  ПЛОХО самотест tg_send упал — длинный текст владельцу под вопросом\n'; ok_flag=0
    fi

    # ── кулдаун разговора о заблокированной очереди (минуты, тот же механизм) ──
    блокировка() {  # ждём(да/нет), возраст в минутах, что проверяем
        local want="$1" age="$2" name="$3" got=нет
        подавлен_кулдауном "$age" 720 && got=да
        [ "$got" = "$want" ] \
            && printf '  ок    %s\n' "$name" \
            || { printf '  ПЛОХО %s: ждали «%s», получили «%s»\n' "$name" "$want" "$got"; ok_flag=0; }
    }
    # БОЛЬНОЙ СЛУЧАЙ: без кулдауна владелец получал бы «очередь ждёт вас»
    # каждый прогон сторожа — раз в 10 минут всю ночь.
    блокировка да  10 "БОЛЬНОЙ СЛУЧАЙ: сказано 10 мин назад — второй раз не пишем"
    блокировка нет 800 "прошло 800 мин (> 720) — напомнить пора"
    блокировка нет "" "ещё не говорили — говорим"

    # ── замер окна по транскрипту ────────────────────────────────────────────
    # Модель настоящего транскрипта: замер, а следом строка со снимком экрана.
    # Снимок — base64 картинки одной строкой; в живом файле такие весят
    # 199 КБ–1,29 МБ (замер 12.08.2026 по 85a3958d).
    W=$(mktemp -d)
    printf '{"message":{"usage":{"input_tokens":100000,"cache_read_input_tokens":44026}}}\n' > "$W/t.jsonl"
    python3 -c 'import sys; sys.stdout.write("{\"снимок\":\"" + "A"*250000 + "\"}\n")' >> "$W/t.jsonl"
    printf 'битая строка, не JSON\n' >> "$W/t.jsonl"
    : > "$W/пусто.jsonl"

    замер() {  # ждём, хвост в байтах, файл, имя случая
        local want="$1" got
        got=$(CTX_TAIL_BYTES="$2" окно_в_токенах "$3")
        [ "$got" = "$want" ] \
            && printf '  ок    %s\n' "$4" \
            || { printf '  ПЛОХО %s: ждали «%s», получили «%s»\n' "$4" "$want" "$got"; ok_flag=0; }
    }
    # БОЛЬНОЙ СЛУЧАЙ 12.08.2026, 19:50: в последних 200 КБ транскрипта было три
    # строки и ни одного замера — снимок экрана вытеснил его из окна чтения.
    # Сторож перешёл на прикидку «байты файла = окно», насчитал 669% и
    # ротировал здоровую сессию (через 10 минут она честно померилась как 42%).
    замер ""       200000  "$W/t.jsonl" "БОЛЬНОЙ СЛУЧАЙ: окно чтения 200 КБ занято снимком — замера нет, и это видно"
    замер 144026   2000000 "$W/t.jsonl" "штатный хвост 2 МБ перекрывает снимок — замер найден"
    замер ""       2000000 "$W/пусто.jsonl" "пустой транскрипт — замера нет"
    замер ""       2000000 "$W/нет-такого.jsonl" "файла нет — замера нет, без падения"
    rm -rf "$W"

    # ── распознавание диалога, перехватившего «/exit» ───────────────────────
    диалог() {  # ждём(да/нет), текст панели, имя случая
        local want="$1" got=нет
        диалог_выхода_в "$2" && got=да
        [ "$got" = "$want" ] \
            && printf '  ок    %s\n' "$3" \
            || { printf '  ПЛОХО %s: ждали «%s», получили «%s»\n' "$3" "$want" "$got"; ok_flag=0; }
    }
    # БОЛЬНОЙ СЛУЧАЙ 09.09.2026 (снимок владельца): панель после «/exit».
    # Имя ЛАТИНИЦЕЙ: кириллическое bash не берёт и печатает в ошибку само
    # значение — эта же правка на нём и споткнулась (память/cyrillic-in-bash-names).
    # Образец — ДОСЛОВНЫЙ снимок `tmux capture-pane` с живого CLI 2.1.258
    # (11.09.2026, воспроизведение случая владельца: фоновая задача в сессии
    # плюс «/exit»). Прежний образец здесь был ВЫДУМАН — со знаком «>» вместо
    # «❯», — и самотест был зелен на экране, которого не бывает: ротация
    # 02:00 не распознала диалог ни разу. Правишь образец — сними панель
    # заново, не пиши по памяти ([[a-check-creates-its-own-condition]]).
    DIALOG_SCREEN=$'❯ /exit\n\n  Background work is running\n  The following will stop when you exit:\n  shell · sleep 900\n  ❯ 1. Exit and stop tasks\n    2. Move to background and exit\n    3. Stay\n  Enter to confirm · Esc to cancel'
    # Тот же диалог в ASCII-режиме терминала: маркер «>» остаётся законным.
    DIALOG_SCREEN_ASCII=$'> /exit\n\nBackground work is running\nThe following will stop when you exit:\n\n shell · sleep 900\n\n> 1. Exit and stop tasks\n  2. Move to background and exit\n  3. Stay\n\nEnter to confirm · Esc to cancel'
    диалог да  "$DIALOG_SCREEN" "БОЛЬНОЙ СЛУЧАЙ: панель ждёт выбора после «/exit» — распознан"
    диалог да  "$DIALOG_SCREEN_ASCII" "тот же диалог со знаком «>» (ASCII-режим) — распознан"
    диалог нет "$(printf '%s\n' 'Всё сделано, жду задачи.' '> ')" "обычная панель — не диалог"
    # Строку «Background work is running» агент печатает и в отчёте ВЛАДЕЛЬЦУ про
    # этот самый случай: одной строки для Enter в панель мало.
    диалог нет "Отчёт: выход упёрся в Background work is running, чинил сторожем" \
        "рассказ агента про диалог — не диалог"
    # БОЛЬНОЙ СЛУЧАЙ 10.09.2026 (ревью): в самом файле сторожа лежит образец
    # экрана — подстрочный признак считал диалогом вывод grep по этому файлу.
    диалог нет "$(grep -F 'DIALOG_SCREEN=' "$0" | head -1)" \
        "строка исходника с образцом экрана — не диалог"
    диалог нет "$(printf '%s\n' 'Background work is running и дальше в той же строке текст' \
                  '  1. Exit and stop tasks' 'Enter to confirm')" \
        "заголовок не отдельной строкой — не диалог"
    диалог нет "$(printf '%s\n' 'Background work is running' 'Exit and stop tasks')" \
        "две строки без приглашения подтвердить — выбор уже сделан, не жмём"

    # БОЛЬНОЙ СЛУЧАЙ 21.09.2026: экран диалога остаётся в панели ПОСЛЕ выхода
    # агента — tmux показывает застывший хвост вместе со строкой «Resume this
    # session with». Признак по одному тексту был истинен 17 попыток подряд, и
    # сторож слал цифры и Escape в голую оболочку.
    живой() {  # ждём(да/нет), текст панели, команда панели, имя случая
        local want="$1" got=нет
        диалог_выхода_жив "$2" "$3" && got=да
        [ "$got" = "$want" ] \
            && printf '  ок    %s\n' "$4" \
            || { printf '  ПЛОХО %s: ждали «%s», получили «%s»\n' "$4" "$want" "$got"; ok_flag=0; }
    }
    живой да  "$DIALOG_SCREEN" claude "диалог на экране и claude в панели — жив, отвечаем"
    живой нет "$DIALOG_SCREEN" bash \
        "БОЛЬНОЙ СЛУЧАЙ: тот же экран, а в панели оболочка — агент ВЫШЕЛ, клавиш не шлём"
    живой нет "$DIALOG_SCREEN" мертва "панель мертва — отвечать некому"
    живой нет "обычная панель" claude "claude жив, диалога нет — не жмём"

    # БОЛЬНОЙ СЛУЧАЙ 10.09.2026: сорок Enter подряд за одну ротацию, двадцать
    # минут без агента. Лестница обязана МЕНЯТЬ ответ, а не повторять его.
    лестница() { # $1=ожидание $2=попытка $3=имя случая
        local got; got=$(клавиши_подтверждения "$2")
        [ "$got" = "$1" ] \
            && printf '  ок    %s\n' "$3" \
            || { printf '  ПЛОХО %s: ждали «%s», получили «%s»\n' "$3" "$1" "$got"; ok_flag=0; }
    }
    # ── признак лимита подписки (задача владельца 11.09.2026) ──────────────
    # Точного текста CLI при исчерпании лимита я не наблюдал, поэтому признак
    # широкий, а больной случай здесь — МОЙ отчёт со словом limit: приняв его
    # за лимит, сторож будил бы работающую смену.
    лимит() { # $1=ждём(да/нет) $2=текст панели $3=имя случая
        local got=нет
        признак_лимита_в "$2" && got=да
        if [ "$got" = "$1" ]; then printf '  ок    %s\n' "$3"
        else printf '  ПЛОХО %s: ждали «%s», получили «%s»\n' "$3" "$1" "$got"; ok_flag=0; fi
    }
    лимит нет "Отчёт владельцу: сделал контроль limit, работа идёт" \
        "БОЛЬНОЙ СЛУЧАЙ: мой отчёт со словом limit — не лимит"

    # ── возобновление: свежий отказ запрещает его объявлять ─────────────────
    # БОЛЬНОЙ СЛУЧАЙ 13.09.2026. Владелец получил цикл «работа встала → работа
    # возобновилась, простой 0 мин → встала»: сессия, стоящая в лимите, сама
    # дописывает в журнал записи об отказе, и «живость» журнала становится
    # истинной при стоящей работе. Ежеминутный limit-watch.sh чинён первым, а
    # ЗДЕСЬ жила вторая копия того же суждения — ревью кода 13.09 показало её
    # живой уликой: 06:40:02 «встала», 06:40:03 «возобновилась, простой 0 мин».
    W_SVEZH=$(mktemp -d)
    свежесть() { # $1=ждём(да/нет) $2=секунд назад $3=имя случая
        local jfile="$W_SVEZH/j.jsonl" got=нет
        python3 - "$jfile" "$2" <<'PYEOF'
import datetime, json, sys, time
момент = datetime.datetime.fromtimestamp(time.time() - int(sys.argv[2]), datetime.UTC)
open(sys.argv[1], "w", encoding="utf-8").write(
    json.dumps({"error": "rate_limit", "timestamp": момент.isoformat()}) + "\n")
PYEOF
        свежий_отказ "$jfile" && got=да
        if [ "$got" = "$1" ]; then printf '  ок    %s\n' "$3"
        else printf '  ПЛОХО %s: ждали «%s», получили «%s»\n' "$3" "$1" "$got"; ok_flag=0; fi
    }
    свежесть да 60 "БОЛЬНОЙ СЛУЧАЙ: отказ минуту назад — возобновление объявлять НЕЛЬЗЯ"
    свежесть нет 3600 "отказ час назад — работа действительно пошла"
    : > "$W_SVEZH/пусто.jsonl"
    if свежий_отказ "$W_SVEZH/пусто.jsonl"; then
        printf '  ПЛОХО пустой журнал принят за свежий отказ\n'; ok_flag=0
    else
        printf '  ок    отказов в журнале нет — свежим не считаем\n'
    fi
    rm -rf "$W_SVEZH"

    # БОЛЬНОЙ СЛУЧАЙ 11.09.2026: транскрипт СВЕЖИЙ по mtime, а агент молчал два
    # часа — в файл писались входящие (сообщения владельца, пинки сторожа).
    # Немота считается по последней записи type=assistant, иначе ветка «лимит»
    # не входит никогда.
    W_STALL=$(mktemp -d)
    STALE_TS=$(date -u -d '-90 minutes' +%Y-%m-%dT%H:%M:%S.000Z)
    FRESH_TS=$(date -u +%Y-%m-%dT%H:%M:%S.000Z)
    {
        printf '{"type":"assistant","timestamp":"%s"}\n' "$STALE_TS"
        printf '{"type":"user","timestamp":"%s"}\n' "$FRESH_TS"
    } > "$W_STALL/t.jsonl"
    STALL_GOT=$(немота_агента_минут "$W_STALL/t.jsonl")
    if [ "${STALL_GOT:-0}" -ge 85 ] && [ "${STALL_GOT:-0}" -le 95 ]; then
        printf '  ок    БОЛЬНОЙ СЛУЧАЙ: немота агента считается мимо свежих входящих (%s мин)\n' "$STALL_GOT"
    else
        printf '  ПЛОХО немота агента: ждали ~90 мин, получили «%s»\n' "$STALL_GOT"; ok_flag=0
    fi
    rm -rf "$W_STALL"
    # ДОСЛОВНАЯ строка с экрана владельца (снимок 11.09.2026). Прежний образец
    # её НЕ ловил: между «limit» и «resets» стоит « · ».
    лимит да  "You've hit your session limit · resets 2:50pm (Asia/Qostanay)" \
        "БОЛЬНОЙ СЛУЧАЙ: живая строка лимита со снимка владельца"
    лимит да  "/upgrade to increase your usage limit." "вторая строка живого экрана"
    лимит да  "Claude AI usage limit reached · resets 9am" "исчерпан лимит подписки"
    лимит да  "5-hour limit reached" "почасовой лимит"

    # Через сколько сброс — задача владельца 11.09.2026. Час берём из строки
    # CLI; больной случай — строка БЕЗ времени: врать про срок нельзя.
    сброс() { # $1=ждём(есть/нет) $2=строка $3=имя случая
        local got=нет
        [ -n "$(через_сколько_сброс "$2")" ] && got=есть
        if [ "$got" = "$1" ]; then printf '  ок    %s\n' "$3"
        else printf '  ПЛОХО %s: ждали «%s», получили «%s»\n' "$3" "$1" "$got"; ok_flag=0; fi
    }
    сброс нет "Claude usage limit reached" \
        "БОЛЬНОЙ СЛУЧАЙ: строка без времени сброса — срок не выдумываем"
    сброс есть "You've hit your session limit · resets 2:50pm (Asia/Qostanay)" \
        "БОЛЬНОЙ СЛУЧАЙ: время сброса из живой строки владельца"
    сброс есть "Claude usage limit reached · resets 6pm" "время сброса в 12-часовом виде"
    сброс есть "5-hour limit reached · resets at 18:30" "время сброса в 24-часовом виде"
    # ── БОЛЬНОЙ СЛУЧАЙ 27.09.2026 (снимок владельца): «зачем сторож пинает
    # постоянно. если известно когда лимит обновится, можно пнуть в то время.
    # также нужно мне в сообщении писать во сколько и через сколько обновится
    # лимит, потому что сейчас эта информация пропала» ──
    #
    # Пробы идут на НАСТОЯЩЕМ транскрипте, а не на рукописном образце: первая
    # редакция этих проб была собрана из придуманной строки jsonl, и мимо неё
    # прошли две критические находки ревью — разбор объявлял лимитом почти любой
    # журнал и тянул в сообщение владельцу 15 КБ ([[capture-foreign-output-do-not-recall-it]]).
    T_LIM=$(mktemp -d)
    # Без конвейера с head: он роняет ls сигналом SIGPIPE, а под `pipefail` это
    # код 141 — самотест обрывался молча посередине.
    ZHIVOJ=""
    for kandidat in $(ls -t "$HOME/.claude/projects/"*/*.jsonl 2>/dev/null); do
        ZHIVOJ="$kandidat"; break
    done
    if [ -n "$ZHIVOJ" ] && [ -r "$ZHIVOJ" ]; then
        tail -c 2000000 "$ZHIVOJ" > "$T_LIM/живой.jsonl"
        OTVET=$(сброс_по_журналу "$T_LIM/живой.jsonl")
        DLINA=${#OTVET}
        STROK=$(printf '%s' "$OTVET" | grep -c . || true)
        if [ "$DLINA" -le 120 ] && [ "${STROK:-0}" -le 1 ]; then
            echo "  ок    БОЛЬНОЙ СЛУЧАЙ: на ЖИВОМ транскрипте ответ короткий и в одну строку ($DLINA знаков)"
        else echo "  ПЛОХО на живом транскрипте ответ распух: $DLINA знаков, строк ${STROK:-0}"; ok_flag=0; fi
        if [ -z "$OTVET" ] || printf '%s' "$OTVET" | grep -qE '^-?[0-9]+	в [0-9]{1,2}:[0-9]{2}, через '; then
            echo "  ок    ответ прибора — «минуты + в HH:MM, через …» или пусто"
        else echo "  ПЛОХО форма ответа прибора: «$OTVET»"; ok_flag=0; fi
    else
        echo "  ПЛОХО живого транскрипта не нашлось — проба на настоящих данных не сделана"; ok_flag=0
    fi
    # Журнал БЕЗ записей отказа: ни лимита, ни времени — и слова «429» в обычном
    # JSON не должны его выдумать (CRITICAL-1: так объявлялся лимит почти всегда).
    printf '%s\n' '{"type":"assistant","message":{"usage":{"output_tokens":429}},"text":"hit your session limit · resets 9pm"}' > "$T_LIM/без-отказа.jsonl"
    if [ -z "$(сброс_по_журналу "$T_LIM/без-отказа.jsonl")" ]; then
        echo "  ок    БОЛЬНОЙ СЛУЧАЙ: «429» в обычном JSON лимитом не считается"
    else echo "  ПЛОХО лимит выдуман из числа 429 в полях расхода"; ok_flag=0; fi
    # Настоящая запись отказа: время берётся ЧИСЛОМ из resetsAt.
    SBROS_TS=$(( $(date +%s) + 1800 ))
    printf '{"type":"assistant","isApiErrorMessage":true,"apiErrorStatus":429,"quotaLimits":{"status":"rejected","resetsAt":%s}}\n' "$SBROS_TS" > "$T_LIM/отказ.jsonl"
    OTVET=$(сброс_по_журналу "$T_LIM/отказ.jsonl")
    if printf '%s' "$OTVET" | grep -q 'через 29 мин\|через 30 мин'; then
        echo "  ок    время сброса взято числом из записи отказа"
    else echo "  ПЛОХО время сброса из записи отказа: «$OTVET»"; ok_flag=0; fi
    # ПРЕДОХРАНИТЕЛЬ проверяется ПОВЕДЕНИЕМ: прежняя проба грепала своё же имя в
    # тексте файла, и мутации «порог перевёрнут» и «порог удалён» оставались
    # зелёными (MAJOR-3 ревью 27.09.2026). Судим САМО РЕШЕНИЕ боевой ветки.
    # Порог LIMIT_KICK_MAX_MIN берётся из окружения (конфиг уже загружен выше).
    if глушить_пинок 1 1793363410 10; then
        echo "  ок    БОЛЬНОЙ СЛУЧАЙ 30.10.2026: срок назван — до подъёма пинка нет"
    else echo "  ПЛОХО пинок ушёл до подъёма при названном сроке"; ok_flag=0; fi
    if глушить_пинок 1 1793363410 9999; then
        echo "  ок    срок назван — молчим, сколько бы ни прошло с прошлого пинка"
    else echo "  ПЛОХО предохранитель сработал при названном сроке"; ok_flag=0; fi
    if глушить_пинок 1 "" 10; then
        echo "  ок    срок неизвестен, пинок был недавно — молчим"
    else echo "  ПЛОХО пинок тратится при неизвестном сроке сразу после пинка"; ok_flag=0; fi
    if ! глушить_пинок 1 "" "${LIMIT_KICK_MAX_MIN:-60}"; then
        echo "  ок    БОЛЬНОЙ СЛУЧАЙ: срок неизвестен, час тишины — будим"
    else echo "  ПЛОХО неизвестный срок заглушил бы работу на сутки"; ok_flag=0; fi
    if ! глушить_пинок 0 1793363410 10; then
        echo "  ок    БОЛЬНОЙ СЛУЧАЙ: лимит не доказан — немую смену будят как прежде"
    else echo "  ПЛОХО без доказанного лимита пинки глушатся"; ok_flag=0; fi
    rm -rf "$T_LIM"

    лимит да  "Weekly limit exceeded" "недельный лимит"
    лимит да  "Upgrade to continue" "предложение перейти на другой план"
    лимит нет "Ход идёт, всё в порядке" "обычная панель — не лимит"
    # Строка владельцу берётся тем же выражением: по одному слову «limit»
    # первой находилась строка приглашения оболочки (проба 11.09.2026).
    # Имя помощника — своё: боевая функция с похожим именем брала бы аргументы
    # в другом смысле, и проба ниже молча мерила бы не то ([[module-name-already-taken]],
    # находка MAJOR-5 ревью 27.09.2026).
    проба_строки_лимита() { # $1=ждём $2=панель $3=имя случая
        local got; got=$(строка_лимита_в "$2")
        if [ "$got" = "$1" ]; then printf '  ок    %s\n' "$3"
        else printf '  ПЛОХО %s: ждали «%s», получили «%s»\n' "$3" "$1" "$got"; ok_flag=0; fi
    }
    проба_строки_лимита "Claude AI usage limit reached · resets 9am" \
        "$(printf '%s\n' 'agent@host:~$ что-то про limit писал я' 'Claude AI usage limit reached · resets 9am')" \
        "БОЛЬНОЙ СЛУЧАЙ: владельцу уходит строка ЛИМИТА, а не приглашение оболочки"

    # ── снимки терминала (задача владельца 13.09.2026) ────────────────────
    # «Можно сделать механизм который делает скриншоты терминала чтобы потом
    # разбираться?» Улика того же дня: диалог выхода не поддался десять раз, а
    # от экрана в журнале осталось 400 знаков — по ним не видно ни всего
    # списка задач, ни того, что было ВЫШЕ диалога.
    snimki_dom=$(mktemp -d)
    SNIMKI_DIR="$snimki_dom" SNIMKOV_HRANIM=3 \
        сохранить_снимок "диалог-выхода" "$DIALOG_SCREEN" >/dev/null
    snimkov=$(find "$snimki_dom" -name '*.txt' | wc -l | tr -d ' ')
    pervyj=$(find "$snimki_dom" -name '*диалог-выхода*' | head -1)
    if [ "$snimkov" = 1 ] && grep -q 'Exit and stop tasks' "$pervyj" 2>/dev/null; then
        printf '  ок    снимок панели лёг файлом и содержит экран целиком\n'
    else
        printf '  ПЛОХО снимок не сохранён: файлов %s\n' "$snimkov"; ok_flag=0
    fi
    # БОЛЬНОЙ СЛУЧАЙ: без предела снимки съедят диск — за сутки тревог бывает
    # сотня. Храним последние N, лишнее сносим САМИ, а не ждём уборщика.
    for n in 1 2 3 4 5; do
        SNIMKI_DIR="$snimki_dom" SNIMKOV_HRANIM=3 \
            сохранить_снимок "proba-$n" "экран $n" >/dev/null
        sleep 1.01
    done
    ostalos=$(find "$snimki_dom" -name '*.txt' | wc -l | tr -d ' ')
    if [ "$ostalos" = 3 ]; then
        printf '  ок    БОЛЬНОЙ СЛУЧАЙ: снимков хранится ровно 3, старые снесены\n'
    else
        printf '  ПЛОХО предел снимков не держится: осталось %s, ждали 3\n' "$ostalos"; ok_flag=0
    fi
    poslednij=$(find "$snimki_dom" -name '*.txt' | sort | tail -1)
    if grep -q 'экран 5' "$poslednij" 2>/dev/null; then
        printf '  ок    снесены САМЫЕ СТАРЫЕ: последний снимок на месте\n'
    else
        printf '  ПЛОХО снесён свежий снимок: %s\n' "$poslednij"; ok_flag=0
    fi
    rm -rf "$snimki_dom"

    лестница "Enter"   1 "первая попытка — подтверждаем подсвеченный пункт"
    лестница "Enter"   2 "вторая — тем же, случайный промах прощаем"
    лестница "ПУНКТ Enter" 3 "третья — называем пункт явно; номер подставится с экрана"
    # БОЛЬНОЙ СЛУЧАЙ 13.09.2026, 04:58–05:01: десять попыток подряд, пункт
    # «Exit and stop tasks» подсвечен, клавиши уходят («1=ок, Enter=ок») — и
    # диалог стоит. В списке четыре фоновые задачи shell, среди них отвязанные
    # setsid: остановить их выход не может, поэтому и не завершается. Дальше
    # давить тот же пункт бессмысленно — уходим ФОНОМ, он ничего не ждёт.
    лестница "ФОНОМ Enter" 4 "четвёртая — пункт «остановить задачи» не поддался, уходим фоном"
    лестница "ФОНОМ Enter" 5 "пятая — тем же"
    лестница "Escape"  6 "шестая — диалог не поддался, сбрасываем и подаём «/exit» заново"
    лестница "Escape" 40 "сороковая — прежний сторож слал бы Enter, теперь путь другой"
    пункт() { # $1=ожидание $2=текст панели $3=имя случая
        local got; got=$(подсвеченный_пункт_в "$2")
        [ "$got" = "$1" ] \
            && printf '  ок    %s\n' "$3" \
            || { printf '  ПЛОХО %s: ждали «%s», получили «%s»\n' "$3" "$1" "$got"; ok_flag=0; }
    }
    пункт "1. Exit and stop tasks" "$DIALOG_SCREEN" "подсвеченный пункт виден в журнале, а не сорок одинаковых строк"
    пункт "3. Stay" "$(printf '%s\n' '> /exit' '  1. Exit and stop tasks' '> 3. Stay')" \
        "БОЛЬНОЙ СЛУЧАЙ: подсветка уехала на «Stay» — в журнале будет видно, почему выход не идёт"
    пункт "" "обычная панель без диалога" "диалога нет — пункта нет"
    номер_пункта() { # $1=ожидание $2=текст $3=имя
        local got; got=$(номер_пункта_выхода "$2")
        [ "$got" = "$1" ] && printf '  ок    %s\n' "$3" \
            || { printf '  ПЛОХО %s: ждали «%s», получили «%s»\n' "$3" "$1" "$got"; ok_flag=0; }
    }
    номер_пункта "1" "$DIALOG_SCREEN" "номер пункта выхода берётся с экрана, а не вшит"
    номер_пункта "2" "$(printf '%s\n' '  1. Stay' '> 2. Exit and stop tasks')" \
        "БОЛЬНОЙ СЛУЧАЙ: порядок пунктов сменился — берём верный номер, а не «1»"
    номер_пункта "" "обычная панель" "пунктов нет — номера нет, шлём Enter"
    фоном() { # $1=ожидание $2=текст $3=имя
        local got; got=$(номер_пункта_фоном "$2")
        [ "$got" = "$1" ] && printf '  ок    %s\n' "$3" \
            || { printf '  ПЛОХО %s: ждали «%s», получили «%s»\n' "$3" "$1" "$got"; ok_flag=0; }
    }
    фоном "2" "$DIALOG_SCREEN" "номер пункта «уйти фоном» берётся с экрана"
    фоном "3" "$(printf '%s\n' '  1. Exit and stop tasks' '  2. Stay' '  3. Move to background and exit')" \
        "БОЛЬНОЙ СЛУЧАЙ: порядок пунктов сменился — берём верный номер, а не «2»"
    фоном "" "обычная панель" "пункта «фоном» нет — номера нет, шлём Enter"

    # ── способ ротации: «/clear» или полный перезапуск (решение владельца 11.09) ──
    способ() { # $1=ждём $2..$7 аргументы $8=имя случая
        local got; got=$(способ_ротации "$2" "$3" "$4" "$5" "$6" "$7" "${9:-0}")
        [ "$got" = "$1" ] && printf '  ок    %s\n' "$8" \
            || { printf '  ПЛОХО %s: ждали «%s», получили «%s»\n' "$8" "$1" "$got"; ok_flag=0; }
    }
    # БОЛЬНОЙ СЛУЧАЙ: правка хуков без перезапуска процесса не применяется —
    # сторож бы «сменил сессию», а работал бы прежний код.
    способ full  1 0 1 24 0 0 "правились хуки или настройки — только полный перезапуск"
    способ full  0 1 1 24 0 0 "сменилась версия CLI — процесс держит старую"
    способ full  0 0 24 24 0 0 "сутки без полного перезапуска — память процесса не освобождалась"
    способ full  0 0 1 24 1 0 "«/clear» подан, а окно не упало — уходим тяжёлым путём"
    способ full  0 0 1 24 0 1 "агент попросил выйти сам (--rotate-now, смена модели)"
    способ clear 0 0 1 24 0 0 "обычный случай: окно подошло к порогу — быстрый путь"
    способ clear 0 0 23 24 0 0 "23 часа из 24 — порог не достигнут, ещё быстрый путь"
    способ full  1 1 99 24 1 1 "всё сразу — полный, а не наоборот"
    способ full  0 0 1 24 0 0 "перезагрузка встала бы (7-й довод) — тяжёлый путь, «/exit» заменит она" 1
    способ clear 0 0 1 24 0 0 "перезагрузка не встала бы — быстрый путь, как раньше" 0

    # ── перезагрузка в окне ротации: слово и код чистой функции ───────────────
    # Ошибка здесь — настоящая перезагрузка машины, поэтому каждое «нет» судится
    # своей причиной, а не только кодом.
    перезагрузка() { # $1=ждём (слово;код) $2=образец причины $3..$13 аргументы $14=имя случая
        local want="$1" pat="$2" out rc=0; shift 2
        out=$(reboot_window_verdict "${@:1:11}") || rc=$?
        if [ "${out%%:*};$rc" = "$want" ] && printf '%s' "$out" | grep -qi -- "$pat"; then printf '  ок    %s\n' "${12}"
        else printf '  ПЛОХО %s: ждали «%s» с «%s», получили «%s;%s»\n' "${12}" "$want" "$pat" "$out" "$rc"; ok_flag=0; fi
    }
    перезагрузка "перезагрузить;0" . 1 "neighbour-1" 0 выход 0 0 0 1 72 24 0 "окно ротации, всё «да» — перезагрузить"
    перезагрузка "нет;1" AUTO_REBOOT 0 "neighbour-1" 0 выход 0 0 0 1 72 24 0 "ключ 0 — выключено, первым"
    перезагрузка "нет;1" "соседи не названы" 1 "" 0 выход 0 0 0 1 72 24 0 "соседи не названы владельцем — нет"
    перезагрузка "нет;1" пауз 1 "neighbour-1" 1 выход 0 0 0 1 72 24 0 "пауза владельца — нет"
    перезагрузка "нет;1" ходу 1 "neighbour-1" 0 принудительно 0 0 0 1 72 24 0 "принудительно: агент в ходу, перезагрузка оборвала бы его"
    перезагрузка "нет;1" фонов 1 "neighbour-1" 0 выход 1 0 0 1 72 24 0 "фоновая задача сессии жива — нет"
    перезагрузка "нет;1" "помощ.*2" 1 "neighbour-1" 0 выход 0 2 0 1 72 24 0 "идут помощники — нет"
    перезагрузка "нет;1" "помощники неизвестны" 1 "neighbour-1" 0 выход 0 "?" 0 1 72 24 0 "помощники «?» — нет"
    перезагрузка "нет;1" "занята.*резервная" 1 "neighbour-1" 0 выход 0 0 "резервная копия" 1 72 24 0 "машина занята — нет"
    перезагрузка "нет;1" "не нужна" 1 "neighbour-1" 0 выход 0 0 0 0 72 24 0 "перезагрузка не нужна — нет"
    перезагрузка "нет;1" неизвестно 1 "neighbour-1" 0 выход 0 0 0 "?" 72 24 0 "нужна ли — неизвестно — нет"
    перезагрузка "нет;1" загружена 1 "neighbour-1" 0 выход 0 0 0 1 3 24 0 "загрузка 3 ч назад при пределе 24 — петля, нет"
    перезагрузка "нет;1" ядро 1 "neighbour-1" 0 выход 0 0 0 1 72 24 1 "прошлая перезагрузка не сменила ядро — нужен владелец"

    # ── дверь ротации: без передачи сессию не меняем (владелец 18.10.2026) ──
    dver() { # $1=ждём $2..$5 аргументы $6=имя случая
        # Судятся ОБА ответа функции — слово и код возврата: вызывающий
        # смотрит на код, а журнал печатает слово, и разъехаться им нельзя.
        # `|| rc=$?` обязателен: под `set -e` отказ в подстановке убил бы
        # самотест на первом же больном случае ([[exit-code-read-after-if]]).
        local got rc=0 want_rc=1
        got=$(ротация_разрешена "$2" "$3" "$4" "${5:-}") || rc=$?
        got="${got%%:*}"
        [ "$1" = да ] && want_rc=0
        if [ "$got" = "$1" ] && [ "$rc" = "$want_rc" ]; then
            printf '  ок    %s\n' "$6"
        else
            printf '  ПЛОХО %s: ждали «%s» (код %s), получили «%s» (код %s)\n' "$6" "$1" "$want_rc" "$got" "$rc"
            ok_flag=0
        fi
    }
    # БОЛЬНОЙ СЛУЧАЙ 18.10.2026: смена молчит под лимитом, передачи нет — а
    # прежний сторож читал это молчание как «регламент отработан».
    dver нет 0 0 0 ""                      "передачи нет — сессию не меняем"
    dver нет 0 1 0 ""                      "передачи нет и держится лимит — отказ называет лимит"
    dver да  1 1 0 ""                      "передача есть — лимит смене не мешает, терять нечего"
    dver да  1 0 0 ""                      "передача написана, лимита нет — обычный случай, меняем"
    dver нет 0 0 1 ""                      "принуждение без названной причины — отказ"
    dver да  0 0 1 "смена модели"          "принуждение с причиной — законная дверь открыта"
    dver нет 0 1 1 "смена модели"          "лимит старше принуждения: передачу писать всё равно нечем"

    # Числа в итоговой строке — доказательство для владельца, поэтому они
    # сверяются с файлом, а не обновляются по памяти: 11.09.2026 там стояло «4
    # пути распознавания» при семи фактических (расхождение с правки 10.09).
    # ── кнопка панели «ревизия сейчас»: флаг снимается, демон зовётся раз ──
    KNOPKA_T=$(mktemp -d)
    KNOPKA_FLAG="$KNOPKA_T/запуск"
    KNOPKA_ZOV="$KNOPKA_T/зовы"
    printf '#!/usr/bin/env bash\nprintf "%%s\\n" "$*" >> "%s"\n' "$KNOPKA_ZOV" > "$KNOPKA_T/demon.sh"
    chmod +x "$KNOPKA_T/demon.sh"
    LOG_DIR_SAVE="$LOG_DIR"; LOG_DIR="$KNOPKA_T"
    # Выключатель фоновых читает конфиг из файла: живой с BACKGROUND_PROCESSES=off
    # гасил запуск, и случаи краснели от состояния прода, а не от кнопки.
    printf 'BACKGROUND_PROCESSES=on\n' > "$KNOPKA_T/harness.conf"

    HARNESS_CONF="$KNOPKA_T/harness.conf" knopka_revizii "$KNOPKA_FLAG" "$KNOPKA_T/demon.sh"
    sleep 0.3
    if [ ! -s "$KNOPKA_ZOV" ]; then
        printf '  ок    кнопка ревизии: флага нет — демон не зван\n'
    else
        printf '  ПЛОХО кнопка ревизии: демон зван без флага\n'; ok_flag=0
    fi

    : > "$KNOPKA_FLAG"
    HARNESS_CONF="$KNOPKA_T/harness.conf" knopka_revizii "$KNOPKA_FLAG" "$KNOPKA_T/demon.sh"
    sleep 0.5
    if [ ! -e "$KNOPKA_FLAG" ] && grep -q -- '--сейчас' "$KNOPKA_ZOV" 2>/dev/null; then
        printf '  ок    БОЛЬНОЙ СЛУЧАЙ: флаг есть — снят, демон зван с --сейчас\n'
    else
        printf '  ПЛОХО кнопка ревизии: флаг %s, зовы «%s»\n' \
            "$([ -e "$KNOPKA_FLAG" ] && echo остался || echo снят)" "$(cat "$KNOPKA_ZOV" 2>/dev/null)"; ok_flag=0
    fi

    HARNESS_CONF="$KNOPKA_T/harness.conf" knopka_revizii "$KNOPKA_FLAG" "$KNOPKA_T/demon.sh"
    sleep 0.3
    if [ "$(grep -c -- '--сейчас' "$KNOPKA_ZOV" 2>/dev/null)" = "1" ]; then
        printf '  ок    второй проход без флага демона не зовёт\n'
    else
        printf '  ПЛОХО кнопка ревизии: демон зван повторно\n'; ok_flag=0
    fi
    LOG_DIR="$LOG_DIR_SAVE"
    rm -rf "$KNOPKA_T"

    # ── пауза владельца гасит подгоняющие ветки ─────────────────────────────
    # БОЛЬНОЙ СЛУЧАЙ 14.09.2026: смена стояла по решению владельца, а сторож
    # пинал её и слал «работа встала». Судится ТОТ ЖЕ разбор, что и в бою.
    PAUZA_T=$(mktemp -d)
    PAUZA_PY="$HARNESS_SCRIPTS/pause.py"
    if HARNESS_PANEL_STATE="$PAUZA_T" python3 "$PAUZA_PY" --идёт-ли; then
        printf '  ПЛОХО пауза: пустой каталог состояния прочитан как пауза
'; ok_flag=0
    else
        printf '  ок    БОЛЬНОЙ СЛУЧАЙ: паузы нет — присмотр работает
'
    fi
    HARNESS_PANEL_STATE="$PAUZA_T" python3 "$PAUZA_PY" --поставить "проба" >/dev/null
    if HARNESS_PANEL_STATE="$PAUZA_T" python3 "$PAUZA_PY" --идёт-ли; then
        printf '  ок    пауза поставлена — присмотр молчит
'
    else
        printf '  ПЛОХО пауза поставлена, а разбор её не видит
'; ok_flag=0
    fi
    HARNESS_PANEL_STATE="$PAUZA_T" python3 "$PAUZA_PY" --снять >/dev/null
    if HARNESS_PANEL_STATE="$PAUZA_T" python3 "$PAUZA_PY" --идёт-ли; then
        printf '  ПЛОХО пауза снята, а разбор её всё ещё видит
'; ok_flag=0
    else
        printf '  ок    пауза снята — присмотр снова работает
'
    fi
    rm -rf "$PAUZA_T"

    # ── решение лимитной ветки: БОЛЬНОЙ СЛУЧАЙ — её не проверял НИКТО ────────
    # Ревью 27.09.2026 (F-lim-06): самотест кончается здесь, а ветка лимита
    # живёт ниже 2600 — любая мутация в ней зелена по построению. Теперь
    # суждение вынуто чистой функцией и судится таблицей.
    limit_proba() {  # $1..$5 вход решения, $6 ждём, $7 зачем
        local vyshlo
        vyshlo=$(LIMIT_STALL_MIN=20 LIMIT_SAY_MIN=3 решение_лимита "$1" "$2" "$3" "$4" "$5")
        if [ "$vyshlo" = "$6" ]; then
            printf '  ок    лимит-решение %s\n' "$7"
        else
            printf '  ПЛОХО лимит-решение %s: вышло «%s», ждали «%s»\n' "$7" "$vyshlo" "$6"
            ok_flag=0
        fi
    }
    #            немота доказан виден метка свежий   ждём              зачем
    limit_proba      3      1      1     0     1  объявить-лимит \
        "доказанный лимит говорит владельцу через 3 минуты, а не через 20"
    limit_proba      3      0      0     0     0  молчу \
        "три минуты немоты без доказательства — не повод будить владельца"
    limit_proba     20      0      0     0     0  объявить-немоту \
        "двадцать минут немоты без признака лимита — немота, а не лимит"
    limit_proba     20      0      1     0     0  объявить-лимит \
        "признак лимита на экране при немоте — говорим про лимит"
    limit_proba     25      1      1     1     1  пинок \
        "о простое уже сказано — второй раз владельцу не пишем, только будим"
    limit_proba      1      0      0     1     0  возобновление \
        "смена пишет и отказов нет — работа пошла"
    limit_proba      1      0      0     1     1  молчу \
        "БОЛЬНОЙ СЛУЧАЙ 13.09: журнал свеж, но отказ свежий — это не возобновление"
    limit_proba     30      1      1     1     0  пинок \
        "метка стоит, отказов нет, но смена молчит 30 мин — это ещё не жизнь"
    limit_proba     10      1      1     1     0  пинок \
        "БОЛЬНОЙ СЛУЧАЙ 27.09 (снимок владельца): немота 10 мин и отказ 9-минутной давности — лимит держится, а не обновился"
    limit_proba     10      0      0     1     0  молчу \
        "смена молчит 10 минут — она не пишет, о возобновлении говорить нечего"
    limit_proba      3      0      0     1     0  молчу \
        "ровно порог немоты — ещё не работа: возобновление начинается СТРОГО ниже него"
    limit_proba      7      1      1     1     0  пинок \
        "БОЛЬНОЙ СЛУЧАЙ (ревью 27.09, F-02): доказанный лимит не бывает возобновлением — даже когда владелец поставил LIMIT_SAY_MIN больше порога свежести"
    limit_proba      0      0      0     0     0  молчу \
        "тишины нет — сторожу сказать нечего"

    CLAIMED=$(sed -n 's/.*зелёный (\([0-9]*\) путей распознавания диалога выхода.*/\1/p' "$0" | head -1)
    COUNTED=$(grep -cE '^[[:space:]]+диалог (да|нет) ' "$0")
    if [ "$CLAIMED" != "$COUNTED" ]; then
        printf '  ПЛОХО итоговая строка: заявлено %s путей распознавания, в файле %s\n' \
            "$CLAIMED" "$COUNTED"; ok_flag=0
    else
        printf '  ок    итоговая строка сходится с файлом: %s путей распознавания\n' "$COUNTED"
    fi

    CLAIMED_Z=$(sed -n 's/.*+ \([0-9]*\) пути живого диалога.*/\1/p' "$0" | head -1)
    COUNTED_Z=$(grep -cE '^[[:space:]]+живой (да|нет) ' "$0")
    if [ "$CLAIMED_Z" != "$COUNTED_Z" ]; then
        printf '  ПЛОХО итоговая строка: заявлено %s путей живого диалога, в файле %s\n' \
            "$CLAIMED_Z" "$COUNTED_Z"; ok_flag=0
    else
        printf '  ок    итоговая строка сходится с файлом: %s пути живого диалога\n' "$COUNTED_Z"
    fi

    (( ok_flag )) && { echo "SELFTEST: зелёный (7 путей распознавания диалога выхода + 4 пути живого диалога (текст + кто в панели) + 2 пути висячего Escape в оболочке + 6 путей лестницы ответов + 3 пути подсвеченного пункта + 3 пути номера пункта выхода + 11 путей решения по панели + 3 пути доставки в панель + 13 путей антиповтора + 5 путей кулдауна пинка + 6 путей признака смены + 11 путей выхода из ротации + 3 пути признака живой фоновой задачи + 4 пути метки конца хода + 2 пути доставки длинного текста владельцу целиком + 3 пути кулдауна разговора о блокировке + 4 пути замера окна + 8 путей выбора способа ротации + 7 путей двери ротации (передача дел и лимит) + 10 путей признака лимита подписки + 3 пути кнопки ревизии + 3 пути паузы владельца + 4 пути решения «будить ли смену» + 13 путей решения лимитной ветки + 12 путей времени сброса и пинка по нему + 16 путей «работы нет, смена у приглашения» + 3 пути текста вести о ждущей ротации, в каждой группе первым — больной случай)"; exit 0; }
    exit 1
fi

# ── конфиги: два, оба обязательны, отказ внятный ────────────────────────────
# shellcheck disable=SC1091
source "$HARNESS_SCRIPTS/lib/config.sh"
INSTALL_CONF="${HARNESS_INSTALL_CONF:-${INSTALL_CONF:-$(konf_koren)/install.conf}}"
HARNESS_CONF="${HARNESS_CONF:-$(konf_koren)/harness.conf}"
[ -r "$INSTALL_CONF" ] || { echo "session-warden: нет $INSTALL_CONF — установка не завершена (01-SPEC §0), работать не с чем"; exit 1; }
[ -r "$HARNESS_CONF" ] || { echo "session-warden: нет $HARNESS_CONF — скопируйте harness/config/harness.conf в $(konf_koren)/ (01-SPEC этап 3)"; exit 1; }
# Окружение старше конфига: общий загрузчик вместо голого source (улика
# 12.09.2026 — проба с TMUX_SESSION в окружении сменила модель в РАБОЧЕЙ панели).
konf_zagruzit

# Выбор модели — общей функцией из scripts/lib/models.sh: четыре копии одной
# функции разъезжаются при первой же правке (находка ревью кода 12.09.2026).
# shellcheck disable=SC1091
[ -r "$PROJECT_DIR/scripts/lib/models.sh" ] && source "$PROJECT_DIR/scripts/lib/models.sh"
# Работа по подменённому конфигу — законна (смоук ротации), но обязана быть
# видна: тот же прогон с чужими порогами выглядит в журнале как штатный.
[ "$HARNESS_CONF" = "$(konf_koren)/harness.conf" ] || \
    say "ВНИМАНИЕ: конфиг ПОДМЕНЁН — $HARNESS_CONF (боевой: $(konf_koren)/harness.conf)"
: "${AGENT_USER:?в install.conf пуст AGENT_USER}" "${PROJECT_DIR:?в install.conf пуст PROJECT_DIR}"
: "${LOG_DIR:?пуст LOG_DIR}" "${HEARTBEAT_DIR:?пуст HEARTBEAT_DIR}"
# Пороги с дефолтами: конфиг мог быть скопирован до появления этих ключей.
AGENT_START_CMD="${AGENT_START_CMD:-claude --dangerously-skip-permissions}"
AGENT_START_TIMEOUT_SEC="${AGENT_START_TIMEOUT_SEC:-120}"
SERVICE_LOCKS_SUBDIR="${SERVICE_LOCKS_SUBDIR:-services}"
# Пороги присмотра за панелью — ЗДЕСЬ, после загрузки конфига. Стояли выше,
# и общий загрузчик (окружение старше файла) возвращал их ПОСЛЕ source: четыре
# ключа harness.conf стали мёртвыми данными, правка порога владельцем не
# действовала и молчала (ревью кода 12.09.2026, F1-gen-01).
AGENT_DEAD_MIN="${AGENT_DEAD_MIN:-15}"
AGENT_DEAD_RESPECT_ATTACHED="${AGENT_DEAD_RESPECT_ATTACHED:-1}"
AGENT_DEAD_COOLDOWN_MIN="${AGENT_DEAD_COOLDOWN_MIN:-120}"
AGENT_ATTACHED_IDLE_MIN="${AGENT_ATTACHED_IDLE_MIN:-10}"



# П-2 (ревью №2): делитель замера окна; ноль, пустота или не-число валили
# прогон делением на ноль без диагноза. Гейт до всякой работы: внятный красный,
# rc=1, метка heartbeat НЕ ставится.
if ! [[ "${CTX_WINDOW_TOKENS:-}" =~ ^[0-9]+$ ]] || [ "$CTX_WINDOW_TOKENS" -eq 0 ]; then
    say "CTX_WINDOW_TOKENS не задан или 0 — почини harness.conf (сейчас: '${CTX_WINDOW_TOKENS:-пусто}')"
    exit 1
fi

ROTATION_LOG="$LOG_DIR/rotation.jsonl"
mkdir -p "$LOG_DIR" "$HEARTBEAT_DIR"

# Флаг «ротация ждёт / идёт» лежит там же, где пауза владельца и очередь хука
# (PANEL_STATE_DIR, дверь стенда — HARNESS_PANEL_STATE): туда пишет и агент, и
# панель, а /var/lib/harness агенту закрыт. Хук очереди читает его через
# scripts/lib/rotation_flag.py и по нему кладёт новые запуски помощников в очередь.
ROTATION_STATE_DIR="${HARNESS_PANEL_STATE:-$(python3 -c 'import sys; sys.path.insert(0, sys.argv[1]); import config; print(config.panel_state_dir())' "$HARNESS_SCRIPTS/lib" 2>/dev/null || true)}"
ROTATION_FLAG="$ROTATION_STATE_DIR/rotation-waits-helpers.json"

rotation_flag_read() {  # $1 = поле флага → значение (пусто — флага или поля нет)
    jq -r --arg k "$1" '.[$k] // empty' "$ROTATION_FLAG" 2>/dev/null || true
}

# Записать флаг: одна точка записи — CLI scripts/lib/rotation_flag.py (перенос
# полей «с»/«причина»/«принуждена»/«сказано» и атомарная запись — там).
rotation_flag_put() {  # $1=этап $2=помощников $3=ждали_сек [$4=принуждена] [$5=сказано epoch]
    local args=(--set --stage "$1" --helpers "$2" --waited "$3")
    [ -z "${4:-}" ] || args+=(--forced "$4")
    [ -z "${5:-}" ] || args+=(--told "$5")
    args+=(--session "${SHIFT_SESSION_ID:-${SESSION_ID:-}}" --reason "${REASON:-}")
    local err
    err=$(HARNESS_PANEL_STATE="$ROTATION_STATE_DIR" python3 "$HARNESS_SCRIPTS/lib/rotation_flag.py" "${args[@]}" 2>&1 >/dev/null) \
        || say "флаг ротации записать не вышло: $ROTATION_FLAG: $(printf %s "$err" | tail -n 1)"
}

# Снимает флаг и метку «принято на ожидании» (диспетчер ставит её, когда
# владельцу сказано «принял в очередь»). Зовётся на каждом пути, где смена
# сменилась или ротация отказана: флаг, о котором забыли, молча запирал бы
# запуски помощников до своего протухания.
rotation_flag_clear() {  # $1 = повод
    [ -e "$ROTATION_FLAG" ] || return 0
    local err
    err=$(HARNESS_PANEL_STATE="$ROTATION_STATE_DIR" python3 "$HARNESS_SCRIPTS/lib/rotation_flag.py" --clear 2>&1 >/dev/null) \
        || say "флаг ротации снять не вышло: $ROTATION_FLAG: $(printf %s "$err" | tail -n 1)"
    jlog "rotation_flag_cleared" "${SESSION_ID:-?}" "$1: $ROTATION_FLAG"
}

# Метка «меня запустили» — ответ на вопрос «cron бежит?», отдельный от метки
# успеха в конце файла. Улика 04–10.09.2026: ротация держит лок до 24 минут,
# все плановые прогоны это время выходят «лок занят» без метки, и sentinel
# 59 раз объявлял живой cron стоящим (ни в одном из 59 случаев cron не был
# неактивен) — с письмом владельцу «демоны присмотра стояли». Один признак
# отвечал на два вопроса и не различал их.
# Метку ставит ТОЛЬКО плановый прогон — тот, что зовёт cron, то есть без
# аргументов. Ручные вызовы (`--rotate-now` агента, `--kick`, `--досмотр-выхода`,
# самотест) и спасательный прогон sentinel её не трогают: иначе они гасят чужую
# тревогу — при вставшем cron уходящий агент своей же ротацией «доказывал» бы,
# что cron жив, и настоящая остановка присмотра осталась бы невидимой
# (ревью 10.09.2026, ops-15).
if [ "${SENTINEL_RESCUE:-0}" != 1 ] && [ -z "${1:-}" ]; then
    touch "$HEARTBEAT_DIR/session-warden.запуск"
fi

# ── `--rotate-now`: законный способ агента уйти со сменой ───────────────────
# Улика 11.08.2026, 22:51: окно доросло до 139%, сторож молчал (был подавлен
# антиповтором), и агент завершил себя сам командой в свою панель. Выход у
# него получился, смена — нет: поднимать преемника умеет только сторож.
# Теперь у агента есть вызов, который делает ОБА действия, — и уходить иначе
# незачем (голый выход отменяет сторож команд guard_bash).
#
# Отвязка обязательна: команду запускает уходящий агент, и его выход убил бы
# процесс, которому осталось поднять преемника, — та же потеря смены.
#
# Помощники живут внутри процесса claude: выход оборвал бы их. Поэтому ворота
# спрашиваются ДО отвязки — после неё уходящий агент ответа уже не увидит, а
# отложенную смену никто бы не объяснил. Слово владельца (`--owner`) ворот не
# спрашивает: потерять работу помощников — его решение.
ROTATE_OWNER_OVERRIDE=0
rotate_now_gate() {  # 0 — отвязывать можно; 1 — смена отложена, агенту сказано
    local out="" rc=0 running=0 hung=0 sid="" verdict who
    [ "$ROTATE_OWNER_OVERRIDE" != 1 ] || return 0
    out=$(python3 "$HARNESS_SCRIPTS/stall-in-log.py" --работа --shift 2>/dev/null) || rc=$?
    # Код 1 — транскрипта смены нет: судить нечем, отвязка идёт как раньше.
    [ "$rc" != 1 ] || return 0
    JUDGE_OUT="$out"
    if [ "$rc" = 0 ]; then
        running=$(judge_field помощников); hung=$(judge_field зависших)
        sid=$(basename "$(judge_field транскрипт)" .jsonl)
    else
        running="?"    # отказ судьи: незнание не разрешение
    fi
    verdict=$(rotation_helpers_verdict "$running" "$hung" 0 "${ROTATE_HELPERS_WAIT_MAX_MIN:-60}" "${ROTATE_HELPERS_TIMEOUT_ACTION:-}") && return 0
    SESSION_ID="$sid" REASON="ротацию запросил агент (--rotate-now)" rotation_flag_put ждёт "$running" 0 1
    who="идут $running помощников ($(judge_helpers_text весть))"
    [ "$running" != 0 ] || who="зависли помощники ($(judge_hung_text))"
    echo "смена отложена: $who, сменю сам, как закончат; новых помощников не запускай, коммить сам."
    return 1
}
FORCE_ROTATE=0
if [ "${1:-}" = "--rotate-now" ]; then
    FORCE_ROTATE=1
    [ "${2:-}" != "--owner" ] || ROTATE_OWNER_OVERRIDE=1
    if [ "${WARDEN_DETACHED:-0}" != 1 ]; then
        rotate_now_gate || exit 1
        WARDEN_DETACHED=1 setsid nohup "$0" "$@" \
            >> "$LOG_DIR/session-warden.log" 2>&1 < /dev/null &
        echo "ротация запущена отдельным процессом: завершение сессии + подъём преемника."
        echo "След — $LOG_DIR/session-warden.log и $ROTATION_LOG."
        exit 0
    fi
fi

# ── лок на весь прогон (Б-4е): ротация ждёт завершения до 15 минут, а cron
# стартует каждые 10 — без лока второй прогон продублирует команды в tmux.
# Каталог сервисных локов: ворота deploy_guard смотрят только $LOG_DIR/locks/.
SERVICE_LOCK_DIR="$LOG_DIR/locks/$SERVICE_LOCKS_SUBDIR"
mkdir -p "$SERVICE_LOCK_DIR"
exec 8>> "$SERVICE_LOCK_DIR/session-warden.lock"
# Досмотр позднего выхода живёт до получаса и лока НЕ берёт: он почти всё это
# время только смотрит, а держать лок значило бы остановить плановые прогоны
# на три цикла cron. Действует он одним вызовом start_agent, а тот идемпотентен
# («в панели уже claude — агент запущен без меня»).
LATE_WATCH=0
[ "${1:-}" = "--досмотр-выхода" ] && LATE_WATCH=1
# Плановый прогон уступает дорогу молча — через 10 минут придёт следующий.
# Запрошенная агентом ротация ЖДЁТ: уступить значило бы отказать молча, а
# агент уже считает, что уходит со сменой. Сам отказ разбирается ниже, когда
# определена доставка в канал, — молчаливым он не остаётся ни в одном случае.
LOCK_TAKEN=1
if [ "$LATE_WATCH" = 1 ]; then
    exec 8>&-
elif [ "$FORCE_ROTATE" = 1 ]; then
    flock -w "${ROTATE_LOCK_WAIT_SEC:-900}" 8 || LOCK_TAKEN=0
elif ! flock -n 8; then
    # Уступить дорогу СВОЕМУ прогону — норма. Но 12.08.2026 лок держал чужой
    # процесс (tmux-сервер, унаследовавший дескриптор), и сторож молча выходил
    # девять прогонов подряд: 40 минут мёртвого сторожа заметил человек, а не
    # харнес. Молчание в логе — не сигнал. Поэтому здесь проверяется, КТО
    # держит: свой — молчим, чужой — чиним и говорим владельцу.
    # fuser отдаёт ВСЕ pid одной строкой через пробелы; склеить их в одно
    # число — получить несуществующий процесс, пустое имя и молчаливый выход
    # по ветке «свой прогон». Поймано пробой 12.08.2026 (`flock` + `sleep`
    # дали два pid). Берём первый: любого из держателей довольно, чтобы
    # понять, наш он или чужой.
    # «|| true» обязателен: под `set -euo pipefail` пустой grep роняет ВЕСЬ
    # скрипт кодом 1, и ни одна строка ниже не печатается — сторож мёртв и
    # молчит. Пустой ответ fuser законен: держателя чужого пользователя он без
    # root не покажет ([[a-setting-ignored-in-silence]] — молчание не сигнал).
    HOLDER=$(fuser "$SERVICE_LOCK_DIR/session-warden.lock" 2>/dev/null | tr -s ' ' '\n' | grep -m1 '[0-9]' || true)
    HOLDER_CMD=$([ -n "$HOLDER" ] && ps -o comm= -p "$HOLDER" 2>/dev/null || echo "")
    # Пустой держатель — не «свой прогон», а «не разобрал». Разводим: свой
    # выход обычен, неразобранный говорит о себе в лог, иначе разница между
    # здоровой уступкой дороги и мёртвым сторожем видна только человеку.
    if [ -z "$HOLDER" ]; then
        say "лок session-warden занят, а держателя не видно (fuser молчит — обычно чужой пользователь) — выхожу без действий"
        exit 0
    fi
    case "$HOLDER_CMD" in
        ""|*bash*|*session-warden*)
            say "другой прогон session-warden ещё работает (лок занят, держит $HOLDER) — выхожу без действий"
            exit 0 ;;
    esac
    # Чужой держатель лока не отпустит его никогда — он не знает, что держит.
    # Лок пересоздаётся: flock живёт на inode, поэтому новый файл свободен, а
    # старый остаётся у держателя и никому не мешает.
    say "лок session-warden держит ЧУЖОЙ процесс $HOLDER ($HOLDER_CMD) — сторож был бы мёртв навсегда; пересоздаю лок"
    mv -f "$SERVICE_LOCK_DIR/session-warden.lock" \
          "$SERVICE_LOCK_DIR/session-warden.lock.занят-$HOLDER_CMD-$HOLDER" 2>/dev/null || true
    exec 8>> "$SERVICE_LOCK_DIR/session-warden.lock"
    flock -n 8 || { say "новый лок тоже занят — выхожу"; exit 1; }
    LOCK_RECREATED="$HOLDER ($HOLDER_CMD)"
fi

# Запись события в журнал ротаций. jq собирает JSON сам — ручная склейка
# строк ломается на первой же кавычке в тексте.
jlog() {  # событие, сессия, детали
    jq -cn --arg ts "$(date -Is)" --arg ev "$1" --arg s "$2" --arg d "$3" \
        '{ts:$ts, event:$ev, session:$s, detail:$d}' >> "$ROTATION_LOG"
}

# Отправка владельцу. Успех ТОЛЬКО при ok:true (норма 01-SPEC §7) — лог
# «отправлено» без разбора ответа успехом не считается.
# Исход при лимите выбирается КЛЮЧОМ в месте вызова (владелец 17.10.2026):
# «--несмотря-на-лимит» — о смене сессии и о том, где нужны его руки;
# «--не-досылать» — весть, которая после обновления смысла не имеет; без ключа
# весть ложится в очередь досыла и уедет после обновления. Ключи идут ВТОРЫМ и
# далее доводами: tg_send "текст" --не-досылать.
tg_send() {
    local text="$1" rc=0; shift || true
    # Звонящий, которому «ушло» и «придержано» не одно и то же, читает флаг: код 0
    # остаётся для всех прежних вызовов, у которых после `||` стоит жалоба на сбой.
    TG_SEND_HELD=0
    if [ -x "$PROJECT_DIR/scripts/tg_send.sh" ]; then
        # Код берётся у САМОЙ двери: `rc=$?` после `if … fi` читает код
        # СОСТАВНОГО оператора, а `if` без `else` на ложном условии даёт 0.
        "$PROJECT_DIR/scripts/tg_send.sh" "$@" "$text" || rc=$?
        [ "$rc" = 0 ] && return 0
        # Код 3 — дверь придержала весть БЕЗ досыла (так позвали). Это
        # исполнение правила, а не сбой доставки: ни прямого curl, ни тревоги,
        # иначе обход двери сделал бы правило пустым.
        [ "$rc" = 3 ] && { TG_SEND_HELD=1; say "придержано дверью канала: держится лимит подписки"; return 0; }
        # Прочий отказ (потолок длины сторожа канала) — не повод обойти дверь:
        # весть уходит вложением через ту же дверь. Прямой путь ниже — только
        # когда двери нет вовсе.
        local doc="$LOG_DIR/весть-сторожа-$(date +%F-%H%M%S).md"
        printf '%s\n' "$text" > "$doc"
        say "текстом не прошло — шлю вложением $doc"
        "$PROJECT_DIR/scripts/tg_send.sh" "$@" --file "$doc" \
            --caption "Сторож сессий: весть во вложении" && return 0
        say "tg_send.sh отказал — сообщение не доставлено"
        return 1
    fi
    if [ -z "${TG_CHAT_ID:-}" ] || [ ! -s "${TG_TOKEN_FILE:-/nonexistent}" ]; then
        say "КАНАЛ НЕ НАСТРОЕН: TG_CHAT_ID/TG_TOKEN_FILE пусты — сообщение владельцу НЕ ушло"
        return 1
    fi
    # URL с токеном — через stdin (curl -K -), а не в argv: argv виден любому
    # в ps. Образец — scripts/tg_send.sh; здесь была копия с токеном наружу.
    local token; token=$(cat "$TG_TOKEN_FILE")
    printf 'url = "https://api.telegram.org/bot%s/sendMessage"\n' "$token" \
        | curl -s -m 20 -K - -X POST \
        --data-urlencode "chat_id=$TG_CHAT_ID" --data-urlencode "text=$text" \
        | jq -e '.ok == true' >/dev/null
}

# Зелёное («агент на месте») гасит задачу модели. Писателя может не быть
# (раскладка неполна) — сторож от этого не падает.
alert_task() {  # $@ = доводы писателя: --resolve <ключ>
    [ -f "$PROJECT_DIR/scripts/alert-task.py" ] || return 0
    python3 "$PROJECT_DIR/scripts/alert-task.py" "$@" </dev/null >/dev/null 2>&1 || true
}

# Пересозданный лок — не мелочь механики: до этой минуты сторож не работал, а
# значит не работала и ротация. Владелец узнаёт об этом сразу, а не когда
# сессия дорастёт до автокомпакта.
if [ -n "${LOCK_RECREATED:-}" ]; then
    jlog "lock_recreated" "?" "лок держал чужой процесс $LOCK_RECREATED"
    tg_send "Сторож сессий был заблокирован: лок держал чужой процесс $LOCK_RECREATED (обычно tmux-сервер, унаследовавший дескриптор). Лок пересоздан, сторож снова работает. Ротация всё это время не срабатывала." || true
fi

# Смену уже ведёт другой прогон? Тогда он ждёт РОВНО моего выхода, и вставать
# к нему в очередь за локом — взаимная блокировка: он ждёт агента, агент ждёт
# лок (улика 12.08.2026: сторож заказал ротацию, агент ушёл через --rotate-now,
# оба замерли, владелец написал «ничего не происходит»). Признак берём из
# журнала, а не из «бежит ли процесс»: обычный прогон сторожа тоже виден в
# ps, но преемника он не поднимет — выйти по нему значило бы уйти без смены.
ротация_в_ходу() { # 0 = ротацию ведёт другой прогон и ждёт моего выхода
    rotation_in_progress
}

# Сессия агента обязана пережить выход агента: пока она умирала вместе с ним,
# ротация выбрасывала из tmux приаттаченного владельца (улика 13.08.2026).
# Новые сессии поднимаются с оболочкой и переживают выход сами; эта опция
# закрывает и те, что уже подняты старым способом — включая живую сейчас.
беречь_сессию() {
    tmux has-session -t "$TMUX_SESSION" 2>/dev/null || return 0
    tmux set-option -t "$TMUX_SESSION" remain-on-exit on 2>/dev/null || true
}

# Сколько секунд панель ничего не выводила. Пока агент работает, TUI
# перерисовывается непрерывно; замолчал — значит ход закончен и ждёт ввода.
# `#{pane_activity}` в tmux 3.4 пуст. `#{session_activity}` тоже НЕ живое: оно
# обновляется при переключении окон, а не при выводе. Замер 11.09.2026 на
# работающем агенте: session_activity дало простой 772 мин, window_activity — 0.
# Ценой этой ошибки было правило «ход закончен И панель молчит»: второе условие
# всегда истинно, и «/exit» подавался по одному признаку — ровно тот обрыв хода
# посреди работы, против которого правило и вводилось 13.08.2026.
простой_панели() {
    local last sec
    last=$(tmux display-message -p -t "$TMUX_SESSION" '#{window_activity}' 2>/dev/null || echo 0)
    [ -n "$last" ] || last=0
    sec=$(( $(date +%s) - last ))
    [ "$sec" -lt 0 ] && sec=0
    printf '%s' "$sec"
}

# Кто пишет прямо сейчас: id свежайшего транскрипта проекта ("" — каталог ещё
# не найден или пуст). Каталог ищет основной поток (PROJECT_TRANSCRIPTS), эта
# функция зовётся уже после него — из ожидания смены.
свежий_id() {
    [ -n "${PROJECT_TRANSCRIPTS:-}" ] || return 0
    local f
    f=$(find "$PROJECT_TRANSCRIPTS" -mindepth 1 -maxdepth 1 -name '*.jsonl' -type f -printf '%T@ %p\n' 2>/dev/null \
        | sort -nr | head -1 | cut -d' ' -f2- || true)
    [ -n "$f" ] && basename "$f" .jsonl
}

# Текст агенту в tmux — ТОЛЬКО при живом claude/node в панели (Б-4б):
# в голой оболочке «Продолжай текущую задачу» исполнился бы как команды bash.
# Оба входа идут под общим локом двери. agent_prompt — служебный толчок (пауза
# владельца его держит), agent_rotation_prompt — «/exit» смены сессии: ротация
# паузой не гасится, иначе начатый выход застрял бы на полдороге.
agent_prompt() {  # текст
    local cmd; cmd=$(pane_cmd)
    case "$cmd" in
        claude|node) pane_kick_service "$1"; return $? ;;
    esac
    say "в панели '$cmd', не claude/node — текст агенту НЕ шлю (оболочка исполнила бы его как команды)"
    return 1
}

agent_rotation_prompt() {  # текст
    local cmd; cmd=$(pane_cmd)
    # «/exit» и «/clear» обрывают помощников процесса. Через эту функцию идут
    # ВСЕ такие команды сторожа — ворота стоят здесь, а не в каждом вызывающем.
    case "$1" in
        /exit|/clear)
            if ! rotation_helpers_gate; then
                PANE_REFUSAL="помощники"
                say "«$1» в панель НЕ подан: ${ROTATION_GATE_WORD:-идут помощники}"
                jlog "rotate_exit_held" "${SESSION_ID:-?}" "«$1» не подан: ${ROTATION_GATE_WORD:-идут помощники}"
                return 1
            fi ;;
    esac
    case "$cmd" in
        claude|node) pane_command text "$1"; return $? ;;
    esac
    say "в панели '$cmd', не claude/node — текст агенту НЕ шлю (оболочка исполнила бы его как команды)"
    return 1
}

# Ворота помощников: 0 — менять сессию можно, 1 — помощники держат. Слово —
# в ROTATION_GATE_WORD. Замер старше 20 с делается заново: ворота зовут и через
# минуты ожидания регламента, когда число помощников давно другое.
rotation_helpers_gate() {
    local now rc=0 waited_min
    now=$(date +%s)
    ROTATION_GATE_WORD=""
    if [ "$ROTATE_OWNER_OVERRIDE" = 1 ]; then ROTATION_GATE_WORD="можно: слово владельца"; return 0; fi
    [ $(( now - ${JUDGE_AT:-0} )) -le 20 ] || judge_work
    waited_min=$(( (${ROTATION_WAITED_SEC:-0} + now - ${ROTATION_WAITED_AT:-$now}) / 60 ))
    ROTATION_GATE_WORD=$(rotation_helpers_verdict "$JUDGE_HELPERS" "${JUDGE_HUNG:-0}" "$waited_min" \
        "${ROTATE_HELPERS_WAIT_MAX_MIN:-60}" "${ROTATE_HELPERS_TIMEOUT_ACTION:-}") || rc=$?
    return "$rc"
}

# ── Перезагрузка сервера вместо «/exit» тяжёлого пути ───────────────────────
# Предикат «нужна ли»: печатает «<нужна 1|0|?> <ожидаемое ядро>».
reboot_needed() {
    local out rc=0
    out=$(python3 "$HARNESS_SCRIPTS/stack_freshness.py" --перезагрузка 2>/dev/null) || rc=$?
    case "$rc" in
        0) printf '1 %s\n' "${out#нужна: }" ;;
        1) printf '0 -\n' ;;
        *) printf '? -\n' ;;
    esac
}

# Прошлая перезагрузка не сменила ядро (или её команда упала), а предикат ждёт то
# же самое: 1 — стоп. У «не состоялась» ядро_сменилось = null, провал виден по команда_код.
# Новое ядро в /boot меняет «ожидаемое» и снимает запрет само.
reboot_last_failed() {  # $1=ожидаемое ядро
    jq -r --arg e "$1" 'if ((.["ядро_сменилось"] == false or (.["итог"] == "не состоялась" and ((.["команда_код"] // 0) != 0))) and .["ядро_ожидаемое"] == $e) then 1 else 0 end' \
        "$ROTATION_STATE_DIR/reboot-last.json" 2>/dev/null || printf '0\n'
}

# 7-й довод способ_ротации: встала бы перезагрузка. Помощников и ход точка в
# rotate_full спросит сама, здесь они «нет, как у решения о ротации».
reboot_would_fit() {
    local paused=0 pause_rc=0 busy=0 busy_out busy_rc=0 need expected hours
    [ "${AUTO_REBOOT_IN_ROTATION:-0}" = 1 ] || { printf '0\n'; return 0; }
    # Без команды перезагрузки не будет: тяжёлый путь ради неё ротации не нужен.
    [ -n "${REBOOT_CMD:-}" ] || { printf '0\n'; return 0; }
    работа_на_паузе || pause_rc=$?
    case "$pause_rc" in 0) paused=1 ;; 1) paused=0 ;; *) paused="?" ;; esac
    busy_out=$(python3 "$HARNESS_SCRIPTS/boot_check.py" --занято 2>/dev/null) || busy_rc=$?
    case "$busy_rc" in 0) busy=0 ;; 1) busy="${busy_out#занята: }" ;; *) busy="?" ;; esac
    read -r need expected < <(reboot_needed)
    hours=$(awk '{print int($1 / 3600)}' /proc/uptime)
    reboot_window_verdict 1 "${STACK_NEIGHBOURS:-}" "$paused" выход 0 0 "$busy" "$need" "$hours" \
        "${REBOOT_MIN_GAP_HOURS:-24}" "$(reboot_last_failed "$expected")" >/dev/null && printf '1\n' || printf '0\n'
}

# Действие: весть владельцу → след и метка → последний взгляд → команда.
# Каждый шаг — условие следующего. Возврат 0 — команда принята, 1 — перезагрузки
# нет (обычный «/exit»), 2 — команда не задана или упала. Команда только из
# $REBOOT_CMD, умолчания в коде нет: у agent полный sudo, ошибка = настоящая
# перезагрузка машины.
reboot_for_rotation() {  # $1=ожидаемое ядро $2=причина ротации
    local expected="$1" reason="$2" dir="${ROTATION_STATE_DIR:-${PANEL_STATE_DIR:-}}"
    local mark="$dir/reboot-started.json" tmp="$dir/reboot-started.json.$$"
    local before text sent_rc=0 cmd_rc=0 why="" flag flag_session flag_stage busy_out busy_rc=0 pause_rc=0
    # Смена — не обязательно самый свежий транскрипт: флаг и задачи у неё свои.
    local shift_id="${SHIFT_SESSION_ID:-${SESSION_ID:-}}"
    if [ -z "${REBOOT_CMD:-}" ]; then
        jlog "reboot_failed" "$SESSION_ID" "команда не задана"
        return 2
    fi
    # «20 минут» в вести = срок метки + период таймера sentinel (5).
    text="Перезагружаю сервер при смене сессии: ставлю обновление системы. Займёт около ${REBOOT_EXPECT_MIN:-3} минут. Задену: ${STACK_NEIGHBOURS:-}. Сам поднимется агент, канал и панель; после подъёма пришлю проверку. Если через $(( ${REBOOT_LATE_MIN:-15} + 5 )) минут от меня нет вести — сервер не поднялся, нужна консоль хостера."
    # Разрешает только ДОСТАВЛЕННАЯ весть: «не-досылать» превращает придержку
    # двери в код 3, а не в очередь досыла с кодом 0.
    tg_send "$text" --несмотря-на-лимит --не-досылать || sent_rc=$?
    if [ "$sent_rc" != 0 ] || [ "${TG_SEND_HELD:-0}" != 0 ]; then
        say "перезагрузка отложена: весть владельцу не доставлена"
        jlog "reboot_skipped" "$SESSION_ID" "весть владельцу не доставлена (код $sent_rc, придержана=${TG_SEND_HELD:-0})"
        return 1
    fi
    before=$(uname -r)
    jlog "reboot_started" "$SESSION_ID" "$reason; ядро $before → $expected"
    if ! { [ -n "$dir" ] && jq -cn --argjson at "$(date +%s)" --arg s "$SESSION_ID" --arg r "$reason" \
            --arg was "$before" --arg want "$expected" \
            '{"с": $at, "сессия": $s, "причина": $r, "ядро_было": $was, "ядро_ожидаемое": $want}' > "$tmp" \
            && mv -f "$tmp" "$mark"; } 2>/dev/null; then
        rm -f "$tmp" 2>/dev/null || true
        jlog "reboot_skipped" "$SESSION_ID" "метку записать не вышло: $mark"
        return 1
    fi
    # Последний взгляд: за время вести владелец мог ответить, встать пауза,
    # запуститься помощник или фоновая задача, а машина — занять работу.
    flag=$(python3 "$HARNESS_SCRIPTS/lib/rotation_flag.py" --state 2>/dev/null || true)
    flag_session=$(jq -r '.["сессия"] // empty' <<< "$flag" 2>/dev/null || true)
    flag_stage=$(jq -r '.["этап"] // empty' <<< "$flag" 2>/dev/null || true)
    работа_на_паузе || pause_rc=$?
    if [ "$flag_session" != "$shift_id" ] || [ "$flag_stage" != идёт ]; then why="флаг ротации не «идёт» у этой смены"
    elif [ "$pause_rc" = 0 ]; then why="пауза владельца"
    elif [ "$pause_rc" != 1 ]; then why="пауза неизвестна (сбой pause.py)"
    elif ! rotation_helpers_gate; then why="помощники"
    elif фоновые_задачи_живы "$shift_id"; then why="фоновая задача сессии"
    elif [ "$(простой_панели)" -lt "${ROTATE_IDLE_SEC:-120}" ]; then why="панель ожила"
    else
        busy_out=$(python3 "$HARNESS_SCRIPTS/boot_check.py" --занято 2>&1) || busy_rc=$?
        [ "$busy_rc" = 0 ] || why="машина занята или неизвестно: $busy_out"
    fi
    if [ -n "$why" ]; then
        say "перезагрузка отменена в последний миг: $why"
        jlog "reboot_skipped" "$SESSION_ID" "последний взгляд: $why"
        return 1
    fi
    bash -c "$REBOOT_CMD" || cmd_rc=$?
    if [ "$cmd_rc" != 0 ]; then
        # Метку не трогаем: код ≠ 0 бывает и тогда, когда останов уже начался.
        # Дописываем код через временный файл, правду скажет время загрузки.
        jq -c --argjson c "$cmd_rc" '. + {"команда_код": $c}' "$mark" > "$tmp" 2>/dev/null && mv -f "$tmp" "$mark" || rm -f "$tmp"
        jlog "reboot_failed" "$SESSION_ID" "команда вернула код $cmd_rc"
        return 2
    fi
    return 0
}

# Одно письмо владельцу простыми словами по ROTATE_HELPERS_TIMEOUT_ACTION=сообщить.
# Повтор не чаще ROTATE_REFUSED_TELL_GAP_MIN: метка «сказано» живёт во флаге.
rotation_tell_owner() {
    local now told text
    now=$(date +%s)
    told=$(rotation_flag_read сказано)
    if [ -n "$told" ] && [ $(( now - told )) -lt $(( ${ROTATE_REFUSED_TELL_GAP_MIN:-180} * 60 )) ]; then
        return 0
    fi
    if helpers_present; then
        text="Смена ждёт ротацию уже $(( (${ROTATION_WAITED_SEC:-0} + now - ${ROTATION_WAITED_AT:-$now}) / 60 )) мин: идут помощники ($JUDGE_HELPERS) — $(judge_helpers_text весть); жду дальше. Если ждать незачем, напишите «ротируй сейчас» — их работа пропадёт."
    else
        text="Помощник $(judge_hung_text) — похоже, завис; ротация его ждёт. Решите: «ротируй сейчас» оборвёт его, иначе я жду дальше."
    fi
    if tg_send "$text" --не-досылать; then
        rotation_flag_put "$(rotation_flag_read этап)" "$JUDGE_HELPERS" "$ROTATION_WAITED_SEC" "$FORCE_ROTATE" "$now"
    else
        say "письмо владельцу о ждущей ротации не ушло — повторю на следующем прогоне"
    fi
}

# Всё, что делает прогон, когда помощники держат нужную ротацию: флаг, событие
# (только при постановке и при смене числа — не на каждом прогоне), одна весть
# смене и, если вышел срок, одно письмо владельцу.
rotation_hold_effects() {
    local existed=0 prev
    [ ! -e "$ROTATION_FLAG" ] || existed=1
    prev=$(rotation_flag_read помощников)
    say "ротация ТРЕБУЕТСЯ ($REASON), но ждёт помощников — ${ROTATION_GATE_WORD:-?}"
    rotation_flag_put ждёт "$JUDGE_HELPERS" "$ROTATION_WAITED_SEC" "$FORCE_ROTATE"
    if [ "$existed" = 0 ] || [ "$prev" != "$JUDGE_HELPERS" ]; then
        jlog "rotate_waits_helpers" "$SESSION_ID" "$REASON; помощников: $JUDGE_HELPERS; $(judge_helpers_text весть)"
    fi
    if [ "$existed" = 0 ]; then
        agent_prompt "$(rotation_hold_text "$JUDGE_HELPERS")" \
            || say "весть смене о ждущей ротации не дошла"
    fi
    [ "${ROTATION_GATE_WORD%%:*}" != "сообщить" ] || rotation_tell_owner
}

# Строки очереди, отложенной хуком, → номера (через пробел) и фраза для пинка.
rotation_queue_numbers() {  # $1 = вывод `rotation_queue_guard.py --release`
    printf '%s\n' "$1" | sed -n 's/^\([0-9][0-9]*\)\. .*/\1/p' | tr '\n' ' '
}
rotation_queue_note() {  # $1 = вывод `rotation_queue_guard.py --release`
    printf '%s\n' "$1" | awk '
        /^[0-9]+\. / { n++; list = list (list == "" ? "" : "; ") $0 }
        /^Полные поручения/ { file = $0; sub(/^[^:]*: /, "", file) }
        END { if (n) printf " Отложено ротацией %d запусков помощников — запусти их заново по очереди: %s; полные поручения — в %s.", n, list, file }'
}

# Страховка выпуска очереди: пинок преемнику мог уйти в кулдаун или не дойти, а
# отложенные запуски остались невыпущенными. Без флага и спустя время после
# пинка они подаются отдельным толчком и помечаются только после доставки.
rotation_queue_rescue() {
    local guard="$HARNESS_SCRIPTS/hooks/rotation_queue_guard.py" out numbers age
    [ ! -e "$ROTATION_FLAG" ] || return 0
    [ -f "$guard" ] || return 0
    age=$(возраст_пинка)
    [ -z "$age" ] || [ "$age" -ge $(( ${KICK_COOLDOWN_SEC:-120} * 5 )) ] || return 0
    out=$(python3 "$guard" --release 2>/dev/null) || return 0
    numbers=$(rotation_queue_numbers "$out")
    [ -n "$numbers" ] || return 0
    if agent_prompt "[сторож] отложено ротацией, пинок до смены этого не донёс.$(rotation_queue_note "$out") Разбери накопленное во входящих."; then
        python3 "$guard" --mark $numbers 2>/dev/null || say "отложенные запуски не помечены выпущенными — выпущу снова"
    fi
}

# После смены на машине остаются порты прежней смены (http.server из каталога
# черновиков на 0.0.0.0). Снимает их прибор внешней поверхности; сбой уборки
# ротацию не валит.
shift_leftover_sweep() {
    local tool="$HARNESS_SCRIPTS/check-external-surface.py" out
    # Обход /proc/*/fd на загруженной машине небыстр; без потолка уборка
    # задержала бы ротацию. Нет прибора — пишем причину, а не молчим.
    [ -f "$tool" ] || { jlog "shift_leftover_sweep_skipped" "?" "нет прибора $tool — уборка мусора смены пропущена"; return 0; }
    out=$(timeout 60 python3 "$tool" --убрать-мусор-смены 2>&1) || { jlog "shift_leftover_sweep_failed" "?" "уборка мусора смены не удалась: ${out:0:200}"; return 0; }
    jlog "shift_leftover_sweep" "?" "${out//$'\n'/; }"
}

if [ "${LOCK_TAKEN:-1}" = 0 ] && ротация_в_ходу; then
    say "--rotate-now: смену уже ведёт другой прогон — просто выхожу, преемника поднимет он"
    jlog "rotate_already_running" "?" "лок держит идущая ротация — агент выходит, не мешая ей"
    agent_rotation_prompt "/exit" || {
        say "команда выхода в панель НЕ ушла — сессия остаётся, смена не состоится"
        tg_send "Смену ведёт сторож, но команда выхода не дошла до панели — сессия жива. Нужно вмешаться." --несмотря-на-лимит || true
        exit 1
    }
    exit 0
fi

# Лок держит НЕ ротация, а обычный прогон сторожа — смены не будет вовсе.
# Отказ громкий: агент, попросивший смену, ответа уже не увидит — он уходит.
if [ "${LOCK_TAKEN:-1}" = 0 ]; then
    say "--rotate-now: лок занят дольше ${ROTATE_LOCK_WAIT_SEC:-900}с — ротацию не выполняю"
    jlog "rotate_lock_busy" "?" "лок session-warden занят дольше ${ROTATE_LOCK_WAIT_SEC:-900}с"
    tg_send "Агент попросил ротацию, но сторож был занят другим прогоном дольше $(( ${ROTATE_LOCK_WAIT_SEC:-900} / 60 )) мин — смена не состоялась. Сессия работает дальше." || true
    exit 1
fi

# Разбудить свежеподнятую сессию: поднять ПРОЦЕСС — не то же, что вернуть
# РАБОТУ. Улика владельца 11.08.2026: «сессия перезагрузилась, но автозапуска
# не произошло» — claude поднимался и молча ждал у пустого приглашения, потому
# что никто ему ничего не говорил. Проверка приёма после ротации идёт
# ОТДЕЛЬНЫМ headless-вызовом и живой панели не касается.
KICK_STAMP="${KICK_STAMP:-${LOG_DIR}/kick.stamp}"

# Возраст последнего пинка в секундах; пустая строка — пинка ещё не было.
возраст_пинка() {
    [ -f "$KICK_STAMP" ] || return 0
    echo $(( $(date +%s) - $(stat -c '%Y' "$KICK_STAMP") ))
}

подхватить_работу() {
    # Новая смена — прежний флаг ожидания ей не принадлежит; снимается на любом
    # пути пинка (полный перезапуск, --kick, дозор, подъём выпавшего агента).
    local had_flag=0 queue_out="" queue_numbers="" queue_note=""
    [ ! -e "$ROTATION_FLAG" ] || had_flag=1
    rotation_flag_clear "новая смена получает пинок"
    # Пинок зовут несколько рук сразу: сторож после ротации, sentinel после
    # загрузки, пусковой скрипт после подъёма юнитом. Кулдаун — чтобы свежая
    # сессия не получила три одинаковых поручения подряд и не начала работу
    # трижды. Уже пнули только что — считаем, что работа подхвачена.
    if пинок_подавлен "$(возраст_пинка)"; then
        say "пинок отдан недавно (кулдаун ${KICK_COOLDOWN_SEC:-120}с) — повтор не подаю"
        return 0
    fi
    # Пауза: TUI после запуска ещё рисуется и первые нажатия теряет.
    sleep "${AGENT_WAKE_DELAY:-5}"
    # Ждём именно агента: пусковой скрипт зовёт пинок сразу после создания
    # сессии, а claude в ней поднимается не мгновенно. Без ожидания пинок
    # уходил бы в оболочку, где agent_prompt его законно отвергает, — и
    # сессия оставалась бы у пустого приглашения при исправном коде.
    local waited=0
    while [ "$waited" -lt "${AGENT_START_TIMEOUT_SEC:-60}" ]; do
        case "$(pane_cmd)" in claude|node) break ;; esac
        sleep 5; waited=$((waited + 5))
    done
    # Порядок слов здесь — не стиль, а поведение смены. Владелец 13.09.2026:
    # «после лимита запуск должен быть мягкий, ты должен спокойно завершить
    # свою работу ты которую делал, по тем же принципам что мы делали, а не
    # хвататься за то что пишу». Прежний текст ставил входящие ПЕРЕД работой,
    # и поднятая сессия начинала с последнего сообщения вместо своего шага.
    # Срочное всё равно не потеряется: его поднимает свод входящих весами.
    #
    # Запуски помощников, отложенные хуком на время ротации, выпускаются сюда
    # списком: смена-преемник перезапускает их сама. Помечаются выпущенными
    # только после доставки пинка — не дошёл, значит остались в очереди.
    if [ -f "$HARNESS_SCRIPTS/hooks/rotation_queue_guard.py" ]; then
        queue_out=$(python3 "$HARNESS_SCRIPTS/hooks/rotation_queue_guard.py" --release 2>/dev/null) || queue_out=""
        queue_numbers=$(rotation_queue_numbers "$queue_out")
        queue_note=$(rotation_queue_note "$queue_out")
    else
        say "хука очереди нет на диске — отложенные запуски помощников не выпускаю"
    fi
    [ "$had_flag" = 0 ] && [ -z "$queue_note" ] || queue_note="$queue_note Разбери накопленное во входящих."
    if pane_command text "Ты — новая сессия после перезапуска. Прочитай STATE.md, последний docs/handover/SESSION-HANDOFF-*.md и CLAUDE.md, назови владельцу в канал текущую задачу и следующий шаг — и ПРОДОЛЖАЙ ТЕКУЩИЙ ШАГ с того места, где он оборвался. Входящие ($LOG_DIR/inbox/) разбери на ближайшем рубеже шага, не бросая его на полпути: срочное свод поднимет сам.$queue_note"; then
        date +%s > "$KICK_STAMP"
        [ -z "$queue_numbers" ] || python3 "$HARNESS_SCRIPTS/hooks/rotation_queue_guard.py" --mark $queue_numbers 2>/dev/null \
            || say "отложенные запуски не помечены выпущенными — выпущу снова"
        jlog "work_resumed" "${SESSION_ID:-?}" "новой сессии отдан пинок «подхвати работу»"
        say "новой сессии отдан пинок подхватить работу"
    else
        say "пинок «подхвати работу» НЕ отдан — сессия поднята, но стоит у пустого приглашения"
        return 1
    fi
}

# `--kick`: отдать пинок «подхвати работу» и выйти. Нужен тому, кто поднял
# агента не через сторожа — прежде всего юниту после перезагрузки сервера:
# сессия там встаёт сама, но у ПУСТОГО приглашения, и работа не начинается,
# пока владелец не напишет первым. Механика пинка живёт в одном месте — выше.
if [ "${1:-}" = "--kick" ]; then
    подхватить_работу && exit 0 || exit 1
fi

# ── `--досмотр-выхода <сессия>`: дозор после сдачи ротации ──────────────────
# Улика 12.08.2026, 23:50–00:10 (снимок владельца). «/exit» подан в 23:50:32,
# сессия не закрылась ни к 23:53, ни к 23:58 — сторож поднял тревогу и вышел.
# А между 23:58 и 00:10 выход ВСЁ-ТАКИ случился: панель, созданная командой,
# закрылась вместе с агентом. Поднять преемника стало некому — cron приходит
# раз в 10 минут, и всё это время сообщение владельца лежало в inbox, а он
# видел «сессии агента не было совсем».
#
# Продлевать досмотр в самой ротации — лечить симптом: любой срок когда-нибудь
# окажется короче. Дыра здесь не в сроке, а в том, что уходя сторож не оставлял
# за собой никого. Теперь оставляет: дозор смотрит каждые 20с и поднимает
# преемника в тот же момент, когда панель освободилась.
агента_нет() {
    tmux has-session -t "$TMUX_SESSION" 2>/dev/null || return 0
    case "$(pane_cmd)" in claude|node) return 1 ;; *) return 0 ;; esac
}

if [ "$LATE_WATCH" = 1 ]; then
    gone_session="${2:-?}"
    watch_limit="${LATE_EXIT_WATCH_SEC:-1800}"
    watched=0
    say "досмотр позднего выхода сессии $gone_session: смотрю до ${watch_limit}с, шаг 20с"
    while [ "$watched" -lt "$watch_limit" ]; do
        sleep 20; watched=$((watched + 20))
        агента_нет || continue
        say "агент ушёл на ${watched}с после сдачи ротации — поднимаю преемника"
        jlog "late_exit_caught" "$gone_session" "выход случился через ${watched}с после сдачи ротации — дозор поднимает преемника"
        if start_agent; then
            jlog "agent_restarted" "$gone_session" "агент поднят дозором позднего выхода"
            подхватить_работу || say "преемник поднят, но пинок не дошёл"
            tg_send "Отбой по тревоге о ротации: сессия закрылась с задержкой (через $((watched / 60)) мин после моей сдачи), преемник поднят дозором и работу подхватил. Вмешиваться не нужно." \
                || say "и отбой не ушёл"
            exit 0
        fi
        jlog "restart_failed" "$gone_session" "дозор позднего выхода: агент не поднялся"
        tg_send "Сессия закрылась после ротации, но преемник не поднялся: в tmux '$TMUX_SESSION' команда «$AGENT_START_CMD» не дала claude. Нужен запуск руками." \
            || say "и сигнал не ушёл"
        exit 1
    done
    say "досмотр окончен: сессия $gone_session жива и через $((watch_limit / 60)) мин — дозор снимаю, дальше владелец"
    jlog "late_exit_watch_end" "$gone_session" "за ${watch_limit}с выход так и не случился — дозор снят"
    exit 0
fi

# Каждый прогон подтверждает: сессия агента переживёт его выход. Свойство,
# которое держится только моментом создания, теряется на сессии, поднятой
# кем-то ещё (юнитом, владельцем руками) — а платит за это владелец, которого
# выбрасывает из tmux в момент ротации.
беречь_сессию
check_two_agents || true

# ── 1. Найти транскрипт текущей сессии ЭТОГО проекта ────────────────────────
# Claude Code пишет JSONL-транскрипты в ~/.claude/projects/<кодир-путь>/<uuid>.jsonl,
# где <кодир-путь> — PROJECT_DIR с заменой «/» на «-». Свежайший файл берём
# СТРОГО из каталога этого проекта (Б-4д): «свежайший вообще» подсовывал
# крошечный JSONL headless-прогона чужого каталога, и замер окна врал.
PROJECTS_DIR="${CLAUDE_PROJECTS_DIR:-/home/$AGENT_USER/.claude/projects}"
if [ ! -d "$PROJECTS_DIR" ]; then
    say "каталога транскриптов $PROJECTS_DIR нет — агент ещё не запускался, надзирать не за чем"
    touch "$HEARTBEAT_DIR/session-warden"
    exit 0
fi
PROJECT_TRANSCRIPTS=""
# Второй кандидат — на случай кодирования «все не-алфавитно-цифровые → -»
# (так кодируют свежие версии Claude Code; точки и подчёркивания тоже в дефис).
for enc in "${PROJECT_DIR//\//-}" "$(printf '%s' "$PROJECT_DIR" | sed 's/[^a-zA-Z0-9]/-/g')"; do
    if [ -d "$PROJECTS_DIR/$enc" ]; then PROJECT_TRANSCRIPTS="$PROJECTS_DIR/$enc"; break; fi
done
if [ -z "$PROJECT_TRANSCRIPTS" ]; then
    say "в $PROJECTS_DIR нет каталога проекта $PROJECT_DIR — сессий этого проекта ещё не было"
    touch "$HEARTBEAT_DIR/session-warden"
    exit 0
fi
TRANSCRIPT=$(find "$PROJECT_TRANSCRIPTS" -mindepth 1 -maxdepth 1 -name '*.jsonl' -type f -printf '%T@ %p\n' 2>/dev/null \
             | sort -nr | head -1 | cut -d' ' -f2- || true)
if [ -z "$TRANSCRIPT" ]; then
    say "транскриптов в $PROJECT_TRANSCRIPTS нет — сессий ещё не было"
    touch "$HEARTBEAT_DIR/session-warden"
    exit 0
fi
SESSION_ID=$(basename "$TRANSCRIPT" .jsonl)
# Смена — не обязательно самый свежий файл: судья работы и принадлежность флага
# ротации считаются по транскрипту СМЕНЫ; замер окна остаётся на свежайшем.
SHIFT_TRANSCRIPT=$(shift_transcript_in "$PROJECT_TRANSCRIPTS")
SHIFT_SESSION_ID=$(basename "${SHIFT_TRANSCRIPT:-$TRANSCRIPT}" .jsonl)

# ── 2. Оценить заполнение окна ──────────────────────────────────────────────
# Замер один и точный — usage последнего ответа модели (см. окно_в_токенах).
# Не удалось померить — ротации по окну нет: сессию стоимостью в контекст не
# меняют по догадке. Переполнение при этом не пропущено, его ловит второй,
# независимый триггер — счётчик компактов ниже (компакт случится сам, и его
# запишет хук PreCompact).
CTX_TOKENS=$(окно_в_токенах "$TRANSCRIPT")
if [ -n "$CTX_TOKENS" ]; then
    FILL_PCT=$(( CTX_TOKENS * 100 / CTX_WINDOW_TOKENS ))
    say "сессия $SESSION_ID: контекст $((CTX_TOKENS / 1000))k токенов = ${FILL_PCT}% окна (порог ${CTX_ROTATE_PCT}%)"
else
    FILL_PCT=-1
    say "сессия $SESSION_ID: замера в последних $(( ${CTX_TAIL_BYTES:-2000000} / 1024 )) КБ транскрипта нет (файл $(( $(stat -c '%s' "$TRANSCRIPT") / 1024 )) КБ) — окно не измерено, по нему не ротирую"
fi

# ── 3. Счёт компактов этой сессии ───────────────────────────────────────────
# События pre_compact пишет хук PreCompact в rotation.jsonl; здесь только счёт.
COMPACTS=0
if [ -f "$ROTATION_LOG" ]; then
    COMPACTS=$(grep -c "\"event\":\"pre_compact\".*\"session\":\"$SESSION_ID\"" "$ROTATION_LOG" || true)
fi
say "компактов за сессию: $COMPACTS (потолок $MAX_COMPACTS)"

# ── 4. Свежесть handover ────────────────────────────────────────────────────
# Не триггер сам по себе, но при ротации владелец должен знать, что передача
# устарела: новая сессия встанет на старый след. Вердикт — ЕДИНЫМ источником
# scripts/handover-check.sh (В-5), не собственной inline-копией проверки.
HANDOVER_NOTE=""
HANDOVER_CHECK="$PROJECT_DIR/scripts/handover-check.sh"
if [ -x "$HANDOVER_CHECK" ]; then
    HC_RC=0; HC_OUT=$("$HANDOVER_CHECK" 2>/dev/null) || HC_RC=$?
    if [ "$HC_RC" -eq 1 ]; then
        HANDOVER_NOTE="ВНИМАНИЕ: $HC_OUT"
        say "$HANDOVER_NOTE"
    else
        say "${HC_OUT:-handover-check: вердикта нет (rc=$HC_RC)}"
    fi
else
    say "scripts/handover-check.sh не найден или не исполняем — свежесть передачи не проверена"
fi

# ── 5. Решение о ротации ────────────────────────────────────────────────────
# -ge, не -gt (Б-4г): обещано «больше одного компакта подряд запрещено» —
# достигнутый потолок MAX_COMPACTS уже означает ротацию.
NEED_ROTATE=0; REASON=""
if [ "$FORCE_ROTATE" = 1 ]; then
    # Ротацию запросил сам агент (`--rotate-now`). Пороги и антиповтор — про
    # то, когда сторож решает САМ; здесь решение уже принято, и подавить его
    # значило бы вернуть агента к единственному оставшемуся способу уйти —
    # выходу без смены (улика 11.08.2026, 22:51: вышел сам, преемника нет).
    NEED_ROTATE=1; REASON="ротацию запросил агент (--rotate-now)"
elif [ "$COMPACTS" -gt 0 ] && [ "$COMPACTS" -ge "$MAX_COMPACTS" ]; then
    NEED_ROTATE=1; REASON="компактов $COMPACTS ≥ потолка $MAX_COMPACTS"
elif [ "$FILL_PCT" -ge "$CTX_ROTATE_PCT" ]; then
    NEED_ROTATE=1; REASON="окно ≈${FILL_PCT}% ≥ ${CTX_ROTATE_PCT}%"
fi

# Пауза владельца: «если пауза то пауза» (владелец, 20.10) — решение сторожа
# о ротации на паузе не доходит до двери: её отказ ложился в журнал и в канал.
# Метка в каталоге паузы называет «отложена» один раз; конец паузы снимает её
# вместе с паузой (pause.py --снять, шаблон `пауза-сказано-*`).
# Код: 0 — пауза стоит, 1 — работа идёт, 2 — неизвестно (сбой pause.py). «--идёт-ли»
# при падении Python даёт тот же 1, что и «паузы нет», поэтому спрашиваем «--почему»:
# он отвечает словами, а молчание или код ≠ 0 — это сбой, не «паузы нет».
работа_на_паузе() {
    local said
    said=$(python3 "$HARNESS_SCRIPTS/pause.py" --почему 2>/dev/null) || return 2
    case "$said" in
        "работа идёт") return 1 ;;
        "на паузе"*) return 0 ;;
        *) return 2 ;;
    esac
}
if работа_на_паузе; then WORK_PAUSED=1; else WORK_PAUSED=0; fi
ROTATE_SUPPRESSED=0

# Флаг «ротация ждёт / идёт». Флаг ушедшей смены снимается любым прогоном:
# падение или перезапуск руками обходят все прочие пути снятия. Флаг своей
# смены — это назревшая ротация: окно могло не дотянуть до порога, а помощники
# уже закончили. Принуждённый (`--rotate-now` при помощниках) доводится как
# принудительный — мимо антиповтора и паузы, как и сам явный вызов.
ROTATION_WAITED_AT=$(date +%s); ROTATION_WAITED_SEC=0; ROTATION_HELD=0
[ "$ROTATE_OWNER_OVERRIDE" != 1 ] || jlog "rotate_owner_override" "$SESSION_ID" "слово владельца: ворота помощников не спрашиваются"
if [ -e "$ROTATION_FLAG" ]; then
    FLAG_SESSION=$(rotation_flag_read сессия)
    if [ -n "$FLAG_SESSION" ] && [ "$FLAG_SESSION" != "$SHIFT_SESSION_ID" ]; then
        rotation_flag_clear "флаг ушедшей смены $FLAG_SESSION"
    else
        [ "$NEED_ROTATE" = 1 ] || { NEED_ROTATE=1; REASON="$(rotation_flag_read причина) (ротация ждала помощников)"; }
        [ "$(rotation_flag_read принуждена)" != 1 ] || FORCE_ROTATE=1
        ROTATION_WAITED_SEC=$(rotation_waited_sec "$(rotation_flag_read ждали_сек)" \
            "$(rotation_flag_read проверено)" "$ROTATION_WAITED_AT" "$WORK_PAUSED")
    fi
fi
if [ "$NEED_ROTATE" = 1 ] && [ "$FORCE_ROTATE" != 1 ] && [ "$WORK_PAUSED" = 1 ]; then
    PAUSE_STATE_DIR="${HARNESS_PANEL_STATE:-$(python3 -c 'import sys; sys.path.insert(0, sys.argv[1]); import config; print(config.panel_state_dir())' "$HARNESS_SCRIPTS/lib" 2>/dev/null)}"
    if [ -n "$PAUSE_STATE_DIR" ] && [ ! -e "$PAUSE_STATE_DIR/пауза-сказано-ротация" ]; then
        : > "$PAUSE_STATE_DIR/пауза-сказано-ротация" 2>/dev/null \
            && say "ротация отложена: пауза владельца ($REASON)"
    fi
    NEED_ROTATE=0; ROTATE_SUPPRESSED=1
fi

# Помощников считает один судья, и считает ДО решения: ротация при идущих
# помощниках не начинается. Результат не глотается — отказ ворот гасит ротацию
# (антиповтор и дверь передачи ниже спрашиваются только у разрешённой).
judge_work
if [ "$NEED_ROTATE" = 1 ]; then
    if ! rotation_helpers_gate; then
        NEED_ROTATE=0; ROTATE_SUPPRESSED=1; ROTATION_HELD=1
        rotation_hold_effects
    fi
fi

# Защита от спама — РАЗДЕЛЬНО по видам события. Анонс владельцу (semi) и
# поданная в панель команда (full) — разные вещи: первый ждёт чужого решения,
# вторая уже исполняется. Пока оба писались событием rotate_command, анонс,
# на который владелец не ответил, давил ротацию весь ROTATE_COOLDOWN_MIN.
# Улика 11.08.2026: анонс 22:20 → «повтор не подаю» в 22:30 и 22:40 при окне
# 97% и 114% → контекст переполнился и ушёл в автосжатие, то есть ровно в то,
# что ротация обязана предотвращать. Поэтому и окно у анонса своё, короткое:
# неотвеченный вопрос стоит владельцу одного сообщения, а молчание сторожа —
# потерянной сессии.
if [ "$NEED_ROTATE" = 1 ] && [ "$FORCE_ROTATE" != 1 ]; then
    read -r VERDICT LAST_EVENT AGE_MIN GAP_MIN <<<"$(подавить_ротацию \
        "$ROTATION_LOG" "$SESSION_ID" "${ROTATE_NEEDS_OWNER:-0}" "$(date +%s)")"
    if [ "$VERDICT" = "да" ]; then
        # Формулировка честная: ротация ТРЕБУЕТСЯ, просто подавлена. Раньше
        # следом печаталось «ротация не требуется» — прибор врал тому, кто
        # придёт читать журнал после отказа.
        say "ротация ТРЕБУЕТСЯ ($REASON), но подавлена антиповтором: $LAST_EVENT был ${AGE_MIN} мин назад (< ${GAP_MIN}); повтор через $(( GAP_MIN - AGE_MIN )) мин"
        NEED_ROTATE=0; ROTATE_SUPPRESSED=1
    fi
fi

# Метка живости: хук считает флаг протухшим, если его не трогали
# ROTATE_FLAG_STALE_MIN. Сторож переписывает его на каждом прогоне, и на паузе.
if [ "$NEED_ROTATE" != 1 ] && [ "$ROTATION_HELD" != 1 ] && [ -e "$ROTATION_FLAG" ]; then
    rotation_flag_put "$(rotation_flag_read этап)" "$JUDGE_HELPERS" "$ROTATION_WAITED_SEC"
fi

rotate_semi() {
    # SC2155 (П-17): local и присвоение раздельно — иначе rc подстановки глотается.
    local msg
    msg="Пора ротация сессии агента: $REASON.
${HANDOVER_NOTE:+$HANDOVER_NOTE
}Скомандуйте агенту завершение: обновить STATE.md, дописать docs/handover/SESSION-HANDOFF-$(date +%Y-%m-%d).md, выйти."
    # jlog — ТОЛЬКО после ok:true (Б-4в): запись до отправки взводит кулдаун,
    # и при недоставке повтор анонса давится, а владелец так и не узнаёт.
    if tg_send "$msg"; then
        jlog "rotate_announced" "$SESSION_ID" "режим semi: $REASON — анонс доставлен (ok:true), жду решения владельца"
        say "анонс ротации отправлен владельцу (ok:true)"
    else
        say "анонс ротации НЕ ДОСТАВЛЕН — событие в rotation.jsonl не пишу, следующий прогон повторит попытку"
        return 1
    fi
}

# ── Быстрый путь смены сессии: «/clear» без выхода из процесса ──────────────
# Решение владельца 11.09.2026 («механизма нужно оба, для каждого своя роль»)
# и его же принцип: «раз есть команды, надо ими пользоваться». Здесь не нужно
# ничего из тяжёлого пути — ни диалога подтверждения выхода с лестницей
# ответов, ни подъёма преемника, ни дозора позднего выхода: процесс остаётся
# жив. За месяц тяжёлый путь дал 48 таймаутов на 135 попыток; у быстрого
# таймаутиться нечему.
#
# Замер 11.09.2026, отдельная сессия: 117 385 → 34 927 токенов, новый
# идентификатор сессии, новый файл транскрипта, CLAUDE.md и указания в
# контексте остались (проверено секретным словом — ответ пришёл из контекста,
# без чтения файла).
#
# Возвращает 0 — сессия сменена, 1 — не удалось (вызывающий уходит в rotate_full).
# Факты для двери ротации добываются ТЕМИ ЖЕ судьями, что и в остальном
# харнесе: свежесть передачи — handover-check.sh (он один знает маску
# docs/handover/SESSION-HANDOFF-*.md), лимит — limit_mark.py (он один судит
# лимит и для двери канала). Второй судья того же факта разъезжается молча.
# У обоих судей ТРИ исхода, а не два: «да», «нет» и «не смог спросить». Третий
# прежде сливался со вторым, и половина двери выключалась молча — переименовали
# ключ, нет интерпретатора, не завершена установка (handover-check отвечает 2),
# а в журнале стояла ложная причина (находки ревью F1-gen-03 и F1-gen-10).
# «Не смог спросить» всегда трактуется в безопасную сторону — ротации нет.
передача_после() {  # $1 = миг (unix); печатает 1/0
    local rc=0
    bash "$PROJECT_DIR/scripts/handover-check.sh" --после "$1" >/dev/null 2>&1 || rc=$?
    case "$rc" in
        0) printf '1\n' ;;
        1) printf '0\n' ;;
        *) say "судья передачи не ответил (код $rc) — считаю, что передачи нет"; printf '0\n' ;;
    esac
}

лимит_сейчас() {  # печатает 1/0
    local rc=0
    # Ротация судится раньше ветки 6б: метки может ещё не быть, а лимит уже в журнале.
    limit_active
    [ "$LIMIT_ACTIVE" = 0 ] || { printf '1\n'; return 0; }
    python3 "$PROJECT_DIR/scripts/limit_mark.py" --лимит-держится >/dev/null 2>&1 || rc=$?
    case "$rc" in
        0) printf '1\n' ;;
        1) printf '0\n' ;;
        *) say "судья лимита не ответил (код $rc) — считаю, что лимит держится"; printf '1\n' ;;
    esac
}

# Миг начала ТЕКУЩЕЙ сессии: передача ЭТОЙ смены написана после него. Нужен
# двум путям (находки ревью F1-gen-02 и F1-gen-12): принудительной ротации, у
# которой мига поручения не существует вовсе, и предохранителю от вечного
# отказа. Окно «моложе получаса» для принуждения не годится: между передачей и
# уходом агента лежат коммит и прогон ворот, а он идёт 20–40 минут.
миг_начала_сессии() {
    local rozhdenie=""
    [ -f "$TRANSCRIPT" ] && rozhdenie=$(stat -c '%W' "$TRANSCRIPT" 2>/dev/null || true)
    # Ноль — файловая система не хранит время рождения: тогда окно из данных.
    if [[ "$rozhdenie" =~ ^[0-9]+$ ]] && [ "$rozhdenie" -gt 0 ]; then
        printf '%s\n' "$rozhdenie"
        return 0
    fi
    printf '%s\n' "$(( $(date +%s) - ${ROTATE_FORCE_HANDOVER_WINDOW_MIN:-30} * 60 ))"
}

# Сколько раз подряд дверь отказала ЭТОЙ сессии. Считается по журналу ротации —
# он уже ведётся, и второй носитель того же факта разъехался бы с первым.
отказов_подряд() {
    local n=0
    [ -f "$ROTATION_LOG" ] || { printf '0\n'; return 0; }
    n=$(grep -F "\"$SESSION_ID\"" "$ROTATION_LOG" 2>/dev/null | tail -20 \
        | grep -c 'rotate_refused' || true)
    printf '%s\n' "${n:-0}"
}

# Дверь ротации: спрашивается ПЕРЕД разрушительным шагом ОБОИХ путей.
# Код 0 — менять сессию можно, 2 — запрещено (и тяжёлый путь тоже не идёт:
# запрет на ротацию — запрет на оба пути, иначе отказ быстрого пути просто
# передаёт разрушение дальше).
дверь_ротации() {  # $1 = миг поручения (unix; 0 — судить по началу сессии)
    # Коды берутся ЯВНО (`|| rc=$?`): под `set -e` присваивание из подстановки
    # с ненулевым кодом убивает демона, и функция была бы жива только потому,
    # что оба её зова стоят в «||»-списке (находка ревью F1-gen-11).
    local mig="${1:-0}" nachalo otkazov verdict rc=0 povod told age_min="" limit
    nachalo=$(миг_начала_сессии)
    otkazov=$(отказов_подряд)
    # ПРЕДОХРАНИТЕЛЬ ОТ ВЕЧНОГО ОТКАЗА (находка ревью F1-gen-05). Автописателя
    # передачи в харнесе НЕТ: проверено 18.10.2026 — pre_compact_handover.sh
    # пишет одну строку события и ничего больше. Значит строгий вопрос («что
    # написано ПОСЛЕ поручения») при длинном лимите не получил бы ответа
    # никогда, окно дошло бы до автосжатия, а владелец не узнал бы почему.
    # После N отказов подряд довольствуемся передачей ЭТОЙ смены и говорим
    # вслух, что именно потеряно — хвост работы после неё.
    if [ "$mig" = 0 ] || [ "$otkazov" -ge "${ROTATE_REFUSED_FALLBACK:-3}" ]; then
        [ "$mig" = 0 ] || say "дверь ротации: отказов подряд $otkazov — сужу по передаче ЭТОЙ смены, хвост работы после неё в неё не попал"
        mig="$nachalo"
    fi
    limit=$(лимит_сейчас)
    verdict=$(ротация_разрешена "$(передача_после "$mig")" "$limit" \
                                "${ROTATE_WITHOUT_HANDOVER:-0}" "${ROTATE_WITHOUT_HANDOVER_WHY:-}") || rc=$?
    if [ "${verdict%%:*}" = "да" ]; then
        say "дверь ротации: $verdict"
        return 0
    fi
    say "ротация ОТМЕНЕНА — $verdict"
    jlog "rotate_refused" "$SESSION_ID" "$verdict"
    # Владелец 17.10: о лимите одно сообщение со временем, потом тишина. Отказ из-за
    # лимита — не смена сессии, а второй голос о том же; весть о лимите скажет 6б.
    [ "$limit" = 0 ] || return 2
    # Владельцу — одна весть НА ПРИЧИНУ: метка названа поводом, иначе отказ по
    # лимиту глушил бы весть об отказе по отсутствию передачи (F1-gen-08).
    # Повод — первое слово вердикта после «нет: ».
    povod=$(printf '%s' "${verdict#нет: }" | cut -d' ' -f1-2 | tr -c 'а-яА-Яa-zA-Z0-9' '-')
    told="$LOG_DIR/rotate-refused.$povod.told"
    if [ -f "$told" ]; then
        age_min=$(( ( $(date +%s) - $(stat -c '%Y' "$told") ) / 60 ))
    fi
    if подавлен_кулдауном "$age_min" "${ROTATE_REFUSED_TELL_GAP_MIN:-180}"; then
        say "об отказе ротации («$povod») сказано $age_min мин назад — молчу"
    # «--не-досылать»: при держащемся лимите весть об отказе ПОСЛЕ обновления
    # лжёт дважды («держится лимит» — уже нет, «работа идёт» — как раз стояла),
    # и становится третьим голосом о лимите (F1-gen-07).
    elif tg_send "Смену сессии отменил: ${verdict#нет: }. Контекст цел, работа не потеряна. Сессия сменится, как только передача дел будет написана." --не-досылать; then
        date +%s > "$told"
    else
        say "весть об отказе ротации не ушла"
    fi
    return 2
}

rotate_clear() {
    local ordered_at idle turn_done waited=0 was_id new_id was_tokens now_tokens
    if ! tmux has-session -t "$TMUX_SESSION" 2>/dev/null; then
        say "tmux-сессии '$TMUX_SESSION' нет — быстрый путь неприменим"
        return 1
    fi
    # Ранняя дверь: под держащимся лимитом поручение регламента заведомо не
    # будет исполнено, и ждать его 900 с незачем — а если передача ЭТОЙ смены
    # уже написана, дверь пропускает сразу (находка ревью F1-gen-12).
    дверь_ротации 0 || return $?
    was_id="$SESSION_ID"
    was_tokens=$(окно_в_токенах "$TRANSCRIPT")
    # Подпись обязательна: в панель пишут двое, и агент однажды принял слова
    # сторожа за слова владельца (улика 12.08.2026, 18:05).
    if ! agent_prompt "[сторож сессий, автоматическая ротация — это не сообщение владельца] Пора менять контекст: $REASON. Заверши работу по регламенту: перезапиши STATE.md (что верно сейчас), допиши docs/handover/SESSION-HANDOFF-$(date +%Y-%m-%d).md, закоммить и отчитайся владельцу в канал. Помощников не запускай — коммить и пиши передачу сам. Выходить НЕ нужно и НЕ вызывай session-warden.sh --rotate-now: как только панель замолчит, я сам подам «/clear» — процесс останется жив, контекст очистится."; then
        say "поручение в панель не ушло — быстрый путь неприменим"
        return 1
    fi
    jlog "rotate_command" "$SESSION_ID" "режим clear: $REASON — поручение подано в tmux"
    ordered_at=$(date +%s)

    # Ждём того же, что и тяжёлый путь: ход закончен И панель молчит. Одного
    # молчания мало — ход мог возобновиться; одной метки мало — она осталась бы
    # прежней (те же улики, что у выход_из_ротации).
    while [ "$waited" -lt "${ROTATE_FINISH_TIMEOUT_SEC:-900}" ]; do
        sleep 15; waited=$((waited + 15))
        # Помощники держат: срок регламента не тикает (ждём их, а не подаём
        # «/clear»), флаг освежается — иначе хук счёл бы его протухшим.
        if ! rotation_helpers_gate; then
            waited=$((waited - 15))
            rotation_flag_put идёт "$JUDGE_HELPERS" "$ROTATION_WAITED_SEC"
            continue
        fi
        idle=$(простой_панели)
        turn_done=$(ход_завершён_после "$ordered_at")
        [ "$turn_done" = 1 ] && [ "$idle" -ge "${ROTATE_IDLE_SEC:-120}" ] && break
    done
    if [ "$waited" -ge "${ROTATE_FINISH_TIMEOUT_SEC:-900}" ]; then
        say "регламент не закончен за ${waited}с — быстрый путь отменяю, решает тяжёлый"
        jlog "clear_timeout" "$SESSION_ID" "регламент не завершён за ${waited}с"
        return 1
    fi
    # Регламент «отработан» — это молчание панели, а молчит она и под лимитом.
    # Спрашиваем ДЕЛО: появилась ли передача после поручения (владелец 18.10).
    дверь_ротации "$ordered_at" || return $?

    say "регламент отработан за ${waited}с, панель молчит ${idle}с — подаю «/clear»"

    PANE_REFUSAL=""
    if ! agent_rotation_prompt "/clear"; then
        say "«/clear» в панель НЕ ушёл"
        # Помощники появились между последней проверкой и командой: тяжёлый
        # путь оборвал бы их так же, поэтому это отказ, а не повод для него.
        [ "$PANE_REFUSAL" != "помощники" ] || return 2
        return 1
    fi
    # Новый идентификатор — единственное доказательство, что команда принята:
    # «/clear» заводит новую сессию и новый файл транскрипта (замер 11.09).
    waited=0
    while [ "$waited" -lt 90 ]; do
        sleep 5; waited=$((waited + 5))
        new_id=$(свежий_id)
        [ -n "$new_id" ] && [ "$new_id" != "$was_id" ] && break
    done
    if [ -z "$new_id" ] || [ "$new_id" = "$was_id" ]; then
        say "после «/clear» сессия не сменилась за ${waited}с (id прежний: $was_id)"
        jlog "clear_failed" "$was_id" "новый идентификатор сессии не появился за ${waited}с"
        return 1
    fi
    now_tokens=$(окно_в_токенах "$PROJECT_TRANSCRIPTS/$new_id.jsonl")
    say "сессия сменена без перезапуска: $was_id → $new_id (окно ${was_tokens:-?} → ${now_tokens:-?} токенов)"

    # Преемнику — то же задание, что и после полного перезапуска, плюс осмотр:
    # хук старта сессии на «/clear» не срабатывает, а состояние знать нужно.
    agent_prompt "Контекст очищен сторожем сессий (это не сообщение владельца). Прочитай STATE.md, последний docs/handover/SESSION-HANDOFF-*.md и CLAUDE.md, выполни «bash scripts/hooks/session_state.sh» для осмотра, назови владельцу в канал текущую задачу и следующий шаг, проверь $LOG_DIR/inbox/ и продолжай работу." \
        || say "задание преемнику не ушло — сессия чиста, но без поручения"
    # Удачная смена снимает метки «об отказе сказано»: следующий отказ — уже
    # другая история, и молчать о нём нельзя (находка ревью F1-gen-08).
    rm -f "$LOG_DIR"/rotate-refused.*.told 2>/dev/null || true
    rotation_flag_clear "режим clear: смена сменилась"
    jlog "agent_restarted" "$new_id" "режим clear: контекст очищен, процесс жив, задание подано"
    return 0
}

rotate_full() {
    if ! tmux has-session -t "$TMUX_SESSION" 2>/dev/null; then
        say "tmux-сессии '$TMUX_SESSION' нет — ротировать нечего; сигнал владельцу"
        tg_send "Ротация нужна ($REASON), но tmux-сессии '$TMUX_SESSION' нет. Агент не запущен?" || say "и сигнал не ушёл"
        return 1
    fi
    say "шлю команду завершения в tmux '$TMUX_SESSION'"
    # Запросивший ротацию агент регламент уже отработал — ему нужен выход, а не
    # поручение закрываться: второе поручение он начал бы выполнять заново.
    # Имя файла передачи — строго docs/handover/SESSION-HANDOFF-<дата>.md (С-6):
    # по этой маске его ищут handover-check, stop_reminder и session_state.
    if [ "$FORCE_ROTATE" = 1 ]; then PROMPT="/exit"
    # Поручение НЕ требует выхода: выйти агент не может (см. выход_из_ротации),
    # а попытка выйти «как принято в проекте» — через `--rotate-now` — ставит
    # второй сторож в очередь за локом ЭТОГО прогона и вешает обоих (улика
    # 12.08.2026). Подпись в начале обязательна: в панель пишут двое — диспетчер
    # канала и сторож, — и агент, приняв поручение сторожа за слова владельца,
    # процитировал их владельцу как его же указание (улика 12.08.2026, 18:05).
    else PROMPT="[сторож сессий, автоматическая ротация — это не сообщение владельца] Пора менять сессию: $REASON. Заверши работу по регламенту: перезапиши STATE.md (что верно сейчас), допиши docs/handover/SESSION-HANDOFF-$(date +%Y-%m-%d).md, закоммить и отчитайся владельцу в канал. Помощников не запускай — коммить и пиши передачу сам. Выходить не нужно и НЕ вызывай session-warden.sh --rotate-now: смену веду я — как только панель замолчит, сам введу «/exit» и подниму преемника."; fi
    # Принудительная ротация подаёт «/exit» СРАЗУ: агент попросил её сам,
    # отработав регламент. Мига поручения здесь не существует, и судить надо
    # по началу сессии — «передача ЭТОЙ смены написана» (довод 0). Окно в
    # полчаса, стоявшее тут сперва, отказывало честному уходу: между передачей
    # и уходом лежат коммит и прогон ворот, 20–40 минут (ревью F1-gen-02).
    #
    # Обычный путь спрашивает ту же дверь ДО поручения по той же причине, что
    # и быстрый: под лимитом ждать нечего.
    дверь_ротации 0 || return $?   # тяжёлый путь: до «/exit» и до поручения
    # «/exit» — команда смены сессии: её дверь паузой не гасится (agent_prompt
    # — служебный толчок, его пауза держит и «/exit» не пропустила бы).
    local send_fn=agent_prompt
    [ "$FORCE_ROTATE" = 1 ] && send_fn=agent_rotation_prompt
    PANE_REFUSAL=""
    if ! "$send_fn" "$PROMPT"; then
        if [ -n "$PANE_REFUSAL" ]; then
            tg_send "Ротация нужна ($REASON), но команда в панель '$TMUX_SESSION' не ушла: $PANE_REFUSAL." || say "и сигнал не ушёл"
        else
            tg_send "Ротация нужна ($REASON), но в tmux-панели '$TMUX_SESSION' не агент — команду не отправил (текст в оболочке исполнился бы). Проверьте сессию." || say "и сигнал не ушёл"
        fi
        return 1
    fi
    # Команда реально ушла агенту — только теперь событие в журнал (кулдаун).
    jlog "rotate_command" "$SESSION_ID" "режим full: $REASON — команда подана в tmux"

    # Ждём, пока агент отработает регламент, и закрываем сессию сами. Виды
    # завершения перечисляет смена_состоялась, кто вводит «/exit» — решает
    # выход_из_ротации; там же улики, из-за которых каждая ветка появилась.
    local waited=0 pane="" alive=1 verdict="ждём" act="ждём"
    local exit_sent=0 deadline="$ROTATE_FINISH_TIMEOUT_SEC" idle=0 alarm_sent=0
    local alarm_watch="${ROTATE_ALARM_WATCH_SEC:-300}" turn_done=0
    # Ожидание фоновой задачи, держащей очередь ввода: своё, с потолком. Когда
    # потолок выбран, задача перестаёт быть оправданием и путь обычный —
    # тревога. Иначе «жду задачу» стало бы вечным алиби зависшей сессии.
    local tasks_live=0 task_waited=0 tasks_capped=0
    # Счёт попыток по диалогу: он и решает, чем отвечать (клавиши_подтверждения).
    local dialog_tries=0 dialog_rounds=0 dialog_capped=0 pane_text="" picked="" keys="" held=0 sent="" screen="" pick_num=""
    local helpers_hold=0
    # Момент поручения: ходы, законченные ДО него, к ротации отношения не имеют.
    local ordered_at; ordered_at=$(date +%s)
    while :; do
        sleep 30; waited=$((waited + 30))
        alive=1; tmux has-session -t "$TMUX_SESSION" 2>/dev/null || alive=0
        pane=$(pane_cmd)
        verdict=$(смена_состоялась "$alive" "$pane" "$(свежий_id)" "$SESSION_ID")
        idle=$(простой_панели)
        turn_done=$(ход_завершён_после "$ordered_at")
        helpers_hold=0; rotation_helpers_gate || helpers_hold=1
        # Раньше признака задач: пока диалог не подтверждён, «/exit» не исполнится
        # НИКОГДА, и ожидание задачи было бы ожиданием того, чего никто не ждёт.
        if [ "$exit_sent" = 1 ] && [ "$alive" = 1 ] && [ "$dialog_capped" = 0 ]; then
            pane_text=$(tmux capture-pane -p -t "$TMUX_SESSION" 2>/dev/null || true)
            if диалог_выхода_жив "$pane_text" "$pane"; then
                dialog_tries=$((dialog_tries + 1))
                picked=$(подсвеченный_пункт_в "$pane_text")
                keys=$(клавиши_подтверждения "$dialog_tries" "$helpers_hold")
                # Подставляем НАСТОЯЩИЙ номер пункта; не нашли — подтверждаем
                # подсвеченное, слепая цифра хуже, чем Enter.
                if [ "${keys#ПУНКТ }" != "$keys" ]; then
                    pick_num=$(номер_пункта_выхода "$pane_text")
                    keys="${pick_num:-Enter} ${keys#ПУНКТ }"
                    [ -n "$pick_num" ] || keys="Enter"
                elif [ "${keys#ФОНОМ }" != "$keys" ]; then
                    # Пункт «уйти фоном» ничего не останавливает — им и выходим,
                    # когда «остановить задачи» не поддался (улика 13.09.2026).
                    pick_num=$(номер_пункта_фоном "$pane_text")
                    keys="${pick_num:-Enter} ${keys#ФОНОМ }"
                    [ -n "$pick_num" ] || keys="Enter"
                fi
                say "«/exit» перехвачен вопросом о фоновых задачах (попытка $dialog_tries, подсвечено «${picked:-не разобрал}») — шлю «$keys»"
                # Прибор различения (10.09.2026): лечение лестницей выбрано БЕЗ
                # воспроизведённой причины, и по прежнему журналу проверить его
                # нечем — сорок строк были одинаковы. Пишем сырьё: что стоит в
                # диалоге, какие задачи он называет, что ответил tmux на каждую
                # клавишу. Следующая же ротация покажет, помогает лестница или
                # диалог держит что-то другое.
                held=$(printf '%s' "$pane_text" | grep -cE '^\s+(shell|bash|task) ·' || true)
                sent=""
                for k in $keys; do
                    # Снимок мог устареть за 0,7 с предыдущей клавиши: агент сам
                    # подтвердил диалог — и Escape прилетит в работающую сессию,
                    # оборвав ход (ревью 10.09.2026). Перечитываем перед каждой.
                    if ! диалог_выхода_жив "$(tmux capture-pane -p -t "$TMUX_SESSION" 2>/dev/null || true)" "$(pane_cmd)"; then
                        say "диалог закрылся сам — остальные клавиши не шлю"
                        sent="${sent:+$sent,}$k=не нужен"
                        break
                    fi
                    if pane_command keys "$k"; then
                        sent="${sent:+$sent,}$k=ок"
                    else
                        sent="${sent:+$sent,}$k=ОТКАЗ"
                        say "клавиша «$k» в панель не ушла"
                    fi
                    sleep "${PANE_ENTER_DELAY:-0.7}"
                done
                # Экран диалога целиком, одной строкой: по нему видно и текст
                # вопроса, и что именно держит выход.
                # «|| true»: под pipefail пустой grep уронил бы ротацию целиком.
                screen=$(printf '%s' "$pane_text" | grep -A 12 -F 'Background work is running' \
                         | tr '\n' '|' | cut -c1-400 || true)
                jlog "rotate_exit_dialog" "$SESSION_ID" "попытка $dialog_tries, подсвечено «${picked:-?}», клавиши «$keys» ($sent), задач в списке: $held, экран: $screen"
                if [ "$keys" = Escape ] && [ "$helpers_hold" = 1 ]; then
                    # Escape отменил выход: вернулись к ожиданию помощников, а не к кругу лестницы.
                    say "диалог выхода при идущих помощниках отменён Escape — «/exit» подам, когда они закончат"
                    exit_sent=0; dialog_tries=0; deadline=$(( waited + 60 ))
                    continue
                fi
                if [ "$keys" = Escape ]; then
                    dialog_rounds=$((dialog_rounds + 1))
                    say "диалог не поддался $dialog_tries раз (круг $dialog_rounds) — сбросил Escape и подаю «/exit» заново"
                    agent_rotation_prompt "/exit" || say "«/exit» в панель не ушёл (в панели: $pane)"
                    dialog_tries=0
                fi
                # Потолок кругов: без него ветка делала «continue» ДО решения о
                # сроке, и лестница крутилась вечно с занятым локом — стояли и
                # ротация, и плановые прогоны, а владелец не знал (ревью 10.09).
                if [ "$dialog_rounds" -ge "${ROTATE_DIALOG_ROUNDS:-3}" ]; then
                    say "диалог выхода не поддался за ${dialog_rounds} круга — дальше как обычный отказ, лестницу прекращаю"
                    jlog "rotate_dialog_capped" "$SESSION_ID" "лестница ответов исчерпана: ${dialog_rounds} круга по 5 попыток; снимок: $(сохранить_снимок "диалог-выхода")"
                    tg_send "Ротация: сессия показывает вопрос о фоновых задачах и не закрывается ни Enter, ни выбором пункта, ни Escape — $((dialog_rounds * 5)) попыток. Дальше действую обычным порядком (тревога и досмотр); если увидите панель — нажмите «1» руками." || say "и сигнал не ушёл"
                    dialog_capped=1
                else
                    continue
                fi
            fi
        fi
        tasks_live=0
        [ "$tasks_capped" = 1 ] || { фоновые_задачи_живы "$SESSION_ID" && tasks_live=1; }
        act=$(выход_из_ротации "$verdict" "$idle" "$exit_sent" "$waited" "$deadline" "$turn_done" "$tasks_live" "$helpers_hold")
        # Срок регламента не тикает, пока помощники держат: ожидание ограничено
        # ROTATE_HELPERS_WAIT_MAX_MIN. Флаг освежается — он не должен протухнуть.
        if [ "$helpers_hold" = 1 ] && [ "$act" = "ждём" ]; then
            deadline=$(( waited + 60 ))
            rotation_flag_put идёт "$JUDGE_HELPERS" "$ROTATION_WAITED_SEC"
        fi
        case "$act" in
            смена) break ;;
            # «/exit» бывает медленнее срока. 12.08.2026, 19:53: сторож сказал
            # «не закрылась», вышел из ротации — и сессия закрылась через минуту
            # уже без него. Преемника поднял только следующий тик: семь минут
            # без агента, и всё это время сообщение владельца лежало в inbox.
            # Тревога владельцу — не конец смены, а просьба быть наготове.
            тревога)
                [ "$alarm_sent" = 1 ] && break
                say "сессия НЕ закрылась и после «/exit» (в панели: $pane) — сигнал владельцу, смену досматриваю ещё ${alarm_watch}с"
                jlog "rotate_timeout" "$SESSION_ID" "не завершилась за ${waited}с, «/exit» в панель не подействовал — досмотр ${alarm_watch}с"
                tg_send "Ротация: сессия не закрылась за $((waited / 60)) мин даже после «/exit» в панель. Досматриваю ещё $((alarm_watch / 60)) мин: закроется сама — подниму преемника и скажу вам, что вмешательство не нужно." || say "и сигнал не ушёл"
                alarm_sent=1; deadline=$(( waited + alarm_watch )); continue ;;
            задачи)
                task_waited=$((task_waited + 30))
                if [ "$task_waited" -ge "${ROTATE_TASK_WAIT_SEC:-900}" ]; then
                    tasks_capped=1
                    say "фоновая задача сессии держит очередь ввода уже ${task_waited}с — потолок выбран, дальше считаю это зависанием"
                    continue
                fi
                [ $((task_waited % 120)) -eq 0 ] \
                    && say "«/exit» принят, но исполнится после фоновой задачи сессии (ждём ${task_waited}с из ${ROTATE_TASK_WAIT_SEC:-900})"
                deadline=$(( waited + 60 )); continue ;;
            ждём) continue ;;
            выход|принудительно)
                if [ "$act" = принудительно ]; then
                    say "срок ${deadline}с вышел, а агент ещё в ходу (ход завершён: ${turn_done}, простой ${idle}с) — ввожу «/exit» всё равно"
                else
                    say "агент закончил ход после поручения и панель молчит ${idle}с — регламент отработан, ввожу «/exit» за него"
                fi
                # Молчание панели бывает и от лимита: спрашиваем ДЕЛО —
                # появилась ли передача после поручения (владелец 18.10).
                #
                # Два условия, и каждое куплено находкой ревью. `exit_sent=0`:
                # в эту ветку путь приходит и второй раз (по «принудительно»),
                # а отказ ПОСЛЕ поданного «/exit» бросил бы сессию закрываться
                # без преемника (F1-gen-01, вторая половина). `FORCE_ROTATE=0`:
                # принудительному пути дверь уже открыта выше, до «/exit», и
                # второй вопрос — с мигом, назначенным ПОСЛЕ выхода, — отказал
                # бы всегда (F1-gen-01, первая половина).
                if [ "$exit_sent" = 0 ] && [ "$FORCE_ROTATE" = 0 ]; then
                    дверь_ротации "$ordered_at" || return $?
                    # Перезагрузка заменяет «/exit»: помощников, паузу, задачи и
                    # занятость машины спрашиваем заново, ворота выше стояли минуты назад.
                    local rb_paused=0 rb_tasks=0 rb_helpers=0 rb_busy=0 rb_busy_out="" rb_busy_rc=0
                    local rb_need=0 rb_kernel="-" rb_hours="" rb_word="" rb_rc=0 rb_pause_rc=0
                    rotation_helpers_gate || true
                    if [[ "$JUDGE_HELPERS" =~ ^[0-9]+$ ]]; then rb_helpers=$(( JUDGE_HELPERS + ${JUDGE_HUNG:-0} )); else rb_helpers="?"; fi
                    работа_на_паузе || rb_pause_rc=$?
                    case "$rb_pause_rc" in 0) rb_paused=1 ;; 1) rb_paused=0 ;; *) rb_paused="?" ;; esac
                    фоновые_задачи_живы "${SHIFT_SESSION_ID:-$SESSION_ID}" && rb_tasks=1
                    rb_busy_out=$(python3 "$HARNESS_SCRIPTS/boot_check.py" --занято 2>/dev/null) || rb_busy_rc=$?
                    case "$rb_busy_rc" in 0) rb_busy=0 ;; 1) rb_busy="${rb_busy_out#занята: }" ;; *) rb_busy="?" ;; esac
                    read -r rb_need rb_kernel < <(reboot_needed)
                    rb_hours=$(awk '{print int($1 / 3600)}' /proc/uptime)
                    rb_word=$(reboot_window_verdict "${AUTO_REBOOT_IN_ROTATION:-0}" "${STACK_NEIGHBOURS:-}" "$rb_paused" "$act" "$rb_tasks" "$rb_helpers" "$rb_busy" "$rb_need" "$rb_hours" "${REBOOT_MIN_GAP_HOURS:-24}" "$(reboot_last_failed "$rb_kernel")") || rb_rc=$?
                    say "перезагрузка при смене: $rb_word"
                    if [ "$rb_rc" = 0 ]; then
                        reboot_for_rotation "$rb_kernel" "$REASON" || rb_rc=$?
                        if [ "$rb_rc" = 0 ]; then
                            # Машина гаснет — сторож гибнет вместе с ней, это и есть смена.
                            sleep "${REBOOT_WAIT_SEC:-180}"
                            jlog "reboot_not_happened" "$SESSION_ID" "команда принята, но за ${REBOOT_WAIT_SEC:-180}с машина не погасла — обычный «/exit»"
                        fi
                    fi
                fi
                jlog "rotate_exit_sent" "$SESSION_ID" "$act: ход завершён=${turn_done}, простой панели ${idle}с, ждали ${waited}с — «/exit» введён в панель"
                agent_rotation_prompt "/exit" || say "«/exit» в панель не ушёл (в панели: $pane)"
                exit_sent=1; deadline=$(( waited + ${ROTATE_EXIT_WAIT_SEC:-180} )) ;;
        esac
    done
    if [ "$act" = "тревога" ]; then
        say "смена не состоялась и за досмотр (${waited}с, в панели: $pane) — дальше нужен владелец"
        jlog "rotate_alarm_timeout" "$SESSION_ID" "не завершилась и за досмотр ${alarm_watch}с после «/exit»"
        # Уходя, оставляем дозор: выход бывает позже нашего срока, и тогда
        # преемника ждать до следующего cron — 10 минут без агента (улика
        # 13.08.2026 у ветки `--досмотр-выхода`). `8>&-` обязателен: без него
        # получасовой потомок унаследует лок сторожа и убьёт плановые прогоны.
        WARDEN_DETACHED=1 setsid nohup "$0" --досмотр-выхода "$SESSION_ID" \
            >> "$LOG_DIR/session-warden.log" 2>&1 < /dev/null 8>&- &
        local watch_pid=$!
        if kill -0 "$watch_pid" 2>/dev/null; then
            say "дозор позднего выхода поставлен (pid $watch_pid) — преемника поднимет он"
            jlog "late_exit_watch" "$SESSION_ID" "сдаю смену, но оставил дозор: поднимет преемника, как только панель освободится"
        else
            say "дозор позднего выхода НЕ запустился — преемника поднимет плановый прогон"
        fi
        tg_send "Ротация: сессия жива и после досмотра ($((waited / 60)) мин с начала смены). Сам её не закрою — нужно вмешаться. Дозор оставил: если она закроется позже сама, преемника подниму без вас и скажу отбой." || say "и сигнал не ушёл"
        return 1
    fi
    case "$verdict" in
        ушла)     say "сессия закрылась вместе с агентом — так завершается панель, созданная командой" ;;
        оболочка) say "панель снова оболочка — агент вышел" ;;
        преемник) say "в панели уже другая сессия ($(свежий_id)) — преемника поднял юнит автозапуска"
                  jlog "successor_detected" "$SESSION_ID" "смену завершил юнит: транскрипт сменился за ${waited}с" ;;
    esac
    say "смена состоялась за ${waited}с ($verdict) — обеспечиваю преемника (Б-4а)"

    # Подъём нового агента — обязанность ротации: завершить и не поднять =
    # система умирает молча (воспроизведённый блокер Б-4).
    if ! start_agent; then
        jlog "restart_failed" "$SESSION_ID" "агент не поднялся за ${AGENT_START_TIMEOUT_SEC}с после ротации"
        say "снимок панели: $(сохранить_снимок "агент-не-поднялся")"
        tg_send "Агент остановлен после ротации, нужен запуск: в tmux '$TMUX_SESSION' команда «$AGENT_START_CMD» не подняла claude за ${AGENT_START_TIMEOUT_SEC}с." --несмотря-на-лимит || say "и сигнал не ушёл"
        return 1
    fi
    # Та же уборка, что и у быстрого пути: удачная смена снимает метки
    # «об отказе сказано» (находка ревью F1-gen-08).
    rm -f "$LOG_DIR"/rotate-refused.*.told 2>/dev/null || true
    jlog "agent_restarted" "$SESSION_ID" "агент поднят после ротации"
    # Тревогу, которая разрешилась сама, обязан снять тот, кто её поднял:
    # иначе владелец идёт вмешиваться в уже работающую систему.
    [ "$alarm_sent" = 1 ] && { jlog "rotate_alarm_cleared" "$SESSION_ID" "смена состоялась на досмотре за ${waited}с"; \
        tg_send "Отбой по прошлой тревоге: сессия закрылась сама на досмотре (${waited}с от начала смены), преемник поднят. Вмешиваться не нужно." || say "и отбой не ушёл"; }
    подхватить_работу || tg_send "Агент поднят после ротации, но пинок «подхвати работу» не дошёл — сессия стоит у пустого приглашения. Напишите ей что угодно." || say "и сигнал не ушёл"

    # Приёмка передачи. БЕЗ MCP-серверов: telegram-плагин допускает одного
    # потребителя getUpdates на токен и отобрал бы канал у живого диспетчера
    # (улика devmap-selfheal.sh).
    local answer rc=0
    # «ничего не меняй»: проверка приёма — ЗАМЕР, а не работа. Без этой оговорки
    # headless-агент видит устаревшую передачу и чинит её сам (улика приёмки
    # 11.08.2026: пробный прогон переписал SESSION-HANDOFF прямо в проверке).
    # Прибор, меняющий то, что измеряет, врёт дважды: правку никто не ревьюил,
    # а следующий замер уже зелёный по построению.
    # Модель — дешёвая (DEMON_MODEL): чтение трёх файлов не стоит opus-цены,
    # а переключатель модели агента на headless-вызовы не действует.
    answer=$(cd "$PROJECT_DIR" && timeout 300 bash "$PROJECT_DIR/scripts/claude-demon.sh" session-warden -p --model "$(model_dlya дежурный)" \
        "прочитай CLAUDE.md, STATE.md и последний docs/handover/*; назови текущую задачу и следующий шаг. НИЧЕГО НЕ МЕНЯЙ: это проверка приёма, а не работа — файлы не правь, коммитов не делай" \
        --mcp-config '{"mcpServers":{}}' --strict-mcp-config --output-format text 2>&1) || rc=$?
    jlog "rotation_check" "$SESSION_ID" "rc=$rc: $(printf '%s' "$answer" | head -c 2000)"
    if [ "$rc" -ne 0 ] || [ -z "$(printf '%s' "$answer" | tr -d '[:space:]')" ]; then
        say "проверка приёма ПРОВАЛЕНА (rc=$rc, ответ пуст или ошибка) — сигнал владельцу"
        tg_send "Ротация выполнена, агент поднят, но проверка приёма провалена (rc=$rc): headless-сессия не назвала задачу и шаг. Передача, вероятно, битая." || say "и сигнал не ушёл"
        return 1
    fi
    say "приём подтверждён: новая сессия назвала задачу и шаг (ответ в rotation.jsonl)"
    # Ответ измерителя владельцу НЕ пересылается: задачу и шаг новая сессия
    # называет в канале сама, первым сообщением, а текст измерителя написан
    # под ЕГО запрет «ничего не меняй» и читается как отчёт рабочего агента,
    # который просит владельца решить за него. Ответ — в rotation.jsonl.
    tg_send "Ротация выполнена ($REASON), агент поднят, приём передачи подтверждён. Задачу и шаг новая смена назовёт сама." --несмотря-на-лимит \
        || say "итоговое уведомление не ушло — ротация при этом состоялась, след в rotation.jsonl"
}

# Каждая ветка обязана оставить след — ненадёжную механику не глотаем молча.
WARDEN_RC=0
# Один толчок tmux за проход: флаг ставят двери pane.sh, ветка 6д смотрит его последней.
TMUX_KICKED=0
if [ "$NEED_ROTATE" = 1 ]; then
    # Ротация — механика харнеса, не решение владельца: она ничего не теряет
    # и ничего не выкатывает, она лишь меняет сессию. Раньше её судьбу решал
    # общий ключ AUTONOMY, и в semi владелец получал «скомандуйте агенту
    # завершение» — харнес перекладывал на него свою работу (улика 11.08.2026).
    # Развилки полуавтомата (выкат, необратимое) живут отдельно и этим ключом
    # не затрагиваются.
    if [ "${ROTATE_NEEDS_OWNER:-0}" = 1 ] && [ "$FORCE_ROTATE" != 1 ]; then
        say "нужна ротация: $REASON (ROTATE_NEEDS_OWNER=1 — спрашиваю владельца)"
        rotate_semi || WARDEN_RC=1
    else
        say "нужна ротация: $REASON — выполняю сам (ROTATE_NEEDS_OWNER=0)"
        # С этой секунды хук кладёт новые запуски помощников в очередь: помощник,
        # запущенный под коммит регламента, оборвался бы выходом так же.
        rotation_flag_put идёт "$JUDGE_HELPERS" "$ROTATION_WAITED_SEC" "$FORCE_ROTATE"
        jlog "rotation_flag_set" "$SHIFT_SESSION_ID" "этап идёт: помощников $JUDGE_HELPERS, ждали ${ROTATION_WAITED_SEC}с"
        # Признаки для выбора пути собираются здесь, решение принимает чистая
        # функция способ_ротации (её 8 путей проверяются самотестом без tmux).
        HOOKS_CHANGED=0
        for f in "$PROJECT_DIR/.claude/settings.json" "$PROJECT_DIR/scripts/hooks"/*; do
            [ -e "$f" ] || continue
            [ "$f" -nt "$TRANSCRIPT" ] && { HOOKS_CHANGED=1; break; }
        done
        VERSION_CHANGED=0
        if [ -n "${CC_VERSION:-}" ] && command -v claude >/dev/null 2>&1; then
            # «|| true»: версия без номера — законный случай (иной формат вывода,
            # не тот бинарник), а под pipefail он уронил бы весь прогон сторожа.
            live_ver=$(claude --version 2>/dev/null | grep -oE '[0-9]+\.[0-9]+\.[0-9]+' | head -1 || true)
            [ -n "$live_ver" ] && [ "$live_ver" != "$CC_VERSION" ] && VERSION_CHANGED=1
        fi
        # Имя с точки: это метка СОБЫТИЯ (когда в последний раз перезапускали
        # смену целиком), а не отметка живого демона. Обходы меток берут «*»
        # и скрытые файлы пропускают — иначе она попадает в список сторожей и
        # «устаревает», не имея никакого периода (владелец 13.09.2026 увидел
        # её в панели среди протухших).
        FULL_STAMP="$HEARTBEAT_DIR/.полный-перезапуск"
        if [ -f "$FULL_STAMP" ]; then
            HOURS_SINCE_FULL=$(( ( $(date +%s) - $(stat -c '%Y' "$FULL_STAMP") ) / 3600 ))
        else
            # Метки нет — процесс живёт с раскладки или дольше суток: тяжёлый путь.
            HOURS_SINCE_FULL=999
        fi
        MODE=$(способ_ротации "$HOOKS_CHANGED" "$VERSION_CHANGED" "$HOURS_SINCE_FULL" \
                                "${FULL_RESTART_MAX_HOURS:-24}" 0 "$FORCE_ROTATE" "$(reboot_would_fit)")
        say "способ смены: $MODE (хуки=$HOOKS_CHANGED версия=$VERSION_CHANGED часов_с_полного=$HOURS_SINCE_FULL принудительно=$FORCE_ROTATE)"
        if [ "$MODE" = clear ]; then
            # Страховка: быстрый путь не удался — тяжёлый доводит смену до конца.
            # Но код 2 — это НЕ неудача, а ЗАПРЕТ (передачи нет): подхватывать
            # его тяжёлым путём значит разрушить контекст другой рукой.
            ROTATE_RC=0; rotate_clear || ROTATE_RC=$?
            if [ "$ROTATE_RC" = 2 ]; then
                say "ротация запрещена дверью — тяжёлый путь тоже не идёт"
            elif [ "$ROTATE_RC" != 0 ]; then
                say "быстрый путь не удался — перехожу на полный перезапуск"
                ROTATE_RC=0; rotate_full || ROTATE_RC=$?
                [ "$ROTATE_RC" = 0 ] || [ "$ROTATE_RC" = 2 ] || WARDEN_RC=1
            fi
        else
            ROTATE_RC=0; rotate_full || ROTATE_RC=$?
            [ "$ROTATE_RC" = 0 ] || [ "$ROTATE_RC" = 2 ] || WARDEN_RC=1
        fi
    fi
elif [ "$ROTATE_SUPPRESSED" != 1 ]; then
    say "ротация не требуется"
fi
# Ротация шла, а флаг остался: сессия не сменилась (отказ двери, неудача), и
# держать запуски помощников незачем. Успешные пути сняли его сами.
[ "$NEED_ROTATE" != 1 ] || rotation_flag_clear "ротация не состоялась, смена остаётся"
rotation_queue_rescue
[ "$NEED_ROTATE" != 1 ] || [ "${ROTATE_RC:-1}" != 0 ] || shift_leftover_sweep

# ── Пауза владельца: присмотр молчит ────────────────────────────────────────
# Владелец 14.09.2026: «Чтобы я остановил работу и больше лишней активности в
# виде сторожа которой тебя пинает больше не было». Пауза гасит ветки, которые
# ПОДГОНЯЮТ: тишину, лимит-немоту и пульс отчётности. Ветку входящих она
# не гасит, но толчок о сообщении идёт дверью pane_kick_owner, и та на паузе
# отказывает: файл ждёт во входящих, смену не будят. Диспетчер на паузе
# обычное сообщение ДЕРЖИТ, снимает паузу только команда resume («продолжай»).
# Ротацию по порогам пауза тоже гасит (раздел 5, определение паузы там же):
# «если пауза то пауза». Явный --rotate-now паузой не гасится.
if [ "$WORK_PAUSED" = 1 ]; then
    say "работа на паузе по решению владельца: тишину, лимит и пульс не трогаю"
    # Запрос, отправленный до паузы, после неё ответа не ждёт: старая метка дала
    # бы владельцу «не ответила N мин», где N — часы паузы.
    rm -f "$LOG_DIR/pulse.kick" "$LOG_DIR/stall.kick" "$LOG_DIR/stall.replied"
fi

limit_active

# ── 6. Silence-watchdog: очередь непуста, а агент молчит ────────────────────
DEVMAP="$PROJECT_DIR/dev-map.yaml"
if [ "$WORK_PAUSED" = 1 ]; then
    :   # на паузе очередь не смотрим: сказано выше, второй раз не повторяем
elif [ -f "$DEVMAP" ]; then
    # Будить агента можно только под РАБОТУ. Ночью 12.08 в очереди стояла одна
    # задача, чью формулировку даёт владелец: пинки уходили каждые
    # SILENCE_MAX_MIN, агент просыпался, отвечал «блокер тот же» и жёг контекст
    # до утра. Признак «ждёт владельца» — поле blocked у задачи в карте.
    QUEUE_OUT=$(python3 "$PROJECT_DIR/scripts/work-queue.py" "$DEVMAP" 2>/dev/null || true)
    WORK=$(printf '%s\n' "$QUEUE_OUT" | sed -n 's/^работа: //p')
    WAITING=$(printf '%s\n' "$QUEUE_OUT" | sed -n 's/^ждут: //p')
    # Прибор не ответил (нет PyYAML, битая карта) — возвращаемся к прежнему
    # признаку: непустая очередь. Молчать из-за сломанного прибора нельзя.
    if ! [[ "${WORK:-}" =~ ^[0-9]+$ ]]; then
        if grep -qE '^queue:' "$DEVMAP" && ! grep -qE '^queue:\s*\[\s*\]\s*$' "$DEVMAP"; then WORK=1; else WORK=0; fi
        say "прибор очереди не ответил — считаю по прежнему признаку (работа=$WORK)"
    fi
    if [ "$WORK" -gt 0 ]; then
        IDLE_MIN="${JUDGE_WORK_MIN:-0}"
        # Пинок «бери следующую» живому помощнику не нужен: главная ждёт его
        # уведомления, и работа идёт; статус у смены просит пульс.
        if [ "$IDLE_MIN" -gt "$SILENCE_MAX_MIN" ] && ! helpers_present && [ "$LIMIT_ACTIVE" = 1 ]; then
            say "тишина ${IDLE_MIN} мин, $(limit_until_text) — молчу"
        elif [ "$IDLE_MIN" -gt "$SILENCE_MAX_MIN" ] && ! helpers_present; then
            say "тишина: очередь непуста, транскрипт молчит ${IDLE_MIN} мин (> ${SILENCE_MAX_MIN}) — пинок в tmux"
            if tmux has-session -t "$TMUX_SESSION" 2>/dev/null; then
                # Пинок НАЗЫВАЕТ, что брать: владелец 26.09.2026 — «если у
                # тебя блокер, но при этом есть любая другая работа, она должна
                # исполняться, вплоть до следующего блокера». Смена трижды за
                # час ответила «свободной работы нет», хотя прибор держал
                # кандидатов: пинок без ответа переспрашивает, а не направляет.
                CHTO_BRAT=$(python3 "$PROJECT_DIR/scripts/work-queue.py" \
                    "$DEVMAP" --следующая 2>/dev/null | head -1)
                [ -n "$CHTO_BRAT" ] || CHTO_BRAT="Продолжай текущую задачу или назови блокер."
                # «Заблокирована она» верно лишь когда прибор сам сказал «следующей
                # работы нет»; иначе пинок приписывал блокировку свободной задаче.
                # Команда с путём к карте: без него work-queue.py не запускается.
                BLOCKED_HINT=""
                case "$CHTO_BRAT" in
                    "СЛЕДУЮЩЕЙ РАБОТЫ НЕТ"*) BLOCKED_HINT=" Заблокирована она — бери следующую по порядку, и так до следующего блокера." ;;
                esac
                if agent_prompt "Работы не видно ${IDLE_MIN} минут. $CHTO_BRAT${BLOCKED_HINT} Порядок работ: python3 $PROJECT_DIR/scripts/work-queue.py $DEVMAP --порядок"; then
                    jlog "silence_kick" "$SESSION_ID" "тишина ${IDLE_MIN} мин при непустой очереди"
                else
                    say "снимок панели: $(сохранить_снимок "выпал-в-оболочку")"
                    tg_send "Очередь непуста, агент молчит ${IDLE_MIN} мин, а в tmux-панели не claude — пинок не отправлен. Похоже, агент выпал в оболочку." --task session-warden:no-agent || say "и сигнал не ушёл"
                    WARDEN_RC=1
                fi
            else
                say "пинать некого: tmux-сессии '$TMUX_SESSION' нет — сигнал владельцу"
                tg_send "Очередь в dev-map.yaml непуста, агент молчит ${IDLE_MIN} мин, tmux-сессии нет. Запустить агента?" --task session-warden:no-agent || say "и сигнал не ушёл"
                WARDEN_RC=1
            fi
        fi
    elif [ -n "$WAITING" ]; then
        # Работы нет, но очередь не пуста — вся она ждёт владельца. Агента не
        # трогаем (будить нечем), а тишина не должна стать вечной: раз в
        # BLOCKED_TELL_GAP_MIN напоминаем тому, от кого зависит движение.
        TOLD="$LOG_DIR/blocked-queue.told"
        AGE_MIN=""
        [ -f "$TOLD" ] && AGE_MIN=$(( ( $(date +%s) - $(stat -c '%Y' "$TOLD") ) / 60 ))
        # Второй признак: агент ПРОСТАИВАЕТ. «Очередь целиком ждёт владельца»
        # истинно и когда смена занята работой, пришедшей сообщением в канал, —
        # а её в карте очереди нет. В ночь на 11.09 смена работала всю ночь, и
        # владелец в 01:20 получил «работы, которую я могу делать сам, нет».
        # Занятому агенту сигнал не нужен: упрётся — скажет сам.
        BUSY_MIN=0
        [ -f "$TRANSCRIPT" ] && BUSY_MIN="${JUDGE_WORK_MIN:-0}"
        if [ "$BUSY_MIN" -lt "${SILENCE_MAX_MIN:-30}" ]; then
            say "работы для смены нет, всё за блокерами, но агент работает (тишина ${BUSY_MIN} мин < ${SILENCE_MAX_MIN:-30}) — владельца не трогаю"
        elif подавлен_кулдауном "$AGE_MIN" "${BLOCKED_TELL_GAP_MIN:-720}"; then
            say "работы для смены нет, всё за блокерами; сказано $AGE_MIN мин назад — молчу"
        elif tg_send "Работы, которую я могу делать сам, в очереди нет — всё стоит за блокерами: $WAITING. Как блокер снимется, продолжу сам."; then
            date +%s > "$TOLD"
            say "работы для смены нет, всё за блокерами ($WAITING) — сказал владельцу"
        else
            say "работы для смены нет, и сигнал об этом не ушёл"
            WARDEN_RC=1
        fi
    fi
else
    say "dev-map.yaml нет — очередь проверять не по чему (продукт ещё не начат)"
fi
# Одно состояние на весь обход: пульс и лимитная ветка читают его, а не
# пересчитывают. Без карты и на паузе WORK не задан — прежнее поведение.
BLOCKED_IDLE=0
if [ -f "$TRANSCRIPT" ] && ! helpers_present && blocked_idle "${WORK:-1}" "${WAITING:-}" \
       "$(owner_last_word_epoch)" "$(epoch_from "$LOG_DIR/last_report")" \
       "$(epoch_from "$LOG_DIR/turn-end.stamp")" "$(last_answer_epoch "$TRANSCRIPT")"; then
    BLOCKED_IDLE=1
fi

# Карточки в работе (wip) активной линии: id через запятую. Пусто — карты нет или
# прибор не ответил; текст статуса тогда называет очередь числом.
wip_cards() {
    python3 - "$PROJECT_DIR/dev-map.yaml" "$PROJECT_DIR/scripts/work-queue.py" 2>/dev/null <<'PY' || true
import importlib.util, sys, yaml
spec = importlib.util.spec_from_file_location("work_queue", sys.argv[2])
queue = importlib.util.module_from_spec(spec)
spec.loader.exec_module(queue)
data = yaml.safe_load(open(sys.argv[1], encoding="utf-8")) or {}
line = queue.активное_направление()
print(", ".join(t["id"] for ln in data.get("lines") or [] if not line or ln.get("id") == line
                for t in ln.get("tasks") or [] if t.get("status") == "wip"))
PY
}

# Статус владельцу от самого сторожа, когда пинок пульса не уходит (смена
# простаивает, а работа в очереди): пинок будит ту, что молчит, но владелец от
# этого ничего не слышит. Одна запись журнала на обход: либо статус, либо причина молчания.
owner_status_pass() {  # $1=мин с работы главной $2=мин без отчёта
    local idle="$1" report="$2" mark="$LOG_DIR/pulse.auto" age="" why="" cards step="" first
    local period="${WARDEN_PERIOD_MIN:-10}" limit="${PULSE_MAX_MIN:-30}"
    [ -f "$mark" ] && age=$(( ( $(date +%s) - $(stat -c '%Y' "$mark") ) / 60 ))
    if [ "${WORK:-0}" -le 0 ]; then why="работы нет"
    elif [ $(( report + period )) -le "$limit" ]; then why="отчёт свежий ${report} мин"
    elif [ "$LIMIT_ACTIVE" = 1 ]; then why="$(limit_until_text)"
    elif [ "${BLOCKED_IDLE:-0}" = 1 ]; then why="смена ждёт владельца"
    elif [ "$idle" -lt "${SILENCE_MAX_MIN:-30}" ] || helpers_present; then why="смена работает"
    elif подавлен_кулдауном "$age" "$limit"; then why="статус сторожа был ${age} мин назад"
    fi
    if [ -n "$why" ]; then say "пульс: молчу — $why"; return 0; fi
    cards=$(wip_cards)
    for first in ${cards//,/ }; do
        step=$(grep -v '^[[:space:]]*$' "$PROJECT_DIR/.tasks/$first/журнал.md" 2>/dev/null | tail -1 | cut -c1-300) || true  # нет журнала — не повод ронять обход
        [ -z "$step" ] || break
    done
    date +%s > "$mark"
    say "пульс: статус владельцу — работа ${WORK}, отчёта нет ${report} мин, смена простаивает ${idle} мин"
    jlog "pulse_auto" "${SESSION_ID:-}" "статус сторожа: отчёта нет ${report} мин, смена простаивает ${idle} мин"
    tg_send "Статус от сторожа: смена молчит — простаивает ${idle} мин. В работе: ${cards:-очередь, задач $WORK}. Помощников: ${JUDGE_HELPERS:-0}. Последний шаг: ${step:-журнала нет}." --не-досылать \
        || say "статус владельцу не ушёл"
}

# ── 6в. Пульс отчётности: работа идёт, а владелец не слышит ────────────────
# Владелец 11.09.2026: «мне нужна ёмкая, лаконичная, но регулярная отчетность,
# как пульс по регулярности, и контроль тоже должен быть системный».
# Метку ставит tg_send при каждой отправке ИЗ СЕССИИ (демоны её не ставят) —
# регулярность перестаёт держаться моей памятью. Порог — число самого владельца от 21.08.2026: «Пиши статусы в
# процессе работы», молчание дольше получаса он назвал отказом.
PULSE_MARK="$LOG_DIR/last_report"
PULSE_MAX_MIN="${PULSE_MAX_MIN:-30}"
# Через сколько минут молчания смены сказать САМОМУ ВЛАДЕЛЬЦУ (порог — данные).
PULSE_OWNER_MIN="${PULSE_OWNER_MIN:-60}"
if [ "$WORK_PAUSED" = 0 ] && tmux has-session -t "$TMUX_SESSION" 2>/dev/null \
   && [ -f "$TRANSCRIPT" ]; then
    WORK_AGE_MIN="${JUDGE_WORK_MIN:-0}"
    if [ -f "$PULSE_MARK" ]; then
        REPORT_AGE_MIN=$(( ( $(date +%s) - $(stat -c '%Y' "$PULSE_MARK") ) / 60 ))
    else
        REPORT_AGE_MIN=9999
    fi
    # Работает = ответ главной или живого помощника моложе порога тишины. Живой
    # помощник — работа сам по себе, даже если его последний ответ старше порога
    # тишины. Молчащему агенту пинок про отчёт не нужен: его будят другие ветки.
    PULSE_WORK_AGE="$WORK_AGE_MIN"
    ! helpers_present || PULSE_WORK_AGE=0
    PULSE_VERDICT=$(pulse_verdict "$PULSE_WORK_AGE" "$REPORT_AGE_MIN" "$BLOCKED_IDLE")
    if [ "$PULSE_VERDICT" = пинок ] && [ "$LIMIT_ACTIVE" = 1 ]; then
        say "пульс: молчу — $(limit_until_text)"
        PULSE_VERDICT=молчу
    elif [ "$PULSE_VERDICT" = молчу ]; then
        owner_status_pass "$WORK_AGE_MIN" "$REPORT_AGE_MIN"
    fi
    if [ "$PULSE_VERDICT" = пинок ]; then
        PULSE_KICK="$LOG_DIR/pulse.kick"
        KICK_AGE=""
        [ -f "$PULSE_KICK" ] && KICK_AGE=$(( ( $(date +%s) - $(stat -c '%Y' "$PULSE_KICK") ) / 60 ))
        # Доставка статуса проверяется ДО кулдауна пульса: иначе PULSE_MAX_MIN
        # глушит ровно тот обход, где пинок остался без ответа.
        if helpers_present && [ -n "$KICK_AGE" ] \
           && [ "$KICK_AGE" -ge "${KICK_ANSWER_WAIT_MIN:-5}" ] \
           && [ "$(stat -c '%Y' "$PULSE_MARK" 2>/dev/null || echo 0)" -le "$(stat -c '%Y' "$PULSE_KICK")" ]; then
            PULSE_UNANSWERED_MARK="$LOG_DIR/pulse.owner"
            UNANSWERED_AGE=""
            [ -f "$PULSE_UNANSWERED_MARK" ] && UNANSWERED_AGE=$(( ( $(date +%s) - $(stat -c '%Y' "$PULSE_UNANSWERED_MARK") ) / 60 ))
            if подавлен_кулдауном "$UNANSWERED_AGE" "${PULSE_OWNER_MIN:-60}"; then
                say "пульс: статус на пинок не пришёл $KICK_AGE мин, владельцу уже говорили $UNANSWERED_AGE мин назад — жду"
            else
                date +%s > "$PULSE_UNANSWERED_MARK"
                jlog "pulse_unanswered" "$SESSION_ID" "статус на пинок не пришёл $KICK_AGE мин; работают помощники: $JUDGE_HELPERS"
                tg_send "Смена не ответила на запрос статуса ${KICK_AGE} мин. Работают помощники: ${JUDGE_HELPERS} — $(judge_helpers_text весть). Работа не стоит." --не-досылать \
                    || say "о неотвеченном запросе статуса владельцу сказать не удалось"
            fi
        fi
        if подавлен_кулдауном "$KICK_AGE" "$PULSE_MAX_MIN"; then
            say "пульс: отчёта нет ${REPORT_AGE_MIN} мин, но пинок был $KICK_AGE мин назад — жду"
        else
            date +%s > "$PULSE_KICK"
            say "пульс: работа идёт (${WORK_AGE_MIN} мин), а отчёта владельцу нет ${REPORT_AGE_MIN} мин — прошу статус"
            if helpers_present; then
                jlog "pulse_kick" "$SESSION_ID" "отчёта нет ${REPORT_AGE_MIN} мин при идущей работе; работают помощники: $JUDGE_HELPERS"
                PULSE_TEXT="[сторож сессий] Владельцу нет отчёта ${REPORT_AGE_MIN} мин. Работают помощники: $(judge_helpers_text пинок). Дай статус командой bash scripts/tg_send.sh --статус. Новых помощников ради отчёта не запускай."
            else
                jlog "pulse_kick" "$SESSION_ID" "отчёта нет ${REPORT_AGE_MIN} мин при идущей работе"
                PULSE_TEXT="[сторож сессий] Владельцу нет отчёта ${REPORT_AGE_MIN} минут, а работа идёт. Дай статус командой bash scripts/tg_send.sh --статус. Без разбора своих действий — он идёт в журнал."
            fi
            agent_prompt "$PULSE_TEXT" \
                || say "пинок про пульс не ушёл (в панели: $(pane_cmd))"
            # Пинки не помогли — сказать ВЛАДЕЛЬЦУ. Улика 12.09.2026: агент
            # работал и не отчитывался 180 минут, сторож честно пинал его
            # восемнадцать раз подряд — и ни разу не сказал владельцу. Тот
            # остался гадать и решил, что кончился лимит подписки. Сигнал,
            # который идёт только виновнику, владельца не бережёт.
            сказать_владельцу_о_молчании "$REPORT_AGE_MIN" "$WORK_AGE_MIN"
        fi
    fi
elif [ "$WORK_PAUSED" = 1 ]; then
    say "пульс: молчу — пауза"
fi

# ── 6б. Лимит подписки: сказать владельцу и поднять работу самим ───────────
# Задача владельца 11.09.2026. Прежде этого не было вовсе: сторож пинал агента
# ТОЛЬКО при непустой незаблокированной очереди, а при исчерпанном лимите
# очередь обычно уже стоит — будить было некому, и смена молча умирала до
# прихода владельца.
# Механика намеренно простая: пока агент нем — повторять пинок. Лимит кончится
# сам, очередной пинок пройдёт, работа продолжится. Это лечит не только лимит,
# а любую немоту сессии, и не требует угадывать чужой текст.
# Имя метки знает ОДИН судья (scripts/limit_mark.py), здесь его нет.
MARK="python3 $PROJECT_DIR/scripts/limit_mark.py"
LIMIT_STALL_MIN="${LIMIT_STALL_MIN:-20}"
LIMIT_RETRY_MIN="${LIMIT_RETRY_MIN:-10}"
# Предохранитель: при НЕИЗВЕСТНОМ сроке сброса дольше этого сторож не молчит.
LIMIT_KICK_MAX_MIN="${LIMIT_KICK_MAX_MIN:-60}"
if [ "$WORK_PAUSED" = 0 ] && tmux has-session -t "$TMUX_SESSION" 2>/dev/null \
   && [ -f "$TRANSCRIPT" ]; then
    # Немота = работа_мин судьи (главная ИЛИ живой помощник); судья не ответил —
    # judge_work уже свёл её к главной или к возрасту файла: хуже, чем судья, но
    # лучше слепоты.
    STALL_MIN="${JUDGE_WORK_MIN:-0}"
    PANE_NOW=$(tmux capture-pane -p -t "$TMUX_SESSION" 2>/dev/null || true)
    LIMIT_SEEN=0
    признак_лимита_в "$PANE_NOW" && LIMIT_SEEN=1
    # Журнал сессии важнее экрана: 429 — факт, экранный текст — догадка.
    # Свежая запись об отказе по лимиту (моложе порога немоты) означает лимит,
    # даже если панель показывает что угодно (улика 12.09.2026: 160 минут
    # лимита при «в панели claude — агент на месте»).
    # Лимит ДЕЙСТВУЕТ — по единому судье (limit_active, один раз за обход):
    # отказ 429, заметка CLI или метка limit-watch. Иначе прошедший лимит
    # поднял бы тревогу владельцу на ровном месте, а лимит, названный только
    # заметкой (за десятки минут до первого 429), не был бы доказан вовсе.
    # «Упёрся в лимит» владельцу говорят после машинного отказа (LIMIT_PROVEN):
    # заметка CLI без отказа лишь глушит пинки (LIMIT_ACTIVE).
    LIMIT_PROVEN=$LIMIT_REFUSED
    [ "$LIMIT_ACTIVE" != 1 ] || LIMIT_SEEN=1
    # Будим по НЕМОТЕ, а признак лимита нужен лишь для слов владельцу. Прежде
    # пинок был заперт за признаком лимита — текста CLI при исчерпании я не
    # наблюдал, и «работа поднимется сама» не выполнялось ни разу (задача
    # владельца 11.09: «после обновления лимитов автоматического запуска не
    # произошло»). Немота при живой панели — достаточное основание разбудить:
    # работающий агент пишет в транскрипт постоянно.
    # Двадцать минут немоты — порог для ДОГАДКИ по экрану: слово «limit» я и сам
    # печатаю в отчётах, и без немоты оно ничего не значит. Машинный отказ 429 в
    # журнале — не догадка, а факт, и ждать с ним нечего. Улика 12.09.2026:
    # владелец увидел лимит на экране, а сообщение от харнеса пришло через 20
    # минут — ровно этот порог плюс ожидание обхода. Для доказанного лимита
    # порог свой и короткий (LIMIT_SAY_MIN), пинки будят по-прежнему.
    if $MARK --стоит-ли; then MARKED=1; else MARKED=0; fi
    # Тихая метка «blocked» живёт, только пока повод тот же. Появилась работа
    # или признак лимита, а смена молчит, — о немоте и о лимите обязаны
    # сказать; со старой меткой решение дало бы лишь «пинок» без слова.
    if [ "$MARKED" = 1 ] \
       && [ "$(stall_reason "$LIMIT_SEEN" "$BLOCKED_IDLE")" != blocked ]; then
        MARK_REASON=$($MARK --повод 2>/dev/null) || MARK_REASON=""
        if [ "$MARK_REASON" = blocked ]; then
            $MARK --снять >/dev/null 2>&1 || true
            MARKED=0
            say "повод «blocked» кончился — тихую метку снял"
        fi
    fi
    # Свежий отказ: срок впереди (судья) либо, без срока, отказ моложе
    # LIMIT_FRESH_MIN — работа помощника после старого отказа без срока лимитом
    # уже не держится.
    if [ -n "$LIMIT_RESET" ] || свежий_отказ "$TRANSCRIPT"; then FRESH=1; else FRESH=0; fi
    VERDICT=$(решение_лимита "$STALL_MIN" "$LIMIT_PROVEN" "$LIMIT_SEEN" "$MARKED" "$FRESH")
    say "решение лимитной ветки: $VERDICT (немота ${STALL_MIN} мин, доказан ${LIMIT_PROVEN}, виден ${LIMIT_SEEN}, метка ${MARKED}, свежий отказ ${FRESH})"
    # Немота без признака лимита — в ДВА шага. Объявить «Работа встала» в том
    # же обходе, что и пинок, значит не дать смене ответить: 25.10.2026 ответ
    # пришёл через 3 секунды после объявления. Первый обход — только пинок и
    # метка stall.kick; владельцу говорим, если за KICK_ANSWER_WAIT_MIN ответа
    # (главной или помощника) не было и помощников нет. Метку гасит работа
    # после пинка (правило ниже), а не любая реплика.
    STALL_KICK="$LOG_DIR/stall.kick"
    STALL_KICK_FIRST=0
    STALL_KICK_AGE_SEC=""
    [ -f "$STALL_KICK" ] && STALL_KICK_AGE_SEC=$(( $(date +%s) - $(stat -c '%Y' "$STALL_KICK") ))
    # Ответ на пинок — реплика, а не работа: главная, которая ждёт вечно, отвечает
    # «Жду.» на каждый пинок, и по одному ответу немота гасилась бы навсегда.
    # Работой после пинка считаются отчёт владельцу новее метки или ответы,
    # продолжавшиеся дольше KICK_ANSWER_WAIT_MIN после неё. Голая реплика метку
    # пинка снимает, но запоминается: если смена снова замолчит в пределах часа
    # без отчёта, второй пинок немоты уже не ждёт — «Работа встала» уходит сразу.
    STALL_REPLIED="$LOG_DIR/stall.replied"
    REPORT_EPOCH=$(stat -c '%Y' "$PULSE_MARK" 2>/dev/null || echo 0)
    if [ -f "$STALL_REPLIED" ] && { [ "$REPORT_EPOCH" -gt "$(stat -c '%Y' "$STALL_REPLIED")" ] \
         || [ $(( $(date +%s) - $(stat -c '%Y' "$STALL_REPLIED") )) -ge $(( ${STALL_REPLY_MEMORY_MIN:-60} * 60 )) ]; }; then
        rm -f "$STALL_REPLIED"
    fi
    if [ -n "$STALL_KICK_AGE_SEC" ]; then
        if [ "$REPORT_EPOCH" -gt "$(stat -c '%Y' "$STALL_KICK")" ] \
           || [ $(( JUDGE_WORK_SEC + ${KICK_ANSWER_WAIT_MIN:-5} * 60 )) -lt "$STALL_KICK_AGE_SEC" ]; then
            rm -f "$STALL_KICK" "$STALL_REPLIED"; STALL_KICK_AGE_SEC=""
        elif [ "$JUDGE_WORK_SEC" -lt "$STALL_KICK_AGE_SEC" ] || [ "$VERDICT" != "объявить-немоту" ]; then
            rm -f "$STALL_KICK"; STALL_KICK_AGE_SEC=""
            date +%s > "$STALL_REPLIED"
        fi
    fi
    if [ "$(stall_reason "$LIMIT_SEEN" "$BLOCKED_IDLE")" != nemota ]; then
        rm -f "$STALL_KICK" "$STALL_REPLIED"
    elif [ "$VERDICT" = "объявить-немоту" ]; then
        if [ -z "$STALL_KICK_AGE_SEC" ] && [ ! -f "$STALL_REPLIED" ]; then
            STALL_KICK_FIRST=1
            VERDICT="пинок"
            say "немота ${STALL_MIN} мин: сначала пинок; владельцу скажу, если ответа не будет ${KICK_ANSWER_WAIT_MIN:-5} мин"
        elif [ -z "$STALL_KICK_AGE_SEC" ]; then
            rm -f "$STALL_REPLIED"
            say "немота ${STALL_MIN} мин после ответа на прошлый пинок без отчёта — объявляю сразу"
        elif [ "$STALL_KICK_AGE_SEC" -lt $(( ${KICK_ANSWER_WAIT_MIN:-5} * 60 )) ] || helpers_present; then
            VERDICT="пинок"
            say "немота ${STALL_MIN} мин: пинок был ${STALL_KICK_AGE_SEC} с назад — жду ответа"
        else
            rm -f "$STALL_KICK"
        fi
    fi
    if [ "$VERDICT" = "объявить-лимит" ] || [ "$VERDICT" = "объявить-немоту" ] \
       || [ "$VERDICT" = "пинок" ]; then
        if [ "$VERDICT" != "пинок" ]; then
            # В метке второе поле — ПОВОД. Без него сообщение о возобновлении
            # говорило «Лимит обновился» и тогда, когда метку ставила немота
            # без единого признака лимита: владелец 14.09.2026 получил «лимит
            # обновился», хотя лимита не было вовсе, и написал «Хотя лимитов
            # не было никаких».
            POVOD=$(stall_reason "$LIMIT_SEEN" "$BLOCKED_IDLE")
            # Формат метки знает ОДИН судья (scripts/limit_mark.py): 27.09.2026
            # это знание жило в двух сторожах сразу, и ежеминутный писал одно
            # поле вместо двух — повод терялся, а владелец получал «признака
            # лимита не было» сразу после «упёрся в лимит».
            #
            # Отказ судьи НЕ гасится: без метки сторож скажет владельцу то же
            # самое на следующем обходе, и так каждые десять минут (ревью
            # 27.09, F-lim-01).
            # Под set -e отказ судьи иначе ронял бы весь обход.
            POSTAVLENO=0
            # Час обновления ложится В МЕТКУ числом: слова о лимите собирает
            # её судья, поэтому у двух сторожей не бывает двух разных первых
            # сообщений (владелец 17.10.2026 получил версию БЕЗ времени — её
            # слал ежеминутный сторож, проснувшийся раньше).
            python3 "$PROJECT_DIR/scripts/limit_mark.py" --поставить "$POVOD" ${LIMIT_RESET:+--сброс "$LIMIT_RESET"} || POSTAVLENO=$?
            if [ "$POSTAVLENO" -ne 0 ]; then
                # Не return: здесь не функция, и выход из скрипта оборвал бы
                # пинок ниже. Просто молчим владельцу.
                say "метку остановки поставить не вышло (код $POSTAVLENO) — владельцу не пишу"
            elif [ "$POVOD" = blocked ]; then
                say "тишина ${STALL_MIN} мин: работы нет, смена у приглашения — метка «blocked», владельцу не пишу"
            elif [ "$LIMIT_SEEN" = 1 ]; then
                jlog "limit_reached" "$SESSION_ID" "панель: $(строка_лимита_в "$PANE_NOW"); немота ${STALL_MIN} мин; сброс: ${LIMIT_RESET:-неизвестен}"
                # Время сброса ищется в панели, а если её строка его не
                # назвала — в ЖУРНАЛЕ: там оно лежит числом. Прежде владелец
                # получал «времени сброса CLI не назвал» всякий раз, когда лимит
                # доказан отказом 429 (его слова 27.09.2026: «эта информация
                # пропала»).
                # Слова — у судьи метки: там лежит час обновления, и там же
                # он превращается в 24-часовое время. Владелец 17.10.2026:
                # «одно сообщение - упёрся в лимит подписки, лимит обновится в
                # 15:10, после обновления продолжу». Прежде здесь была ВТОРАЯ
                # формулировка того же — с признаком отказа и часом из чужой
                # строки панели.
                VEST_O_LIMITE=$(python3 "$PROJECT_DIR/scripts/limit_mark.py" --весть-о-лимите 2>/dev/null) \
                    || VEST_O_LIMITE="Упёрся в лимит подписки. Скажу, как только работа пойдёт."
                tg_send "$VEST_O_LIMITE" --несмотря-на-лимит \
                    || say "о лимите сказать не удалось"
            else
                jlog "agent_stalled" "$SESSION_ID" "немота ${STALL_MIN} мин, признака лимита на панели нет"
                tg_send "Работа встала: агент молчит ${STALL_MIN} минут. Признака лимита на экране не видно, причина пока не названа. Бужу сам каждые ${LIMIT_RETRY_MIN} минут — если дело в лимите, смена поднимется, как только он обновится." \
                    || say "о немоте сказать не удалось"
            fi
        fi
        # Пинок с редким шагом: пока лимит держится, он не пройдёт, но и не
        # стоит ничего. Как только лимит обновится, ближайший пинок оживит смену.
        LIMIT_KICK="$LOG_DIR/лимит-подписки.пинок"
        KICK_AGE=""
        [ -f "$LIMIT_KICK" ] && KICK_AGE=$(( ( $(date +%s) - $(stat -c '%Y' "$LIMIT_KICK") ) / 60 ))
        # Будить НЕЧЕМ, когда работы нет: прибор очереди (ветка 6 выше) уже
        # посчитал, что вся очередь ждёт решения владельца. Смене в этом
        # состоянии нечего продолжать, а каждый пинок — полный шаг агента со
        # всем накопленным контекстом. 26.09.2026 таких пинков пришло три
        # подряд, и все три получили честный ответ «стою, жду его слова».
        # Тот же довод уже записан в ветке 6: «Агента не трогаем (будить нечем)».
        if ! budit_smenu "${WORK:-1}" "${WAITING:-}"; then
            say "тишина ${STALL_MIN} мин, но работы нет — всё за блокерами: смену не бужу"
        elif глушить_пинок "$LIMIT_ACTIVE" "$LIMIT_WAKE" "${KICK_AGE:-$STALL_MIN}"; then
            # Срок назван — до подъёма (сброс + LIMIT_KICK_DELAY_SEC) в панель
            # ни слова: пинок заведомо не пройдёт и стоит смене нового отказа.
            # Срок неизвестен — молчим не дольше LIMIT_KICK_MAX_MIN.
            say "$(limit_until_text) — пинка не трачу"
        elif подавлен_кулдауном "$KICK_AGE" "$LIMIT_RETRY_MIN"; then
            say "лимит подписки держится (тишина ${STALL_MIN} мин), пинок был $KICK_AGE мин назад — жду"
        else
            date +%s > "$LIMIT_KICK"
            say "лимит подписки: тишина ${STALL_MIN} мин — пробую разбудить смену"
            # Текст по ПРИЗНАКУ, а не по имени ветки: признака лимита нет —
            # значит и говорить о нём нечего. Владелец 14.09.2026 уже ловил
            # харнес на «лимит обновился» без лимита: «Хотя лимитов не было
            # никаких». Смене такое сообщение стоит того же — она идёт искать
            # лимит, которого не было.
            if [ "$LIMIT_SEEN" = 1 ]; then
                KICK_TEXT_LIMIT="[сторож сессий] Если лимит подписки обновился — продолжай работу с того места, где остановился: сверься с STATE.md и docs/handover/, проверь \$LOG_DIR/inbox/ и скажи владельцу, что работа возобновилась."
            else
                KICK_TEXT_LIMIT="[сторож сессий] Работы не видно ${STALL_MIN} мин, признака лимита нет. Продолжай текущий шаг: сверься с STATE.md и docs/handover/, проверь \$LOG_DIR/inbox/. Если стоишь по причине — назови её владельцу."
            fi
            # Метка пинка немоты ставится ДО отправки (ответ, пришедший за время
            # отправки, должен считаться новее метки) и снимается, если пинок не
            # ушёл: иначе через KICK_ANSWER_WAIT_MIN объявилась бы немота без
            # попытки разбудить смену.
            [ "$STALL_KICK_FIRST" != 1 ] || date +%s > "$STALL_KICK"
            if ! agent_prompt "$KICK_TEXT_LIMIT"; then
                [ "$STALL_KICK_FIRST" != 1 ] || rm -f "$STALL_KICK"
                say "пинок не ушёл (в панели: $(pane_cmd))"
            fi
        fi
    elif [ "$VERDICT" = "возобновление" ]; then
        # Смена ожила: транскрипт снова растёт И свежего отказа в нём больше
        # нет. Второе условие обязательно: сессия, стоящая в лимите, сама
        # дописывает в журнал записи об отказе — по одной «живости» сторож
        # объявлял возобновление, пока работа стояла, и владелец получал цикл
        # «встала → возобновилась» (его слова 13.09.2026: «Зачем мне этот
        # спам»). Ежеминутный limit-watch.sh чинён тем же условием; здесь была
        # ВТОРАЯ копия того же суждения, и она бы врала дальше.
        # Метку читает, снимает и облекает в слова тот же судья, что её ставил.
        SNYATO=$(python3 "$PROJECT_DIR/scripts/limit_mark.py" --снять --транскрипт "$TRANSCRIPT" 2>/dev/null) || SNYATO=""
        # Пусто — метки не было или судья не ответил. Своей вести здесь нет:
        # четвёртая формулировка вне судьи это четвёртый источник правды, а
        # «возобновилась» без метки — дубль с ложным «0 мин» (ревью 27.09).
        if [ -z "$SNYATO" ]; then
            say "метку снять не вышло или её не было — о возобновлении молчу"
        else
        DOWN_MIN=$(printf '%s' "$SNYATO" | cut -f1)
        POVOD=$(printf '%s' "$SNYATO" | cut -f2)
        VEST=$(printf '%s' "$SNYATO" | cut -f3)
        jlog "limit_cleared" "$SESSION_ID" "работа возобновилась (повод ${POVOD:-неизвестен}), простой ${DOWN_MIN:-?} мин"
        say "работа возобновилась после ${DOWN_MIN:-?} мин простоя (повод ${POVOD:-неизвестен})"
        # Пустая весть — метка устарела (её ставила уже другая смена) или
        # смена ждала владельца: ни то, ни другое не новость для него.
        if [ -z "$VEST" ]; then
            say "весть пуста (повод ${POVOD:-неизвестен}, простой ${DOWN_MIN:-?} мин) — владельцу не пишу"
        else
        tg_send "$VEST Продолжаю с того места, где остановился." \
            || say "о возобновлении сказать не удалось"
        fi
        fi
    fi
fi

# Потолок повторов толчка о сообщении на один файл: сессия, трижды получившая
# толчок и не взявшая файл, не возьмёт его и в четвёртый — дальше нужен человек.
INBOX_KICK_CEILING=3

# Уборка 6а: на КАЖДОМ круге и при любом числе входящих, до толчка.
# Живёт отдельно от толчка потому, что файл обычно берут, когда толчку уже нечего
# делать (входящие пусты): внутри толчка задача модели
# «сессия не берёт сообщение» висела бы открытой до следующего толчка.
inbox_cleanup_step() {
    local state="$LOG_DIR/kick-state" counter counter_name
    mkdir -p "$state"
    for counter in "$state"/repeat-*; do
        [ -e "$counter" ] || continue
        counter_name="${counter##*/repeat-}"; counter_name="${counter_name%.told}"
        [ -e "$INBOX_DIR/$counter_name" ] && continue
        # Сигнал о потолке уходил (есть .told) — задача модели закрывается зелёным.
        case "$counter" in *.told) ! declare -F alert_task >/dev/null || alert_task --resolve session-warden:inbox-stuck ;; esac
        rm -f "$counter"
    done
    # Метка «отдано» живёт, пока лежит её файл: взятый сессией файл уходит в
    # обработано/, и метка ему больше не нужна.
    for counter in "$state"/sent-*; do
        [ -e "$counter" ] || continue
        [ -e "$INBOX_DIR/${counter##*/sent-}.txt" ] || rm -f "$counter"
    done
    # Пустые входящие: причина прошлого отказа снимается, иначе второй эпизод
    # паузы промолчит о «смену не бужу».
    if [ -z "$(find "$INBOX_DIR" -maxdepth 1 -type f -print -quit 2>/dev/null)" ]; then
        rm -f "$state/inbox-refusal"
    fi
}

# Законный отказ двери (пауза, ротация, лимит) — одна строка на СМЕНЕ причины,
# без сигнала владельцу.
inbox_say_refusal() {  # причина
    local mark="$LOG_DIR/kick-state/inbox-refusal"
    [ "$(cat "$mark" 2>/dev/null)" = "$1" ] && return 0
    say "$1: $INBOX_N сообщений ждут в inbox, смену не бужу"
    printf '%s' "$1" > "$mark"
}

# Один раз на файл: сторож толкнул сессию потолок раз, она файл не берёт — дальше
# нужен человек. Метка «сказано» только при настоящей отправке: весть, придержанная
# дверью канала, не ушла.
inbox_signal_stuck() {  # имя файла, его время (эпоха)
    local told="$LOG_DIR/kick-state/repeat-$1.told" hhmm
    [ -e "$told" ] && return 0
    hhmm=$(date -d "@$2" +%H:%M)
    say "файл $hhmm на потолке повторов, не толкаю"
    tg_send "Сообщение от $hhmm: толкнул сессию $INBOX_KICK_CEILING раза, она его не берёт — оно лежит во входящих." --task session-warden:inbox-stuck \
        && [ "$TG_SEND_HELD" = 0 ] && : > "$told"
    return 0
}

# Шаг толчка ветки 6а. Дверь спрашивается ПЕРВОЙ: на паузе, в ротации и в лимите
# ни потолок, ни сигнал не судятся — пауза СТОП, а придержанный сигнал пропал бы.
# Потолок — на файл, не на очередь: застрявшие сигналят и в выборку толчка не идут.
inbox_kick_step() {
    local state="$LOG_DIR/kick-state" reason line name epoch count target="" target_count=0
    reason=$(pane_gate_owner)
    if [ -n "$reason" ]; then
        inbox_say_refusal "$reason"
        return 0
    fi
    rm -f "$state/inbox-refusal"
    while IFS= read -r line; do
        name="${line#* }"; epoch="${line%%.*}"
        count=$(cat "$state/repeat-$name" 2>/dev/null || echo 0)
        [[ "$count" =~ ^[0-9]+$ ]] || count=0
        if [ "$count" -ge "$INBOX_KICK_CEILING" ]; then
            inbox_signal_stuck "$name" "$epoch"
        elif [ -z "$target" ]; then
            target="$name"; target_count="$count"
        fi
    done < <(find "$INBOX_DIR" -maxdepth 1 -type f -mmin +2 -printf '%T@ %f\n' 2>/dev/null | sort -n)
    [ -n "$target" ] || return 0
    if pane_kick_owner "В $INBOX_DIR лежат $INBOX_N сообщений владельца — свод одной командой: python3 scripts/inbox-digest.py; прочитанное перенеси в $INBOX_DIR/обработано/."; then
        echo $((target_count + 1)) > "$state/repeat-$target"
        say "в inbox $INBOX_N необработанных сообщений владельца — пинок в tmux (толчок $((target_count + 1)) из $INBOX_KICK_CEILING)"
        jlog "inbox_kick" "$SESSION_ID" "необработанных: $INBOX_N"
        return 0
    fi
    reason="${PANE_REFUSAL%%:*}"
    case "$reason" in
        пауза|ротация|лимит) inbox_say_refusal "$reason" ;;
        *)
            if tmux has-session -t "$TMUX_SESSION" 2>/dev/null; then
                tg_send "У меня $INBOX_N ваших сообщений в inbox, но в tmux-панели не claude — агент выпал в оболочку. Поднимаю смену сейчас же, ответ будет от неё." --task session-warden:no-agent || say "и сигнал не ушёл"
            else
                say "tmux-сессии нет — входящие некому отдать, сигнал владельцу"
                tg_send "У меня $INBOX_N ваших сообщений в очереди, но сессия агента не запущена." --task session-warden:no-agent || say "и сигнал не ушёл"
            fi
            WARDEN_RC=1 ;;
    esac
}

# ── 6д. Скорость: недобор задач в работе — пинок, переизбыток — совет ───────
# Режим считает судья speed_mode.py; сторож только доносит его слово основной
# сессии. Ветка последняя из толкающих: пульс, лимит и входящие важнее недобора,
# а второй толчок в тот же проход мешал бы им дойти.
speed_judge_cfg() {  # число из блока «сторож» данных судьи
    python3 - "$PROJECT_DIR/harness/demons" "$1" 2>/dev/null <<'PY' || true
import sys
sys.path.insert(0, sys.argv[1])
import speed_mode
print(speed_mode.load_data()["сторож"][sys.argv[2]])
PY
}

# Пинок не отвечен, если задач в работе не прибавилось к следующему пинку; после
# нескольких подряд смена не берёт задачи сама — тогда слово владельцу.
speed_escalate() {  # в_работе, режим
    local work="$1" mode="$2" state="$LOG_DIR/speed.unanswered" prev_work="$LOG_DIR/speed.kick.work"
    local count=0 after gap owner="$LOG_DIR/speed.owner" age=""
    [ -f "$prev_work" ] && [ "$work" -le "$(cat "$prev_work" 2>/dev/null || echo 999999)" ] \
        && count=$(( $(cat "$state" 2>/dev/null || echo 0) + 1 ))
    echo "$count" > "$state"
    echo "$work" > "$prev_work"
    after=$(speed_judge_cfg эскалация_после_пинков)
    gap=$(speed_judge_cfg эскалация_не_чаще_мин)
    [[ "$after" =~ ^[0-9]+$ && "$gap" =~ ^[0-9]+$ ]] || return 0
    [ "$count" -ge "$after" ] || return 0
    [ -f "$owner" ] && age=$(( ( $(date +%s) - $(stat -c '%Y' "$owner") ) / 60 ))
    if подавлен_кулдауном "$age" "$gap"; then return 0; fi
    tg_send "Сторож $after раза просил взять задачи — в работе $work при режиме $mode. Смена не берёт, смотрю почему." \
        --task session-warden:speed-unanswered && date +%s > "$owner" \
        || say "скорость: слово владельцу о непринятых пинках не ушло"
}

speed_kick_step() {
    local judge="$PROJECT_DIR/harness/demons/speed_mode.py" kick="$LOG_DIR/speed.kick" over="$LOG_DIR/speed.over"
    local last_kick=0 last_over=0 verdict rc=0 kind count take shown line1 work mode text
    if [ "${TMUX_KICKED:-0}" = 1 ]; then say "скорость: молчу — в этом проходе уже был пинок"; return 0; fi
    if [ "${OWNER_WAITING:-0}" = 1 ]; then say "скорость: молчу — во входящих слово владельца"; return 0; fi
    [ -f "$kick" ] && last_kick=$(stat -c '%Y' "$kick")
    [ -f "$over" ] && last_over=$(stat -c '%Y' "$over")
    verdict=$(python3 "$judge" --сторожу --последний-пинок "$last_kick" --последнее-лишнее "$last_over" 2>&1) || rc=$?
    if [ "$rc" != 0 ]; then say "скорость: судья не ответил (код $rc): $verdict"; return 0; fi
    IFS=$'\t' read -r kind count take <<<"$verdict"
    case "$kind" in
        недобор|лишнее) ;;
        ровно) rm -f "$LOG_DIR/speed.unanswered"; say "скорость: ровно"; alert_task --resolve session-warden:speed-unanswered; return 0 ;;
        *) say "скорость: $verdict"; return 0 ;;
    esac
    shown=$(python3 "$judge" --показать --коротко 2>/dev/null) || { say "скорость: слов судьи нет, пинок не шлю"; return 0; }
    line1=$(sed -n 1p <<<"$shown")
    if [ "$kind" = лишнее ]; then
        rm -f "$LOG_DIR/speed.unanswered"
        alert_task --resolve session-warden:speed-unanswered
        text="[сторож скорости] $line1 Лишних задач в работе: $count. Новых задач не бери, начатые доводи."
        if agent_prompt "$text"; then
            date +%s > "$over"
            say "скорость: в работе больше режима на $count — совет в tmux"
            jlog "speed_over" "$SESSION_ID" "лишних задач: $count"
            HARNESS_LOG_DIR="$LOG_DIR" harness_event режим-скорости harness/demons/session-warden.sh speed.over ok "лишних=$count"
        else
            say "скорость: совет про лишнее не ушёл (в панели: $(pane_cmd))"
        fi
        return 0
    fi
    work=$(sed -n 's/^В работе \([0-9][0-9]*\).*/\1/p' <<<"$shown")
    mode=$(sed -n 's/^Режим «[^»]*»: \([0-9][0-9]*\) .*/\1/p' <<<"$shown")
    text="[сторож скорости] $line1 $(sed -n 2p <<<"$shown") Возьми ещё $count: ${take// /, } — на каждую оркестратора или одного помощника. В промпте метка «Часть: <id карточки>#1» (именно id из карты, не имя каталога), без неё задача не засчитается. Заблокирована — бери следующую по python3 scripts/work-queue.py dev-map.yaml --порядок."
    if agent_prompt "$text"; then
        date +%s > "$kick"
        say "скорость: недобор, прошу взять $count: $take"
        jlog "speed_kick" "$SESSION_ID" "добор $count: $take"
        HARNESS_LOG_DIR="$LOG_DIR" harness_event режим-скорости harness/demons/session-warden.sh speed.kick ok "добор=$count" "задачи=$take" "в_работе=${work:-?}"
        [[ "$work" =~ ^[0-9]+$ ]] && speed_escalate "$work" "${mode:-?}"
    else
        say "скорость: пинок про недобор не ушёл (в панели: $(pane_cmd))"
    fi
    return 0
}

# ── 6а. Входящие владельца: непустой inbox не должен лежать молча ───────────
# Диспетчер складывает сообщения владельца в $LOG_DIR/inbox/ файлами; агент
# переносит прочитанное в inbox/обработано/. Свежий необработанный файл старше
# пары минут — пинок в сессию: сообщение владельца не имеет права ждать.
INBOX_DIR="$LOG_DIR/inbox"
OWNER_WAITING=0   # латиницей намеренно: кириллица в имени переменной bash запрещена
if [ -d "$INBOX_DIR" ]; then
    inbox_cleanup_step
    INBOX_N=$(find "$INBOX_DIR" -maxdepth 1 -type f -mmin +2 2>/dev/null | wc -l | tr -d ' ')
    if [ "$INBOX_N" -gt 0 ]; then
        OWNER_WAITING=1
        inbox_kick_step
    fi
fi

# ── 6д. Скорость: последней из толкающих ───────────────────────────────────
speed_kick_step

# ── 6г. Кнопка панели «ревизия сейчас» ─────────────────────────────────────
knopka_revizii "$LOG_DIR/revizia/запуск" "$PROJECT_DIR/harness/demons/project-revision.sh"

# ── 6б. Агент выпал в оболочку — самостоятельное состояние ──────────────────
# Не «не смогли доставить», а «работать некому». Порядок: засечь время →
# уважить приаттаченного владельца → по порогу поднять агента той же командой,
# что и ротация (AGENT_START_CMD) → сказать владельцу, но не чаще кулдауна.
PANE_STATE="$LOG_DIR/agent-pane.since"
DEAD_STAMP="$LOG_DIR/agent-pane.told"
if tmux has-session -t "$TMUX_SESSION" 2>/dev/null; then
    PANE_NOW=$(pane_cmd)
    CLIENTS=$(tmux list-clients -t "$TMUX_SESSION" 2>/dev/null | grep -c . || true)
    # Часы «агента нет с» заводятся ДО решения. Пока их заводила только ветка
    # «ждём», приаттаченный клиент останавливал и часы: отсчёт начинался заново
    # после его отключения, и порог не наступал никогда.
    pane_is_agent "$PANE_NOW" || [ -s "$PANE_STATE" ] || date +%s > "$PANE_STATE"
    SINCE=0
    [ -f "$PANE_STATE" ] && SINCE=$(cat "$PANE_STATE" 2>/dev/null || echo 0)
    # Простой панели: tmux помнит время последней активности сессии. Живой
    # человек за клиентом её обновляет, забытый ssh-клиент — нет.
    PANE_ACTIVITY=$(tmux display-message -p -t "$TMUX_SESSION" '#{window_activity}' 2>/dev/null || echo 0)
    PANE_IDLE_MIN=$(( ( $(date +%s) - ${PANE_ACTIVITY:-0} ) / 60 ))
    [ "$PANE_IDLE_MIN" -lt 0 ] && PANE_IDLE_MIN=0
    case "$(решение_по_панели "$PANE_NOW" "${CLIENTS:-0}" "$SINCE" "$(date +%s)" "$PANE_IDLE_MIN" "$OWNER_WAITING")" in
        ok)
            [ -f "$PANE_STATE" ] && rm -f "$PANE_STATE" "$DEAD_STAMP"
            say "в панели '$PANE_NOW' — агент на месте"
            alert_task --resolve session-warden:no-agent
            ;;
        человек)
            say "в панели '$PANE_NOW', но к сессии подключён владелец (клиентов: $CLIENTS, простой ${PANE_IDLE_MIN} мин) — не вмешиваюсь"
            ;;
        сказать)
            # Человек в панели работает — команду туда не шлём. Но агента нет
            # дольше порога, и молчать об этом нельзя: харнес стоит.
            MIN_OUT=$(( ( $(date +%s) - SINCE ) / 60 ))
            say "агента нет ${MIN_OUT} мин, но в панели работает человек (простой ${PANE_IDLE_MIN} мин) — не вмешиваюсь, говорю в канал"
            TELL=1
            if [ -f "$DEAD_STAMP" ]; then
                AGE_MIN=$(( ( $(date +%s) - $(stat -c '%Y' "$DEAD_STAMP") ) / 60 ))
                [ "$AGE_MIN" -lt "$AGENT_DEAD_COOLDOWN_MIN" ] && TELL=0
            fi
            if [ "$TELL" = 1 ]; then
                tg_send "Агента нет ${MIN_OUT} мин: в tmux-панели '$PANE_NOW'. Сам не поднимаю — в панели кто-то работает (последняя активность ${PANE_IDLE_MIN} мин назад), команда испортила бы ваш ввод. Запустить: «$AGENT_START_CMD»." \
                    && date +%s > "$DEAD_STAMP" \
                    || say "сигнал о простое агента не ушёл"
            fi
            ;;
        ждём)
            [ -s "$PANE_STATE" ] || date +%s > "$PANE_STATE"
            say "в панели '$PANE_NOW' (не claude) — засёк время, порог ${AGENT_DEAD_MIN} мин"
            ;;
        поднять)
            MIN_OUT=$(( ( $(date +%s) - SINCE ) / 60 ))
            say "агент выпал в оболочку: в панели '$PANE_NOW' уже ${MIN_OUT} мин, клиентов нет — поднимаю"
            if start_agent; then
                jlog "agent_revived" "${SESSION_ID:-?}" "панель '$PANE_NOW' ${MIN_OUT} мин, поднят $AGENT_START_CMD"
                подхватить_работу || true
                rm -f "$PANE_STATE"
                # Сигнал владельцу — с кулдауном: беда та же, спам ни к чему.
                TELL=1
                if [ -f "$DEAD_STAMP" ]; then
                    AGE_MIN=$(( ( $(date +%s) - $(stat -c '%Y' "$DEAD_STAMP") ) / 60 ))
                    [ "$AGE_MIN" -lt "$AGENT_DEAD_COOLDOWN_MIN" ] && TELL=0
                fi
                if [ "$TELL" = 1 ]; then
                    tg_send "Агент выпадал в оболочку (в панели было '$PANE_NOW' ${MIN_OUT} мин) — поднял сам командой «$AGENT_START_CMD». Если это вы выходили из сессии: выход из tmux — Ctrl+B затем D, а Ctrl+C закрывает агента." \
                        && date +%s > "$DEAD_STAMP" \
                        || say "сигнал о выпавшем агенте не ушёл — агент при этом поднят"
                fi
            else
                jlog "agent_revive_failed" "${SESSION_ID:-?}" "команда «$AGENT_START_CMD» не подняла claude"
                tg_send "Агент выпал в оболочку, и поднять его командой «$AGENT_START_CMD» не удалось за ${AGENT_START_TIMEOUT_SEC}с. Нужны ваши руки: sudo -u $AGENT_USER -H tmux attach -t $TMUX_SESSION" \
                    --task session-warden:no-agent || say "и сигнал не ушёл"
                WARDEN_RC=1
            fi
            ;;
    esac
else
    # Сессии нет вовсе — с тех пор как её создают КОМАНДОЙ, это обычный вид
    # смерти агента: вышел — закрылась панель, а с ней и сессия. Юнит её не
    # вернёт (штатный выход = rc 0, у юнита Restart=on-failure), значит это
    # работа сторожа. Раньше здесь была только строчка в лог — самый глухой
    # вид простоя из возможных.
    say "tmux-сессии '$TMUX_SESSION' нет — агента нет вовсе, поднимаю сессию с агентом"
    if start_agent; then
        jlog "agent_revived" "${SESSION_ID:-?}" "сессии не было — поднята вместе с агентом ($AGENT_START_CMD)"
        подхватить_работу || true
        TELL=1
        if [ -f "$DEAD_STAMP" ]; then
            AGE_MIN=$(( ( $(date +%s) - $(stat -c '%Y' "$DEAD_STAMP") ) / 60 ))
            [ "$AGE_MIN" -lt "$AGENT_DEAD_COOLDOWN_MIN" ] && TELL=0
        fi
        if [ "$TELL" = 1 ]; then
            tg_send "Сессии агента не было совсем (панель закрылась вместе с ним) — поднял заново командой «$AGENT_START_CMD»." \
                --task session-warden:no-agent && date +%s > "$DEAD_STAMP" || say "сигнал о поднятой сессии не ушёл"
        fi
    else
        jlog "agent_revive_failed" "${SESSION_ID:-?}" "сессии не было, поднять её с агентом не удалось"
        refusal_hint
        WARDEN_RC=1
    fi
fi

# Метка heartbeat — ТОЛЬКО при полном успехе прогона.
if [ "$WARDEN_RC" = 0 ]; then
    touch "$HEARTBEAT_DIR/session-warden"
fi
exit "$WARDEN_RC"
